const c=4,n="tin-hoc",h="Tin học lớp 4",t="internal",i=[{id:"may-tinh-va-em",title:"Máy tính và em",lessons:[{id:"th4-phan-cung-phan-mem",title:"Bài 1: Phần cứng và phần mềm",weeks:[1,2],learn:[{title:"Phần cứng",text:"Phần cứng là các bộ phận của máy tính mà em nhìn thấy và chạm vào được, như màn hình, bàn phím, chuột, loa, máy in.",example:"🖥️ ⌨️ 🖱️ 🔈 🖨️"},{title:"Phần mềm",text:"Phần mềm là các chương trình chạy trên máy tính, giúp máy tính làm một việc nào đó. Em không cầm nắm được phần mềm.",example:"📝 soạn thảo · 🎨 vẽ · 🌐 trình duyệt · ⌨️ luyện gõ"},{title:"Thiết bị vào và thiết bị ra",text:"Thiết bị vào giúp đưa thông tin vào máy tính, như bàn phím, chuột, micro. Thiết bị ra đưa kết quả ra ngoài, như màn hình, loa, máy in.",example:"⌨️ 🖱️ 🎙️ ➡️ 💻 ➡️ 🖥️ 🔈 🖨️"},{title:"Thân máy",text:"Thân máy chứa bộ xử lý, là bộ phận quan trọng giúp máy tính tính toán và xử lý thông tin.",example:"🧠 bộ xử lý"}],practice:[{questions:[{id:"th4-phan-cung-phan-mem-01",type:"mc",q:"Bộ phận nào sau đây là phần cứng?",emoji:"🖱️",explain:"Con chuột là bộ phận nhìn thấy và chạm được nên là phần cứng. Các lựa chọn còn lại là phần mềm.",options:["Phần mềm vẽ tranh","Phần mềm luyện gõ phím","Trình duyệt web","Con chuột"],answer:3},{id:"th4-phan-cung-phan-mem-02",type:"mc",q:"Phần mềm là gì?",explain:"Phần mềm là các chương trình giúp máy tính làm việc, em không cầm nắm được.",options:["Các bộ phận làm bằng nhựa của máy tính","Dây điện nối máy tính với ổ cắm","Các chương trình chạy trên máy tính"],answer:2},{id:"th4-phan-cung-phan-mem-03",type:"tf",q:"Màn hình là một phần cứng của máy tính.",emoji:"🖥️",explain:"Đúng. Màn hình là bộ phận nhìn thấy, chạm được nên là phần cứng.",answer:!0},{id:"th4-phan-cung-phan-mem-04",type:"tf",q:"Em có thể cầm phần mềm soạn thảo văn bản trên tay.",explain:"Sai. Phần mềm là chương trình, em không cầm nắm được.",answer:!1},{id:"th4-phan-cung-phan-mem-05",type:"mc",q:"Thiết bị nào giúp em nghe được âm thanh từ máy tính?",emoji:"🔈",explain:"Loa phát âm thanh ra ngoài, nên loa là thiết bị ra.",options:["Loa","Bàn phím","Chuột","Micro"],answer:0},{id:"th4-phan-cung-phan-mem-06",type:"mc",q:"Thiết bị nào dùng để gõ chữ vào máy tính?",emoji:"⌨️",explain:"Bàn phím giúp em gõ chữ, số vào máy tính.",options:["Loa","Bàn phím","Máy in"],answer:1},{id:"th4-phan-cung-phan-mem-07",type:"tf",q:"Trình duyệt web là một phần cứng của máy tính.",emoji:"🌐",explain:"Sai. Trình duyệt web là chương trình dùng để xem trang web, nên là phần mềm.",answer:!1},{id:"th4-phan-cung-phan-mem-08",type:"match",q:"Ghép mỗi thứ với nhóm của nó.",explain:"Bàn phím đưa chữ vào máy, loa phát âm thanh ra ngoài, còn phần mềm vẽ là chương trình.",pairs:[["Bàn phím","Thiết bị vào"],["Loa","Thiết bị ra"],["Phần mềm vẽ","Phần mềm"]]},{id:"th4-phan-cung-phan-mem-09",type:"tf",q:"Máy in là một thiết bị ra.",emoji:"🖨️",explain:"Đúng. Máy in đưa kết quả từ máy tính ra giấy nên là thiết bị ra.",answer:!0}]},{questions:[{id:"th4-phan-cung-phan-mem-10",type:"multi",q:"Chọn tất cả các phần cứng.",explain:"Màn hình, loa, chuột là bộ phận chạm được nên là phần cứng.",options:["Phần mềm trình chiếu","Chuột","Trình duyệt web","Màn hình","Loa"],answers:[1,3,4]},{id:"th4-phan-cung-phan-mem-11",type:"multi",q:"Chọn tất cả các phần mềm.",explain:"Phần mềm soạn thảo, phần mềm vẽ và trình duyệt web là chương trình. Bàn phím và máy in là phần cứng.",options:["Trình duyệt web","Máy in","Phần mềm soạn thảo văn bản","Bàn phím","Phần mềm vẽ"],answers:[0,2,4]},{id:"th4-phan-cung-phan-mem-12",type:"mc",q:"Thiết bị nào là thiết bị vào?",emoji:"🎙️",explain:"Micro đưa tiếng nói vào máy tính nên là thiết bị vào. Loa, màn hình, máy in là thiết bị ra.",options:["Loa","Màn hình","Máy in","Micro"],answer:3},{id:"th4-phan-cung-phan-mem-13",type:"mc",q:"Thiết bị nào là thiết bị ra?",explain:"Máy in đưa kết quả ra giấy nên là thiết bị ra.",options:["Bàn phím","Máy in","Chuột"],answer:1},{id:"th4-phan-cung-phan-mem-14",type:"match",q:"Ghép thiết bị với việc nó làm.",explain:"Mỗi thiết bị có một việc riêng giúp em dùng máy tính.",pairs:[["Màn hình","Hiện hình ảnh, chữ"],["Loa","Phát ra âm thanh"],["Chuột","Điều khiển con trỏ"],["Máy in","In ra giấy"]]},{id:"th4-phan-cung-phan-mem-15",type:"tf",q:"Thân máy chứa bộ xử lý, giúp máy tính xử lý thông tin.",explain:"Đúng. Bộ xử lý nằm trong thân máy và làm nhiệm vụ xử lý thông tin.",answer:!0},{id:"th4-phan-cung-phan-mem-16",type:"tf",q:"Bàn phím là thiết bị ra vì nó hiện chữ cho em xem.",explain:"Sai. Bàn phím là thiết bị vào, giúp đưa chữ vào máy tính. Chữ hiện ra trên màn hình.",answer:!1},{id:"th4-phan-cung-phan-mem-17",type:"mc",q:"Vì sao phần mềm luyện gõ phím không phải là phần cứng?",explain:"Phần mềm là chương trình chạy trên máy tính, không chạm vào được.",options:["Vì nó rất nhỏ, khó nhìn thấy được","Vì nó nằm sẵn bên trong bàn phím","Vì nó là chương trình, không cầm được"],answer:2},{id:"th4-phan-cung-phan-mem-18",type:"tf",q:"Micro và loa đều là thiết bị vào.",explain:"Sai. Micro là thiết bị vào, còn loa là thiết bị ra.",answer:!1}]},{questions:[{id:"th4-phan-cung-phan-mem-19",type:"mc",q:"An muốn in bức tranh vừa vẽ trên máy tính ra giấy. An cần thêm thiết bị nào?",emoji:"🖨️",explain:"Máy in giúp đưa bức tranh từ máy tính ra giấy.",options:["Máy in","Micro","Loa"],answer:0},{id:"th4-phan-cung-phan-mem-20",type:"mc",q:"Bình muốn thu giọng hát của mình vào máy tính. Bình cần thiết bị nào?",emoji:"🎤",explain:"Micro là thiết bị vào, giúp đưa âm thanh vào máy tính.",options:["Micro","Loa","Máy in","Màn hình"],answer:0},{id:"th4-phan-cung-phan-mem-21",type:"mc",q:"Chi muốn vẽ một bức tranh trên máy tính. Chi cần mở loại phần mềm nào?",emoji:"🎨",explain:"Phần mềm vẽ có bút, màu và các công cụ giúp em vẽ tranh.",options:["Phần mềm luyện gõ phím","Phần mềm vẽ","Phần mềm trình chiếu"],answer:1},{id:"th4-phan-cung-phan-mem-22",type:"tf",q:"Khi loa bị hỏng, đó là phần mềm bị hỏng.",explain:"Sai. Loa là bộ phận chạm được nên là phần cứng; loa hỏng là hỏng phần cứng.",answer:!1},{id:"th4-phan-cung-phan-mem-23",type:"tf",q:"Khi bấm chuột, phần mềm vẽ không mở ra được thì chắc chắn là chuột bị hỏng.",explain:"Sai. Có thể chuột vẫn tốt mà phần mềm gặp lỗi. Cần kiểm tra cả phần cứng và phần mềm.",answer:!1},{id:"th4-phan-cung-phan-mem-24",type:"multi",q:"Dũng muốn xem một video có tiếng trên máy tính. Những thiết bị nào giúp Dũng xem và nghe?",explain:"Màn hình hiện hình ảnh, loa phát âm thanh. Máy in và micro không cần cho việc xem video.",options:["Màn hình","Loa","Máy in","Micro"],answers:[0,1]},{id:"th4-phan-cung-phan-mem-25",type:"mc",q:'Hà nói: "Nếu không có phần mềm, máy tính vẫn làm được mọi việc." Em thấy thế nào?',explain:"Phần cứng cần phần mềm điều khiển thì mới làm được việc có ích.",options:["Đúng, chỉ cần có phần cứng là đủ rồi","Đúng, vì phần mềm không quan trọng gì","Chưa đúng, máy cần phần mềm để làm việc"],answer:2},{id:"th4-phan-cung-phan-mem-26",type:"match",q:"Ghép việc em muốn làm với thứ cần dùng.",explain:"Mỗi việc cần đúng thiết bị hoặc phần mềm phù hợp.",pairs:[["Gõ một bài văn","Bàn phím"],["Nghe bài hát","Loa"],["Xem trang web","Trình duyệt web"],["Nói chuyện qua máy tính","Micro"]]},{id:"th4-phan-cung-phan-mem-27",type:"fill",q:"Điền từ còn thiếu: Bàn phím, chuột, màn hình đều là phần … của máy tính.",explain:"Đó là các bộ phận chạm được, nên gọi là phần cứng.",answer:["cứng"]}]}],challenge:{questions:[{id:"th4-phan-cung-phan-mem-28",type:"multi",q:"Chọn tất cả các thiết bị vào.",explain:"Bàn phím, chuột, micro đưa thông tin vào máy tính. Loa và màn hình là thiết bị ra.",options:["Chuột","Micro","Loa","Màn hình","Bàn phím"],answers:[0,1,4]},{id:"th4-phan-cung-phan-mem-29",type:"mc",q:"Câu nào nói đúng về phần cứng và phần mềm?",explain:"Phần mềm chạy trên phần cứng; phần cứng cần phần mềm điều khiển.",options:["Chỉ cần phần mềm, không cần phần cứng","Phần mềm là các bộ phận bằng kim loại","Hai phần phối hợp thì máy mới làm việc"],answer:2},{id:"th4-phan-cung-phan-mem-19",type:"mc",q:"An muốn in bức tranh vừa vẽ trên máy tính ra giấy. An cần thêm thiết bị nào?",emoji:"🖨️",explain:"Máy in giúp đưa bức tranh từ máy tính ra giấy.",options:["Máy in","Micro","Loa"],answer:0},{id:"th4-phan-cung-phan-mem-20",type:"mc",q:"Bình muốn thu giọng hát của mình vào máy tính. Bình cần thiết bị nào?",emoji:"🎤",explain:"Micro là thiết bị vào, giúp đưa âm thanh vào máy tính.",options:["Micro","Loa","Máy in","Màn hình"],answer:0},{id:"th4-phan-cung-phan-mem-24",type:"multi",q:"Dũng muốn xem một video có tiếng trên máy tính. Những thiết bị nào giúp Dũng xem và nghe?",explain:"Màn hình hiện hình ảnh, loa phát âm thanh. Máy in và micro không cần cho việc xem video.",options:["Màn hình","Loa","Máy in","Micro"],answers:[0,1]},{id:"th4-phan-cung-phan-mem-25",type:"mc",q:'Hà nói: "Nếu không có phần mềm, máy tính vẫn làm được mọi việc." Em thấy thế nào?',explain:"Phần cứng cần phần mềm điều khiển thì mới làm được việc có ích.",options:["Đúng, chỉ cần có phần cứng là đủ rồi","Đúng, vì phần mềm không quan trọng gì","Chưa đúng, máy cần phần mềm để làm việc"],answer:2},{id:"th4-phan-cung-phan-mem-15",type:"tf",q:"Thân máy chứa bộ xử lý, giúp máy tính xử lý thông tin.",explain:"Đúng. Bộ xử lý nằm trong thân máy và làm nhiệm vụ xử lý thông tin.",answer:!0}]},summary:["Phần cứng là các bộ phận nhìn thấy và chạm được của máy tính.","Phần mềm là các chương trình chạy trên máy tính.","Thiết bị vào đưa thông tin vào máy, thiết bị ra đưa kết quả ra ngoài."]},{id:"th4-phoi-hop-cung-mem",title:"Bài 2: Phần cứng và phần mềm phối hợp",weeks:[3,3],learn:[{title:"Cùng nhau làm việc",text:"Phần mềm chỉ chạy được khi có phần cứng. Phần cứng cần phần mềm điều khiển thì mới làm được việc có ích.",example:"💻 + 📝 = bài văn"},{title:"Khi máy gặp lỗi",text:"Máy tính có thể gặp lỗi do phần cứng (như chuột hỏng, dây lỏng) hoặc do phần mềm (như chương trình bị treo). Khi đó em nên báo người lớn.",example:"🖱️❌ · 💻⏳"},{title:"Dùng máy tính đúng cách",text:"Không tắt máy bằng cách rút điện đột ngột. Không ăn uống gần máy. Không tự ý cài hoặc xoá phần mềm.",example:"🔌❌ · 🥤❌"}],practice:[{questions:[{id:"th4-phoi-hop-cung-mem-01",type:"tf",q:"Phần mềm chỉ chạy được khi có phần cứng.",explain:"Đúng. Phần mềm cần máy tính, tức là phần cứng, để chạy.",answer:!0},{id:"th4-phoi-hop-cung-mem-02",type:"tf",q:"Phần cứng có thể tự làm mọi việc mà không cần phần mềm.",explain:"Sai. Phần cứng cần phần mềm điều khiển mới làm được việc có ích.",answer:!1},{id:"th4-phoi-hop-cung-mem-03",type:"mc",q:"Để tắt máy tính đúng cách, em nên làm gì?",emoji:"⏻",explain:"Dùng lệnh tắt máy giúp máy lưu và đóng chương trình an toàn.",options:["Dùng lệnh tắt máy trên màn hình","Rút phích cắm điện ngay","Bấm giữ nút nguồn thật lâu mỗi lần"],answer:0},{id:"th4-phoi-hop-cung-mem-04",type:"tf",q:"Em không nên để cốc nước sát bàn phím.",emoji:"🥤",explain:"Đúng. Nước đổ vào có thể làm hỏng bàn phím và máy tính.",answer:!0},{id:"th4-phoi-hop-cung-mem-05",type:"mc",q:"Chương trình bị treo, không bấm được gì. Đây là lỗi của gì?",explain:"Chương trình bị treo là lỗi của phần mềm.",options:["Bàn ghế","Phần mềm","Dây điện"],answer:1},{id:"th4-phoi-hop-cung-mem-06",type:"tf",q:"Em được tự ý cài phần mềm lạ lên máy tính của lớp.",explain:"Sai. Em cần hỏi thầy cô hoặc người lớn trước khi cài phần mềm.",answer:!1},{id:"th4-phoi-hop-cung-mem-07",type:"mc",q:"Chuột bị đứt dây nên không dùng được. Đây là lỗi của gì?",explain:"Chuột là phần cứng, đứt dây là hỏng phần cứng.",options:["Phần cứng","Phần mềm","Trang web"],answer:0},{id:"th4-phoi-hop-cung-mem-08",type:"mc",q:"Khi máy tính gặp lỗi lạ, em nên làm gì trước tiên?",explain:"Người lớn sẽ giúp em kiểm tra và sửa lỗi an toàn.",options:["Đập nhẹ vào màn hình máy","Báo thầy cô hoặc người lớn","Tự rút hết dây nối ra"],answer:1},{id:"th4-phoi-hop-cung-mem-09",type:"tf",q:"Ăn bánh khi đang gõ phím là thói quen tốt.",explain:"Sai. Vụn bánh rơi vào bàn phím có thể làm kẹt phím.",answer:!1}]},{questions:[{id:"th4-phoi-hop-cung-mem-10",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi tình huống cần xử lý đúng cách và an toàn.",pairs:[["Đổ nước lên bàn phím","Báo người lớn tắt máy, lau khô"],["Muốn tắt máy","Dùng lệnh tắt máy"],["Muốn cài trò chơi mới","Hỏi ý kiến người lớn"],["Chuột không di chuyển được","Nhờ người lớn kiểm tra dây chuột"]]},{id:"th4-phoi-hop-cung-mem-11",type:"mc",q:"Vì sao không nên rút điện để tắt máy tính?",explain:"Tắt đột ngột có thể làm mất bài đang làm và gây lỗi cho máy.",options:["Vì lần sau máy sẽ chạy nhanh hơn","Vì màn hình sẽ bị to ra hơn","Có thể làm mất bài và hỏng máy"],answer:2},{id:"th4-phoi-hop-cung-mem-12",type:"tf",q:"Khi gõ phím, chữ hiện lên màn hình là nhờ phần cứng và phần mềm cùng làm việc.",explain:"Đúng. Bàn phím, màn hình là phần cứng; phần mềm soạn thảo nhận và hiển thị chữ.",answer:!0},{id:"th4-phoi-hop-cung-mem-13",type:"multi",q:"Những việc nào giúp giữ máy tính bền lâu?",explain:"Tắt máy đúng cách, giữ sạch và để nước xa máy giúp máy bền. Đập bàn phím làm hỏng máy.",options:["Giữ bàn phím sạch sẽ","Để nước uống xa máy","Đập bàn phím khi máy chậm","Tắt máy bằng lệnh tắt máy"],answers:[0,1,3]},{id:"th4-phoi-hop-cung-mem-14",type:"mc",q:"Khi em mở phần mềm soạn thảo và gõ chữ, phần mềm đó cần phần cứng nào để hiện chữ ra?",explain:"Màn hình là thiết bị ra để hiện chữ.",options:["Loa","Màn hình","Micro"],answer:1},{id:"th4-phoi-hop-cung-mem-15",type:"tf",q:"Nếu chỉ có phần mềm mà không có máy tính thì em vẫn chơi được trò chơi trên máy tính.",explain:"Sai. Phần mềm cần phần cứng để chạy.",answer:!1},{id:"th4-phoi-hop-cung-mem-16",type:"order",q:"Sắp xếp các bước tắt máy tính đúng cách.",explain:"Lưu bài, đóng phần mềm rồi mới tắt máy để không mất dữ liệu.",items:["Lưu bài đang làm","Đóng các phần mềm đang mở","Chọn lệnh tắt máy","Chờ màn hình tắt hẳn"]},{id:"th4-phoi-hop-cung-mem-17",type:"mc",q:"Máy tính không lên hình nhưng đèn nguồn vẫn sáng. Việc em nên làm là gì?",explain:"Nhờ người lớn kiểm tra là cách an toàn nhất.",options:["Tự mở thân máy ra xem bên trong","Đổ nước lên khăn rồi lau màn hình","Nhờ người lớn kiểm tra dây màn hình"],answer:2},{id:"th4-phoi-hop-cung-mem-18",type:"tf",q:"Phần mềm luyện gõ giúp bàn phím và màn hình làm được việc dạy gõ phím.",explain:"Đúng. Phần mềm điều khiển phần cứng để làm một việc có ích.",answer:!0}]},{questions:[{id:"th4-phoi-hop-cung-mem-19",type:"mc",q:"Lan đang vẽ tranh thì chuột không di chuyển được, nhưng bàn phím vẫn gõ được. Lỗi có thể do đâu?",emoji:"🖱️",explain:"Chỉ có chuột không hoạt động nên có thể chuột bị hỏng hoặc lỏng dây.",options:["Chuột bị hỏng hoặc lỏng dây","Màn hình bị hỏng mất hình","Bàn phím bị hỏng, liệt phím"],answer:0},{id:"th4-phoi-hop-cung-mem-20",type:"mc",q:"Minh gõ bài nhưng phần mềm soạn thảo đứng im, các phần mềm khác vẫn chạy. Lỗi có thể do đâu?",explain:"Chỉ một phần mềm không chạy nên có thể chính phần mềm đó bị lỗi.",options:["Bàn phím bị gãy mất chân","Phần mềm soạn thảo bị treo","Màn hình bị vỡ một góc"],answer:1},{id:"th4-phoi-hop-cung-mem-21",type:"tf",q:"Nam thấy máy chậm nên rút điện cho nhanh. Nam làm như vậy là đúng.",explain:"Sai. Rút điện đột ngột có thể làm mất bài và hỏng máy.",answer:!1},{id:"th4-phoi-hop-cung-mem-22",type:"tf",q:"Thảo lưu bài vẽ rồi mới tắt máy. Thảo làm như vậy là đúng.",explain:"Đúng. Lưu bài trước khi tắt máy giúp không mất bài.",answer:!0},{id:"th4-phoi-hop-cung-mem-23",type:"mc",q:"Bạn rủ Phúc cài một trò chơi lạ lên máy tính của lớp. Phúc nên làm gì?",explain:"Phần mềm lạ có thể gây hại cho máy. Cần hỏi thầy cô trước.",options:["Cài ngay cho cả lớp cùng vui","Cài rồi giấu đi không cho ai biết","Hỏi ý kiến thầy cô trước"],answer:2},{id:"th4-phoi-hop-cung-mem-24",type:"multi",q:"Máy tính gặp lỗi. Những việc nào em có thể làm?",explain:"Báo người lớn và kể lại lỗi giúp sửa nhanh hơn. Tự tháo hay đập máy rất nguy hiểm.",options:["Ghi lại lỗi đã thấy","Tự tháo máy ra sửa","Đập vào máy","Báo người lớn"],answers:[0,3]},{id:"th4-phoi-hop-cung-mem-25",type:"mc",q:"Vy làm đổ nước lên bàn phím. Vy nên làm gì ngay?",emoji:"💧",explain:"Nước và điện rất nguy hiểm. Cần báo người lớn ngay.",options:["Báo người lớn để tắt máy, lau khô","Cứ tiếp tục gõ cho xong bài","Tự cầm máy sấy thổi vào ổ điện"],answer:0},{id:"th4-phoi-hop-cung-mem-26",type:"tf",q:"Khi tiếng phát ra từ loa bị rè, đó có thể là lỗi phần cứng.",explain:"Đúng. Loa là phần cứng, loa hỏng có thể làm tiếng bị rè.",answer:!0},{id:"th4-phoi-hop-cung-mem-27",type:"fill",q:"Điền từ còn thiếu: Phần mềm chỉ chạy được khi có phần … .",explain:"Phần mềm cần phần cứng để chạy.",answer:["cứng"]}]}],challenge:{questions:[{id:"th4-phoi-hop-cung-mem-28",type:"mc",q:"Câu nào đúng nhất?",explain:"Hai phần phối hợp với nhau thì máy tính mới làm việc có ích.",options:["Phần cứng và phần mềm cần nhau để máy tính làm việc","Phần cứng quan trọng hơn nên không cần phần mềm","Phần mềm chạy được trên quyển vở"],answer:0},{id:"th4-phoi-hop-cung-mem-29",type:"tf",q:"Khi máy tính bị treo, em nên bấm liên tục thật nhiều phím để máy chạy lại.",explain:"Sai. Bấm liên tục không giúp được. Em nên chờ một chút và báo người lớn.",answer:!1},{id:"th4-phoi-hop-cung-mem-19",type:"mc",q:"Lan đang vẽ tranh thì chuột không di chuyển được, nhưng bàn phím vẫn gõ được. Lỗi có thể do đâu?",emoji:"🖱️",explain:"Chỉ có chuột không hoạt động nên có thể chuột bị hỏng hoặc lỏng dây.",options:["Chuột bị hỏng hoặc lỏng dây","Màn hình bị hỏng mất hình","Bàn phím bị hỏng, liệt phím"],answer:0},{id:"th4-phoi-hop-cung-mem-20",type:"mc",q:"Minh gõ bài nhưng phần mềm soạn thảo đứng im, các phần mềm khác vẫn chạy. Lỗi có thể do đâu?",explain:"Chỉ một phần mềm không chạy nên có thể chính phần mềm đó bị lỗi.",options:["Bàn phím bị gãy mất chân","Phần mềm soạn thảo bị treo","Màn hình bị vỡ một góc"],answer:1},{id:"th4-phoi-hop-cung-mem-16",type:"order",q:"Sắp xếp các bước tắt máy tính đúng cách.",explain:"Lưu bài, đóng phần mềm rồi mới tắt máy để không mất dữ liệu.",items:["Lưu bài đang làm","Đóng các phần mềm đang mở","Chọn lệnh tắt máy","Chờ màn hình tắt hẳn"]},{id:"th4-phoi-hop-cung-mem-25",type:"mc",q:"Vy làm đổ nước lên bàn phím. Vy nên làm gì ngay?",emoji:"💧",explain:"Nước và điện rất nguy hiểm. Cần báo người lớn ngay.",options:["Báo người lớn để tắt máy, lau khô","Cứ tiếp tục gõ cho xong bài","Tự cầm máy sấy thổi vào ổ điện"],answer:0},{id:"th4-phoi-hop-cung-mem-10",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi tình huống cần xử lý đúng cách và an toàn.",pairs:[["Đổ nước lên bàn phím","Báo người lớn tắt máy, lau khô"],["Muốn tắt máy","Dùng lệnh tắt máy"],["Muốn cài trò chơi mới","Hỏi ý kiến người lớn"],["Chuột không di chuyển được","Nhờ người lớn kiểm tra dây chuột"]]}]},summary:["Phần cứng và phần mềm phối hợp thì máy tính mới làm việc.","Lỗi có thể do phần cứng hoặc phần mềm; khi gặp lỗi em báo người lớn.","Tắt máy đúng cách, giữ máy sạch và không tự ý cài phần mềm."]},{id:"th4-go-hang-tren-duoi",title:"Bài 3: Gõ phím hàng trên và hàng dưới",weeks:[4,5],learn:[{title:"Hàng phím cơ sở",text:"Hai ngón trỏ đặt lên phím F và J có gờ nổi. Các ngón còn lại đặt lần lượt lên các phím bên cạnh.",example:"A S D F · J K L ;"},{title:"Hàng phím trên",text:"Hàng phím trên có các phím Q W E R T Y U I O P. Ngón nào phụ trách phím ở hàng cơ sở thì cũng vươn lên gõ phím ngay phía trên.",example:"Q W E R T · Y U I O P"},{title:"Hàng phím dưới",text:"Hàng phím dưới có các phím Z X C V B N M. Ngón tay co xuống để gõ, gõ xong đưa về hàng cơ sở.",example:"Z X C V B · N M"},{title:"Hai ngón trỏ",text:"Ngón trỏ trái gõ R, T, F, G, V, B. Ngón trỏ phải gõ Y, U, H, J, N, M.",example:"👈 R T F G V B · Y U H J N M 👉"}],practice:[{questions:[{id:"th4-go-hang-tren-duoi-01",type:"mc",q:"Hàng phím trên gồm các phím nào?",explain:"Hàng phím trên là hàng nằm phía trên hàng phím cơ sở, bắt đầu bằng Q.",options:["A S D F G H J K L","Q W E R T Y U I O P","Z X C V B N M"],answer:1},{id:"th4-go-hang-tren-duoi-02",type:"mc",q:"Hàng phím dưới gồm các phím nào?",explain:"Hàng phím dưới nằm phía dưới hàng phím cơ sở, bắt đầu bằng Z.",options:["Q W E R T Y U I O P","A S D F G H J K L","Z X C V B N M"],answer:2},{id:"th4-go-hang-tren-duoi-03",type:"mc",q:"Hai ngón trỏ đặt lên hai phím nào ở hàng cơ sở?",explain:"Phím F và J có gờ nổi để đặt hai ngón trỏ.",options:["A và L","G và H","D và K","F và J"],answer:3},{id:"th4-go-hang-tren-duoi-04",type:"tf",q:"Sau khi gõ một phím ở hàng trên, ngón tay đưa về hàng phím cơ sở.",explain:"Đúng. Đưa ngón tay về hàng cơ sở giúp em gõ phím tiếp theo nhanh và đúng.",answer:!0},{id:"th4-go-hang-tren-duoi-05",type:"mc",q:"Phím Q được gõ bằng ngón nào?",explain:"Ngón út trái đặt ở phím A, vươn lên gõ phím Q.",options:["Ngón trỏ tay trái","Ngón út tay trái","Ngón út tay phải"],answer:1},{id:"th4-go-hang-tren-duoi-06",type:"mc",q:"Phím P được gõ bằng ngón nào?",explain:"Phím P nằm ở cuối hàng phím trên bên phải, do ngón út tay phải gõ.",options:["Ngón trỏ tay phải","Ngón út tay trái","Ngón út tay phải"],answer:2},{id:"th4-go-hang-tren-duoi-07",type:"tf",q:"Phím Z được gõ bằng ngón cái.",explain:"Sai. Phím Z được gõ bằng ngón út tay trái. Ngón cái gõ phím cách.",answer:!1},{id:"th4-go-hang-tren-duoi-08",type:"mc",q:"Phím cách được gõ bằng ngón nào?",explain:"Ngón cái đặt nhẹ trên phím cách.",options:["Ngón cái","Ngón út","Ngón giữa"],answer:0},{id:"th4-go-hang-tren-duoi-09",type:"tf",q:"Phím M nằm ở hàng phím trên.",explain:"Sai. Phím M nằm ở hàng phím dưới, cùng hàng với Z X C V B N.",answer:!1}]},{questions:[{id:"th4-go-hang-tren-duoi-10",type:"match",q:"Ghép phím với ngón gõ phím đó.",explain:"Ngón giữa trái ở D gõ E; ngón giữa phải ở K gõ I; ngón áp út trái ở S gõ W; ngón áp út phải ở L gõ O.",pairs:[["E","Ngón giữa tay trái"],["I","Ngón giữa tay phải"],["W","Ngón áp út tay trái"],["O","Ngón áp út tay phải"]]},{id:"th4-go-hang-tren-duoi-11",type:"multi",q:"Chọn tất cả các phím do ngón trỏ tay trái gõ.",explain:"Ngón trỏ trái gõ R, T, F, G, V, B. Y và N do ngón trỏ phải gõ.",options:["R","T","V","Y","N"],answers:[0,1,2]},{id:"th4-go-hang-tren-duoi-12",type:"multi",q:"Chọn tất cả các phím do ngón trỏ tay phải gõ.",explain:"Ngón trỏ phải gõ Y, U, H, J, N, M. T do ngón trỏ trái gõ, C do ngón giữa trái gõ.",options:["N","M","T","C","U"],answers:[0,1,4]},{id:"th4-go-hang-tren-duoi-13",type:"mc",q:"Phím C được gõ bằng ngón nào?",explain:"Ngón giữa trái đặt ở D, co xuống gõ phím C.",options:["Ngón trỏ tay phải","Ngón út tay trái","Ngón cái","Ngón giữa tay trái"],answer:3},{id:"th4-go-hang-tren-duoi-14",type:"mc",q:"Phím X được gõ bằng ngón nào?",explain:"Ngón áp út trái đặt ở S, co xuống gõ phím X.",options:["Ngón giữa tay phải","Ngón áp út tay trái","Ngón trỏ tay trái"],answer:1},{id:"th4-go-hang-tren-duoi-15",type:"tf",q:"Phím B được gõ bằng ngón trỏ tay trái.",explain:"Đúng. Ngón trỏ trái gõ cả V và B ở hàng phím dưới.",answer:!0},{id:"th4-go-hang-tren-duoi-16",type:"tf",q:"Phím Y được gõ bằng ngón trỏ tay trái.",explain:"Sai. Phím Y được gõ bằng ngón trỏ tay phải.",answer:!1},{id:"th4-go-hang-tren-duoi-17",type:"tf",q:"Ngón đặt ở phím D sẽ vươn lên gõ phím R.",explain:"Sai. Ngón giữa trái ở D vươn lên gõ phím E. Phím R do ngón trỏ trái gõ.",answer:!1},{id:"th4-go-hang-tren-duoi-18",type:"mc",q:"Ngón đặt ở phím K co xuống sẽ gõ phím nào ở hàng dưới?",explain:"Ngón giữa phải ở K co xuống gõ phím dấu phẩy. Phím M do ngón trỏ phải gõ.",options:["Phím M","Phím B","Phím dấu phẩy"],answer:2}]},{questions:[{id:"th4-go-hang-tren-duoi-19",type:"mc",q:'Khi gõ chữ "to", hai ngón nào được dùng?',explain:"T do ngón trỏ trái gõ, O do ngón áp út phải gõ.",options:["Ngón trỏ trái gõ T, ngón áp út phải gõ O","Ngón cái gõ cả hai chữ","Ngón út trái gõ T, ngón út phải gõ O"],answer:0},{id:"th4-go-hang-tren-duoi-20",type:"mc",q:'Khi gõ chữ "me", hai ngón nào được dùng?',explain:"M do ngón trỏ phải gõ, E do ngón giữa trái gõ.",options:["Ngón út phải gõ M, ngón út trái gõ E","Ngón trỏ phải gõ M, ngón giữa trái gõ E","Ngón trỏ trái gõ cả hai chữ"],answer:1},{id:"th4-go-hang-tren-duoi-21",type:"tf",q:'Khi gõ chữ "bo", em chỉ dùng tay trái.',explain:"Sai. B do tay trái gõ nhưng O do tay phải gõ.",answer:!1},{id:"th4-go-hang-tren-duoi-22",type:"tf",q:'Chữ "we" chỉ cần dùng các ngón của tay trái.',explain:"Đúng. W do ngón áp út trái gõ, E do ngón giữa trái gõ.",answer:!0},{id:"th4-go-hang-tren-duoi-23",type:"multi",q:'Từ "con" cần những ngón tay nào?',explain:"C: ngón giữa trái; O: ngón áp út phải; N: ngón trỏ phải.",options:["Ngón út tay trái","Ngón giữa tay trái","Ngón áp út tay phải","Ngón trỏ tay phải"],answers:[1,2,3]},{id:"th4-go-hang-tren-duoi-24",type:"mc",q:"Khoa gõ phím U bằng ngón giữa tay phải. Khoa cần sửa thế nào?",explain:"Phím U do ngón trỏ tay phải gõ.",options:["Gõ phím U bằng ngón cái tay phải","Gõ phím U bằng ngón trỏ tay trái","Gõ phím U bằng ngón trỏ tay phải"],answer:2},{id:"th4-go-hang-tren-duoi-25",type:"mc",q:"Ngọc gõ xong phím Q nhưng để ngón út ở luôn trên phím Q. Ngọc nên làm gì?",explain:"Gõ xong phải đưa ngón tay về hàng phím cơ sở.",options:["Đưa ngón út về phím A","Để nguyên trên phím Q","Đưa ngón út sang phím P"],answer:0},{id:"th4-go-hang-tren-duoi-26",type:"order",q:"Sắp xếp các bước gõ phím R đúng cách.",explain:"Bắt đầu và kết thúc đều ở hàng phím cơ sở.",items:["Đặt các ngón tay lên hàng phím cơ sở","Vươn ngón trỏ trái từ phím F lên phím R","Gõ nhẹ phím R","Đưa ngón trỏ trái về phím F"]},{id:"th4-go-hang-tren-duoi-27",type:"fill",q:"Điền chữ cái còn thiếu: Phím có gờ nổi cho ngón trỏ tay phải là phím … .",explain:"Phím J có gờ nổi cho ngón trỏ phải, phím F cho ngón trỏ trái.",answer:["J","j"]}]}],challenge:{questions:[{id:"th4-go-hang-tren-duoi-28",type:"multi",q:"Chọn tất cả các phím do ngón út tay trái gõ.",explain:"Ngón út trái gõ Q, A, Z. P do ngón út phải gõ, X do ngón áp út trái gõ.",options:["P","X","Q","A","Z"],answers:[2,3,4]},{id:"th4-go-hang-tren-duoi-29",type:"match",q:"Ghép phím ở hàng dưới với ngón gõ.",explain:"Mỗi ngón co xuống gõ phím ngay dưới phím nó đặt ở hàng cơ sở.",pairs:[["Z","Ngón út tay trái"],["X","Ngón áp út tay trái"],["C","Ngón giữa tay trái"],["M","Ngón trỏ tay phải"]]},{id:"th4-go-hang-tren-duoi-21",type:"tf",q:'Khi gõ chữ "bo", em chỉ dùng tay trái.',explain:"Sai. B do tay trái gõ nhưng O do tay phải gõ.",answer:!1},{id:"th4-go-hang-tren-duoi-23",type:"multi",q:'Từ "con" cần những ngón tay nào?',explain:"C: ngón giữa trái; O: ngón áp út phải; N: ngón trỏ phải.",options:["Ngón út tay trái","Ngón giữa tay trái","Ngón áp út tay phải","Ngón trỏ tay phải"],answers:[1,2,3]},{id:"th4-go-hang-tren-duoi-10",type:"match",q:"Ghép phím với ngón gõ phím đó.",explain:"Ngón giữa trái ở D gõ E; ngón giữa phải ở K gõ I; ngón áp út trái ở S gõ W; ngón áp út phải ở L gõ O.",pairs:[["E","Ngón giữa tay trái"],["I","Ngón giữa tay phải"],["W","Ngón áp út tay trái"],["O","Ngón áp út tay phải"]]},{id:"th4-go-hang-tren-duoi-24",type:"mc",q:"Khoa gõ phím U bằng ngón giữa tay phải. Khoa cần sửa thế nào?",explain:"Phím U do ngón trỏ tay phải gõ.",options:["Gõ phím U bằng ngón cái tay phải","Gõ phím U bằng ngón trỏ tay trái","Gõ phím U bằng ngón trỏ tay phải"],answer:2},{id:"th4-go-hang-tren-duoi-26",type:"order",q:"Sắp xếp các bước gõ phím R đúng cách.",explain:"Bắt đầu và kết thúc đều ở hàng phím cơ sở.",items:["Đặt các ngón tay lên hàng phím cơ sở","Vươn ngón trỏ trái từ phím F lên phím R","Gõ nhẹ phím R","Đưa ngón trỏ trái về phím F"]}]},summary:["Hàng phím trên bắt đầu bằng Q, hàng phím dưới bắt đầu bằng Z.","Ngón nào đặt ở phím nào thì vươn lên hoặc co xuống gõ phím cùng cột.","Gõ xong một phím, đưa ngón tay về hàng phím cơ sở."]},{id:"th4-go-muoi-ngon",title:"Bài 4: Luyện gõ mười ngón đúng tư thế",weeks:[6,6],learn:[{title:"Gõ mười ngón",text:"Gõ mười ngón là dùng đủ mười ngón tay, mỗi ngón phụ trách một số phím. Gõ đúng giúp em gõ nhanh và ít sai.",example:"🖐️ ⌨️ 🖐️"},{title:"Tư thế ngồi",text:"Ngồi thẳng lưng, hai chân đặt trên sàn, mắt nhìn thẳng vào màn hình, không cúi sát. Hai tay thả lỏng, cổ tay không tì mạnh lên bàn phím.",example:"🪑 🧍 ✅"},{title:"Không nhìn bàn phím",text:"Khi đã thuộc vị trí phím, em cố gắng nhìn màn hình thay vì nhìn bàn phím. Luyện đều mỗi ngày với phần mềm luyện gõ.",example:"👀 🖥️"}],practice:[{questions:[{id:"th4-go-muoi-ngon-01",type:"tf",q:"Gõ mười ngón là dùng đủ cả mười ngón tay để gõ phím.",explain:"Đúng. Mỗi ngón tay phụ trách một số phím nhất định.",answer:!0},{id:"th4-go-muoi-ngon-02",type:"tf",q:"Khi gõ phím, em nên cúi sát mặt vào màn hình.",explain:"Sai. Cúi sát màn hình có hại cho mắt và lưng.",answer:!1},{id:"th4-go-muoi-ngon-03",type:"mc",q:"Tư thế ngồi nào đúng khi dùng máy tính?",emoji:"🪑",explain:"Ngồi thẳng lưng giúp em không mỏi và bảo vệ mắt.",options:["Ngồi thẳng lưng, mắt nhìn thẳng màn hình","Nằm sấp trên bàn, mặt sát màn hình","Ngồi vẹo một bên, chân gác lên ghế"],answer:0},{id:"th4-go-muoi-ngon-04",type:"mc",q:"Gõ mười ngón đúng cách giúp em điều gì?",explain:"Mỗi ngón quen vị trí phím nên em gõ nhanh và chính xác.",options:["Máy tính chạy nhanh hơn","Gõ nhanh hơn và ít sai","Màn hình sáng hơn"],answer:1},{id:"th4-go-muoi-ngon-05",type:"tf",q:"Hai tay nên gồng cứng khi gõ phím.",explain:"Sai. Hai tay nên thả lỏng để gõ nhẹ nhàng và không mỏi.",answer:!1},{id:"th4-go-muoi-ngon-06",type:"tf",q:"Chỉ cần dùng hai ngón trỏ để gõ là gõ mười ngón.",explain:"Sai. Gõ mười ngón phải dùng đủ mười ngón tay.",answer:!1},{id:"th4-go-muoi-ngon-07",type:"mc",q:"Khi luyện gõ, em nên gõ phím như thế nào?",explain:"Gõ nhẹ, dứt khoát giúp bàn phím bền và chữ không bị lặp.",options:["Đập thật mạnh","Giữ phím thật lâu","Gõ nhẹ, dứt khoát"],answer:2},{id:"th4-go-muoi-ngon-08",type:"mc",q:"Phần mềm nào giúp em tập gõ mười ngón?",emoji:"⌨️",explain:"Phần mềm luyện gõ có bài tập gõ từng hàng phím.",options:["Phần mềm vẽ","Trình duyệt web","Phần mềm luyện gõ phím"],answer:2},{id:"th4-go-muoi-ngon-09",type:"tf",q:"Hai chân nên đặt trên sàn hoặc chỗ để chân khi ngồi gõ phím.",explain:"Đúng. Đặt chân vững giúp em ngồi thẳng và thoải mái.",answer:!0}]},{questions:[{id:"th4-go-muoi-ngon-10",type:"mc",q:"Vì sao nên cố gắng không nhìn bàn phím khi gõ?",explain:"Nhìn màn hình giúp em thấy ngay chữ gõ sai.",options:["Để bàn phím không bị bẩn và bám bụi","Để thấy chữ sai trên màn hình, gõ nhanh hơn","Để máy tính chạy nhanh và mát hơn"],answer:1},{id:"th4-go-muoi-ngon-11",type:"multi",q:"Những việc nào là tư thế ngồi đúng?",explain:"Lưng thẳng, mắt nhìn thẳng, chân đặt trên sàn là tư thế đúng.",options:["Gác chân lên ghế","Lưng thẳng","Mắt nhìn thẳng màn hình","Chân đặt trên sàn"],answers:[1,2,3]},{id:"th4-go-muoi-ngon-12",type:"tf",q:"Thuộc vị trí phím giúp em gõ mà ít phải nhìn bàn phím.",explain:"Đúng. Khi các ngón tay nhớ vị trí phím, em có thể nhìn màn hình khi gõ.",answer:!0},{id:"th4-go-muoi-ngon-13",type:"tf",q:"Gõ càng mạnh thì càng nhanh.",explain:"Sai. Gõ mạnh làm mỏi tay và dễ hỏng phím. Gõ nhẹ và đều mới nhanh.",answer:!1},{id:"th4-go-muoi-ngon-14",type:"mc",q:"Ngồi máy tính lâu, em nên làm gì?",explain:"Nghỉ ngơi giúp mắt và cơ thể đỡ mệt.",options:["Nghỉ giải lao, nhìn ra xa cho mắt nghỉ","Ngồi liền nhiều giờ cho xong việc","Dụi mắt thật mạnh rồi ngồi tiếp"],answer:0},{id:"th4-go-muoi-ngon-15",type:"order",q:"Sắp xếp các bước chuẩn bị luyện gõ.",explain:"Ngồi đúng, đặt tay đúng rồi mới bắt đầu gõ.",items:["Ngồi thẳng lưng trước máy tính","Đặt hai ngón trỏ lên phím F và J","Đặt các ngón còn lại lên hàng phím cơ sở","Bắt đầu gõ theo bài luyện"]},{id:"th4-go-muoi-ngon-16",type:"mc",q:"Ngón cái đặt ở đâu khi chuẩn bị gõ?",explain:"Hai ngón cái đặt nhẹ trên phím cách.",options:["Trên phím Enter","Trên phím cách","Dưới gầm bàn"],answer:1},{id:"th4-go-muoi-ngon-17",type:"tf",q:"Cổ tay nên tì thật mạnh lên mép bàn phím.",explain:"Sai. Cổ tay nên thả lỏng, không tì mạnh, để tay không mỏi.",answer:!1},{id:"th4-go-muoi-ngon-18",type:"mc",q:"Muốn gõ giỏi, cách tốt nhất là gì?",explain:"Luyện đều mỗi ngày giúp các ngón tay nhớ vị trí phím.",options:["Luyện tập đều đặn mỗi ngày một ít","Chỉ luyện một lần thật lâu là đủ","Chỉ ngồi xem bạn khác gõ phím"],answer:0}]},{questions:[{id:"th4-go-muoi-ngon-19",type:"mc",q:"Tùng gõ bằng hai ngón trỏ và luôn nhìn bàn phím. Em khuyên Tùng thế nào?",explain:"Gõ mười ngón giúp Tùng gõ nhanh và không phải nhìn bàn phím.",options:["Cứ gõ hai ngón như vậy là tốt nhất","Chỉ cần gõ mạnh tay hơn nữa là được","Tập đặt tay ở hàng cơ sở, gõ mười ngón"],answer:2},{id:"th4-go-muoi-ngon-20",type:"mc",q:"Vy thấy mỏi mắt sau khi ngồi máy tính lâu. Vy nên làm gì?",emoji:"👀",explain:"Nghỉ ngơi và nhìn ra xa giúp mắt thư giãn.",options:["Cúi sát màn hình hơn","Tăng độ sáng màn hình thật cao","Dừng lại nghỉ, nhìn ra xa"],answer:2},{id:"th4-go-muoi-ngon-21",type:"tf",q:"An ngồi vẹo người để gõ cho nhanh. An ngồi như vậy là đúng.",explain:"Sai. Ngồi vẹo người lâu sẽ đau lưng. An cần ngồi thẳng lưng.",answer:!1},{id:"th4-go-muoi-ngon-22",type:"tf",q:"Bình mỗi ngày luyện gõ một ít với phần mềm luyện gõ. Bình làm như vậy là tốt.",explain:"Đúng. Luyện đều đặn giúp Bình gõ ngày càng nhanh và đúng.",answer:!0},{id:"th4-go-muoi-ngon-23",type:"multi",q:"Chi muốn gõ nhanh và ít sai. Chi nên làm những việc nào?",explain:"Đặt tay đúng, dùng đúng ngón và luyện đều giúp gõ nhanh, ít sai.",options:["Đặt tay đúng hàng phím cơ sở","Dùng đúng ngón cho từng phím","Luyện tập mỗi ngày","Chỉ dùng một ngón"],answers:[0,1,2]},{id:"th4-go-muoi-ngon-24",type:"mc",q:'Dũng gõ chữ "a" thành "s" nhiều lần. Có thể Dũng đã làm sai điều gì?',explain:"Khi tay đặt lệch một phím, chữ gõ ra sẽ sai. Hãy tìm gờ nổi ở F và J để đặt lại tay.",options:["Đặt các ngón tay lệch khỏi hàng cơ sở","Màn hình máy tính để quá to","Ngồi thẳng lưng khi gõ phím"],answer:0},{id:"th4-go-muoi-ngon-25",type:"match",q:"Ghép thói quen với kết quả.",explain:"Mỗi thói quen tốt mang lại một lợi ích cho em.",pairs:[["Gõ mười ngón","Gõ nhanh hơn"],["Ngồi thẳng lưng","Không đau lưng"],["Nghỉ giải lao","Mắt đỡ mỏi"],["Gõ nhẹ phím","Bàn phím bền hơn"]]},{id:"th4-go-muoi-ngon-26",type:"tf",q:"Khi đã gõ thành thạo, em có thể nhìn màn hình thay vì nhìn bàn phím.",explain:"Đúng. Nhìn màn hình giúp em thấy và sửa lỗi ngay.",answer:!0},{id:"th4-go-muoi-ngon-27",type:"fill",q:"Điền số còn thiếu: Gõ … ngón là dùng đủ các ngón của hai bàn tay.",explain:"Hai bàn tay có mười ngón, gõ mười ngón là dùng đủ cả mười ngón.",answer:["mười","10"]}]}],challenge:{questions:[{id:"th4-go-muoi-ngon-28",type:"mc",q:"Câu nào đúng về luyện gõ mười ngón?",explain:"Gõ đúng trước, nhanh sau. Các ngón tay sẽ quen dần.",options:["Phải gõ thật nhanh ngay từ đầu dù sai nhiều","Lúc đầu gõ chậm nhưng đúng, sau sẽ nhanh dần","Gõ sai không cần sửa"],answer:1},{id:"th4-go-muoi-ngon-29",type:"tf",q:"Đặt tay đúng hàng phím cơ sở trước khi gõ giúp em gõ ít sai hơn.",explain:"Đúng. Từ hàng cơ sở, mỗi ngón biết đường vươn tới phím của mình.",answer:!0},{id:"th4-go-muoi-ngon-19",type:"mc",q:"Tùng gõ bằng hai ngón trỏ và luôn nhìn bàn phím. Em khuyên Tùng thế nào?",explain:"Gõ mười ngón giúp Tùng gõ nhanh và không phải nhìn bàn phím.",options:["Cứ gõ hai ngón như vậy là tốt nhất","Chỉ cần gõ mạnh tay hơn nữa là được","Tập đặt tay ở hàng cơ sở, gõ mười ngón"],answer:2},{id:"th4-go-muoi-ngon-24",type:"mc",q:'Dũng gõ chữ "a" thành "s" nhiều lần. Có thể Dũng đã làm sai điều gì?',explain:"Khi tay đặt lệch một phím, chữ gõ ra sẽ sai. Hãy tìm gờ nổi ở F và J để đặt lại tay.",options:["Đặt các ngón tay lệch khỏi hàng cơ sở","Màn hình máy tính để quá to","Ngồi thẳng lưng khi gõ phím"],answer:0},{id:"th4-go-muoi-ngon-23",type:"multi",q:"Chi muốn gõ nhanh và ít sai. Chi nên làm những việc nào?",explain:"Đặt tay đúng, dùng đúng ngón và luyện đều giúp gõ nhanh, ít sai.",options:["Đặt tay đúng hàng phím cơ sở","Dùng đúng ngón cho từng phím","Luyện tập mỗi ngày","Chỉ dùng một ngón"],answers:[0,1,2]},{id:"th4-go-muoi-ngon-25",type:"match",q:"Ghép thói quen với kết quả.",explain:"Mỗi thói quen tốt mang lại một lợi ích cho em.",pairs:[["Gõ mười ngón","Gõ nhanh hơn"],["Ngồi thẳng lưng","Không đau lưng"],["Nghỉ giải lao","Mắt đỡ mỏi"],["Gõ nhẹ phím","Bàn phím bền hơn"]]},{id:"th4-go-muoi-ngon-16",type:"mc",q:"Ngón cái đặt ở đâu khi chuẩn bị gõ?",explain:"Hai ngón cái đặt nhẹ trên phím cách.",options:["Trên phím Enter","Trên phím cách","Dưới gầm bàn"],answer:1}]},summary:["Gõ mười ngón giúp gõ nhanh và chính xác.","Ngồi thẳng lưng, mắt nhìn thẳng màn hình, tay thả lỏng.","Luyện gõ đều đặn và nghỉ giải lao để bảo vệ mắt."]}]},{id:"mang-may-tinh-internet",title:"Mạng máy tính và Internet",lessons:[{id:"th4-thong-tin-trang-web",title:"Bài 5: Thông tin trên trang web",weeks:[7,8],learn:[{title:"Trang web",text:"Trang web là nơi đưa thông tin lên Internet. Em dùng phần mềm trình duyệt web để mở và xem trang web.",example:"🌐 trình duyệt → 📄 trang web"},{title:"Các dạng thông tin",text:"Trang web có thể có chữ, hình ảnh, âm thanh và video.",example:"🔤 chữ · 🖼️ hình ảnh · 🎵 âm thanh · 🎬 video"},{title:"Siêu liên kết",text:"Siêu liên kết là chữ hoặc hình mà khi nháy chuột vào sẽ mở ra trang web khác. Đưa chuột vào siêu liên kết, con trỏ thường đổi thành hình bàn tay.",example:"👆 nháy vào → trang mới"},{title:"Địa chỉ trang web",text:"Mỗi trang web có một địa chỉ riêng. Gõ địa chỉ vào ô địa chỉ của trình duyệt rồi nhấn Enter để mở trang.",example:"🔗 ô địa chỉ + Enter"}],practice:[{questions:[{id:"th4-thong-tin-trang-web-01",type:"mc",q:"Phần mềm dùng để xem trang web gọi là gì?",emoji:"🌐",explain:"Trình duyệt web giúp em mở và xem trang web.",options:["Phần mềm vẽ","Phần mềm luyện gõ","Phần mềm trình chiếu","Trình duyệt web"],answer:3},{id:"th4-thong-tin-trang-web-02",type:"multi",q:"Trang web có thể có những dạng thông tin nào?",explain:"Trang web có thể có chữ, hình ảnh, âm thanh và video. Máy tính không gửi được mùi hương.",options:["Video","Mùi hương","Chữ","Hình ảnh","Âm thanh"],answers:[0,2,3,4]},{id:"th4-thong-tin-trang-web-03",type:"tf",q:"Siêu liên kết giúp mở ra một trang web khác khi nháy chuột vào.",explain:"Đúng. Đó là tác dụng của siêu liên kết.",answer:!0},{id:"th4-thong-tin-trang-web-04",type:"tf",q:"Trang web chỉ có chữ, không có hình ảnh.",explain:"Sai. Trang web có thể có chữ, hình ảnh, âm thanh và video.",answer:!1},{id:"th4-thong-tin-trang-web-05",type:"mc",q:"Khi đưa chuột vào siêu liên kết, con trỏ chuột thường có hình gì?",emoji:"👆",explain:"Con trỏ hình bàn tay báo cho em biết đó là siêu liên kết.",options:["Đồng hồ cát","Bàn tay","Cây bút"],answer:1},{id:"th4-thong-tin-trang-web-06",type:"tf",q:"Mọi trang web đều dùng chung một địa chỉ.",explain:"Sai. Mỗi trang web có một địa chỉ riêng.",answer:!1},{id:"th4-thong-tin-trang-web-07",type:"mc",q:"Muốn mở trang web khi biết địa chỉ, em gõ địa chỉ vào đâu?",explain:"Gõ địa chỉ vào ô địa chỉ rồi nhấn Enter.",options:["Ô địa chỉ của trình duyệt","Khung vẽ của phần mềm vẽ","Cửa sổ của Thùng rác"],answer:0},{id:"th4-thong-tin-trang-web-08",type:"tf",q:"Siêu liên kết chỉ có thể là chữ, không thể là hình ảnh.",explain:"Sai. Siêu liên kết có thể là chữ hoặc hình ảnh.",answer:!1},{id:"th4-thong-tin-trang-web-09",type:"mc",q:"Sau khi gõ địa chỉ trang web vào ô địa chỉ, em nhấn phím nào để mở trang?",explain:"Nhấn Enter để trình duyệt mở trang web.",options:["Phím cách","Phím A","Enter"],answer:2}]},{questions:[{id:"th4-thong-tin-trang-web-10",type:"match",q:"Ghép nội dung với dạng thông tin.",explain:"Mỗi nội dung trên trang web thuộc một dạng thông tin.",pairs:[["Bài hát thiếu nhi","Âm thanh"],["Bức ảnh con mèo","Hình ảnh"],["Đoạn phim hoạt hình","Video"],["Bài đọc về loài cá","Chữ"]]},{id:"th4-thong-tin-trang-web-11",type:"mc",q:"Một trang web có đoạn phim dạy gấp giấy. Đó là dạng thông tin nào?",emoji:"🎬",explain:"Đoạn phim có hình chuyển động và tiếng là video.",options:["Chữ","Video","Âm thanh"],answer:1},{id:"th4-thong-tin-trang-web-12",type:"tf",q:"Trang web giúp em đọc tin tức, học bài và xem tranh ảnh.",explain:"Đúng. Trang web có nhiều thông tin bổ ích.",answer:!0},{id:"th4-thong-tin-trang-web-13",type:"order",q:"Sắp xếp các bước mở một trang web khi biết địa chỉ.",explain:"Mở trình duyệt, gõ địa chỉ vào ô địa chỉ rồi nhấn Enter.",items:["Mở trình duyệt web","Nháy chuột vào ô địa chỉ","Gõ địa chỉ trang web","Nhấn phím Enter"]},{id:"th4-thong-tin-trang-web-14",type:"mc",q:"Vì sao con trỏ đổi thành hình bàn tay khi đưa vào một dòng chữ?",explain:"Con trỏ hình bàn tay báo hiệu có siêu liên kết.",options:["Vì máy tính đang bị hỏng chuột","Vì dòng chữ đó bị viết sai chính tả","Vì dòng chữ đó là siêu liên kết"],answer:2},{id:"th4-thong-tin-trang-web-15",type:"tf",q:"Nháy vào siêu liên kết luôn mở ra một trò chơi.",explain:"Sai. Siêu liên kết mở ra một trang web khác, có thể là bài đọc, hình ảnh hay video.",answer:!1},{id:"th4-thong-tin-trang-web-16",type:"multi",q:"Những việc nào làm được với trình duyệt web?",explain:"Trình duyệt giúp xem web, mở liên kết, gõ địa chỉ. Muốn in ra giấy thì cần máy in.",options:["Xem trang web","Nháy vào siêu liên kết","Gõ địa chỉ trang web","In ra giấy mà không cần máy in"],answers:[0,1,2]},{id:"th4-thong-tin-trang-web-17",type:"mc",q:"Trên trang web có hình một chú voi, nháy vào thì mở trang nói về loài voi. Hình đó là gì?",emoji:"🐘",explain:"Hình ảnh nháy vào mở ra trang khác là siêu liên kết.",options:["Một video","Một âm thanh","Một tệp bị lỗi","Một siêu liên kết"],answer:3},{id:"th4-thong-tin-trang-web-18",type:"tf",q:"Trên trang web, chữ và hình ảnh có thể nằm cùng nhau.",explain:"Đúng. Một trang web có thể có cả chữ, hình ảnh, âm thanh và video.",answer:!0}]},{questions:[{id:"th4-thong-tin-trang-web-19",type:"mc",q:"Lan muốn nghe tiếng hót của chim chích bông trên trang web. Lan cần tìm dạng thông tin nào?",emoji:"🐦",explain:"Tiếng chim hót là thông tin dạng âm thanh.",options:["Âm thanh","Chữ","Hình ảnh"],answer:0},{id:"th4-thong-tin-trang-web-20",type:"mc",q:'Minh đang đọc bài về Mặt Trăng, thấy dòng chữ "Xem thêm về Mặt Trời". Nháy vào đó sẽ thế nào?',emoji:"☀️",explain:"Dòng chữ đó là siêu liên kết, dẫn tới trang nói về Mặt Trời.",options:["Tắt máy tính ngay lập tức","Mở trang nói về Mặt Trời","Xoá mất bài đang đọc dở"],answer:1},{id:"th4-thong-tin-trang-web-21",type:"tf",q:"Nam muốn xem lại trang trước đó. Nam có thể dùng nút quay lại của trình duyệt.",explain:"Đúng. Nút quay lại đưa em về trang vừa xem.",answer:!0},{id:"th4-thong-tin-trang-web-22",type:"tf",q:"Muốn xem video trên trang web có tiếng, chỉ cần máy in là đủ.",explain:"Sai. Cần màn hình để xem hình và loa để nghe tiếng.",answer:!1},{id:"th4-thong-tin-trang-web-23",type:"multi",q:"Hà làm bài giới thiệu về con mèo. Hà có thể lấy những dạng thông tin nào trên trang web?",explain:"Trang web có cả chữ, ảnh, âm thanh, video về con mèo.",options:["Bài viết về mèo","Ảnh con mèo","Tiếng mèo kêu","Video mèo chơi đùa"],answers:[0,1,2,3]},{id:"th4-thong-tin-trang-web-24",type:"mc",q:"Thảo gõ địa chỉ trang web nhưng gõ sai một chữ. Điều gì có thể xảy ra?",explain:"Mỗi trang có địa chỉ riêng, gõ sai địa chỉ thì không đến đúng trang.",options:["Trang vẫn mở ra đúng như thường","Máy tính tự tắt và khởi động lại","Không mở được hoặc mở nhầm trang khác"],answer:2},{id:"th4-thong-tin-trang-web-25",type:"mc",q:"Trang web về thời tiết có bảng số đo nhiệt độ và hình mây mưa. Trang đó có những dạng thông tin nào?",emoji:"🌦️",explain:"Bảng số đo là chữ và số, hình mây mưa là hình ảnh.",options:["Chữ và hình ảnh","Chỉ có âm thanh","Chỉ có video"],answer:0},{id:"th4-thong-tin-trang-web-26",type:"tf",q:"Mỗi trang web chỉ được có đúng một siêu liên kết.",explain:"Sai. Trang web thường có nhiều siêu liên kết dẫn tới các trang khác nhau.",answer:!1},{id:"th4-thong-tin-trang-web-27",type:"fill",q:"Điền từ còn thiếu: Chữ hoặc hình nháy vào mở ra trang khác gọi là siêu … .",explain:"Đó là siêu liên kết.",answer:["liên kết"]}]}],challenge:{questions:[{id:"th4-thong-tin-trang-web-28",type:"order",q:"Sắp xếp các việc để xem một video về cá heo khi đã có trang web.",explain:"Mở trình duyệt, vào trang, nháy vào video rồi xem.",items:["Mở trình duyệt web","Mở trang web có video về cá heo","Nháy vào video","Xem và nghe video"]},{id:"th4-thong-tin-trang-web-29",type:"tf",q:"Khi nháy vào siêu liên kết, trang mới có thể mở ra ở một thẻ mới của trình duyệt.",explain:"Đúng. Có siêu liên kết mở trang mới ngay tại chỗ, có cái mở ở thẻ mới.",answer:!0},{id:"th4-thong-tin-trang-web-19",type:"mc",q:"Lan muốn nghe tiếng hót của chim chích bông trên trang web. Lan cần tìm dạng thông tin nào?",emoji:"🐦",explain:"Tiếng chim hót là thông tin dạng âm thanh.",options:["Âm thanh","Chữ","Hình ảnh"],answer:0},{id:"th4-thong-tin-trang-web-23",type:"multi",q:"Hà làm bài giới thiệu về con mèo. Hà có thể lấy những dạng thông tin nào trên trang web?",explain:"Trang web có cả chữ, ảnh, âm thanh, video về con mèo.",options:["Bài viết về mèo","Ảnh con mèo","Tiếng mèo kêu","Video mèo chơi đùa"],answers:[0,1,2,3]},{id:"th4-thong-tin-trang-web-24",type:"mc",q:"Thảo gõ địa chỉ trang web nhưng gõ sai một chữ. Điều gì có thể xảy ra?",explain:"Mỗi trang có địa chỉ riêng, gõ sai địa chỉ thì không đến đúng trang.",options:["Trang vẫn mở ra đúng như thường","Máy tính tự tắt và khởi động lại","Không mở được hoặc mở nhầm trang khác"],answer:2},{id:"th4-thong-tin-trang-web-13",type:"order",q:"Sắp xếp các bước mở một trang web khi biết địa chỉ.",explain:"Mở trình duyệt, gõ địa chỉ vào ô địa chỉ rồi nhấn Enter.",items:["Mở trình duyệt web","Nháy chuột vào ô địa chỉ","Gõ địa chỉ trang web","Nhấn phím Enter"]},{id:"th4-thong-tin-trang-web-16",type:"multi",q:"Những việc nào làm được với trình duyệt web?",explain:"Trình duyệt giúp xem web, mở liên kết, gõ địa chỉ. Muốn in ra giấy thì cần máy in.",options:["Xem trang web","Nháy vào siêu liên kết","Gõ địa chỉ trang web","In ra giấy mà không cần máy in"],answers:[0,1,2]}]},summary:["Trình duyệt web giúp mở và xem trang web.","Trang web có chữ, hình ảnh, âm thanh và video.","Siêu liên kết là chữ hoặc hình, nháy vào sẽ mở trang khác."]},{id:"th4-xem-web-an-toan",title:"Bài 6: Xem trang web an toàn",weeks:[9,9],learn:[{title:"Thông tin có ích và không phù hợp",text:"Trên Internet có nhiều thông tin bổ ích, nhưng cũng có thông tin không phù hợp với trẻ em, thông tin sai hoặc lừa đảo.",example:"✅ bổ ích · ⚠️ không phù hợp"},{title:"Quảng cáo và cửa sổ lạ",text:"Không nháy vào quảng cáo lạ, cửa sổ báo trúng thưởng hay lời mời tải phần mềm. Hãy đóng lại và báo người lớn.",example:"🎁❌ · 🪟❌"},{title:"Giữ thông tin riêng",text:"Không đưa họ tên đầy đủ, địa chỉ nhà, số điện thoại, mật khẩu lên mạng khi chưa hỏi bố mẹ.",example:"🏠 📞 🔑 ➡️ 🔒"},{title:"Khi thấy điều lạ",text:"Gặp nội dung làm em sợ hoặc khó chịu, hãy đóng trang và kể ngay với bố mẹ, thầy cô.",example:"😟 → 👨‍👩‍👧"}],practice:[{questions:[{id:"th4-xem-web-an-toan-01",type:"tf",q:"Mọi thông tin trên Internet đều đúng và phù hợp với trẻ em.",explain:"Sai. Có thông tin sai hoặc không phù hợp, em cần cẩn thận.",answer:!1},{id:"th4-xem-web-an-toan-02",type:"mc",q:'Một cửa sổ hiện lên báo "Bạn đã trúng thưởng, nháy vào đây!". Em nên làm gì?',emoji:"🎁",explain:"Đây thường là lừa đảo. Không nháy vào và báo người lớn.",options:["Nháy vào ngay để nhận quà","Gõ địa chỉ nhà vào","Không nháy vào, báo người lớn"],answer:2},{id:"th4-xem-web-an-toan-03",type:"tf",q:"Em có thể cho người lạ trên mạng biết địa chỉ nhà nếu họ nói chuyện vui vẻ.",emoji:"🏠",explain:"Sai. Địa chỉ nhà là thông tin riêng, không cho người lạ biết.",answer:!1},{id:"th4-xem-web-an-toan-04",type:"mc",q:"Thông tin nào em cần giữ bí mật trên mạng?",emoji:"🔑",explain:"Mật khẩu chỉ mình em và bố mẹ biết.",options:["Tên con vật em thích","Mật khẩu","Màu em thích"],answer:1},{id:"th4-xem-web-an-toan-05",type:"tf",q:"Khi thấy nội dung làm em sợ hãi, em nên đóng trang và kể với người lớn.",explain:"Đúng. Người lớn sẽ giúp em và bảo vệ em.",answer:!0},{id:"th4-xem-web-an-toan-06",type:"mc",q:"Khi muốn tải một phần mềm từ trang web, em nên làm gì?",explain:"Phần mềm lạ có thể có hại cho máy. Hỏi người lớn trước.",options:["Hỏi ý kiến bố mẹ hoặc thầy cô","Tải ngay mà không cần hỏi ai","Tải thật nhiều phần mềm về máy"],answer:0},{id:"th4-xem-web-an-toan-07",type:"tf",q:"Nháy vào mọi quảng cáo trên trang web là việc nên làm.",explain:"Sai. Quảng cáo lạ có thể dẫn tới trang không an toàn.",answer:!1},{id:"th4-xem-web-an-toan-08",type:"mc",q:"Ai nên ở bên cạnh khi em mới tập xem trang web?",explain:"Có người lớn bên cạnh giúp em xem web an toàn.",options:["Người lạ trên mạng","Không cần ai cả","Bố mẹ hoặc thầy cô"],answer:2},{id:"th4-xem-web-an-toan-09",type:"tf",q:"Số điện thoại của bố mẹ là thông tin không nên đưa lên mạng.",emoji:"📞",explain:"Đúng. Đó là thông tin riêng của gia đình.",answer:!0}]},{questions:[{id:"th4-xem-web-an-toan-10",type:"multi",q:"Những thông tin nào là thông tin riêng, không nên đưa lên mạng?",explain:"Địa chỉ nhà, mật khẩu, số điện thoại là thông tin riêng cần giữ kín.",options:["Số điện thoại","Tên loài hoa em thích","Địa chỉ nhà","Mật khẩu"],answers:[0,2,3]},{id:"th4-xem-web-an-toan-11",type:"match",q:"Ghép tình huống với cách xử lý.",explain:"Mỗi tình huống lạ đều cần cẩn thận và nhờ người lớn giúp.",pairs:[["Cửa sổ báo trúng thưởng","Đóng lại, không nháy vào"],["Người lạ hỏi địa chỉ nhà","Không trả lời, báo bố mẹ"],["Trang web có hình ảnh đáng sợ","Đóng trang, kể với người lớn"],["Muốn tải trò chơi mới","Hỏi ý kiến người lớn"]]},{id:"th4-xem-web-an-toan-12",type:"mc",q:"Vì sao không nên nháy vào quảng cáo lạ?",explain:"Quảng cáo lạ có thể chứa nội dung không an toàn.",options:["Có thể dẫn tới trang lừa đảo, hại máy","Vì quảng cáo luôn có chữ rất đẹp","Vì máy tính sẽ chạy nhanh hơn nhiều"],answer:0},{id:"th4-xem-web-an-toan-13",type:"tf",q:"Trang web của trường học, thư viện thường có thông tin bổ ích cho học sinh.",explain:"Đúng. Đó là những nơi đáng tin cậy để tìm thông tin học tập.",answer:!0},{id:"th4-xem-web-an-toan-14",type:"tf",q:"Nếu một trang web nói điều gì thì điều đó chắc chắn đúng.",explain:"Sai. Có trang đưa tin sai. Em nên hỏi người lớn hoặc xem thêm nguồn khác.",answer:!1},{id:"th4-xem-web-an-toan-15",type:"mc",q:"Một trang web yêu cầu em nhập mật khẩu để nhận quà. Em làm gì?",explain:"Không bao giờ đưa mật khẩu để đổi lấy quà, đó thường là lừa đảo.",options:["Nhập mật khẩu ngay","Không nhập, báo người lớn","Nhập mật khẩu của bạn"],answer:1},{id:"th4-xem-web-an-toan-16",type:"multi",q:"Những thói quen nào giúp em xem web an toàn?",explain:"Kết bạn với người lạ trên mạng là không an toàn.",options:["Xem web khi có người lớn cho phép","Không nháy vào quảng cáo lạ","Giữ kín mật khẩu","Kết bạn với mọi người lạ"],answers:[0,1,2]},{id:"th4-xem-web-an-toan-17",type:"tf",q:"Em nên đặt giờ xem web hợp lý, không ngồi quá lâu.",explain:"Đúng. Ngồi quá lâu có hại cho mắt và sức khỏe.",answer:!0},{id:"th4-xem-web-an-toan-18",type:"mc",q:"Khi đọc một tin lạ trên mạng, em nên làm gì?",explain:"Hỏi người lớn giúp em biết tin đúng hay sai.",options:["Hỏi người lớn xem tin đó có đúng không","Chia sẻ ngay cho tất cả bạn bè","Tin ngay mà không cần hỏi lại ai"],answer:0}]},{questions:[{id:"th4-xem-web-an-toan-19",type:"mc",q:"Khoa đang xem video học vẽ thì hiện lên quảng cáo nhấp nháy mời tải trò chơi. Khoa nên làm gì?",explain:"Không nháy vào quảng cáo lạ để giữ an toàn cho máy và cho mình.",options:["Nháy vào để tải trò chơi về","Bỏ qua, không nháy vào quảng cáo","Gửi quảng cáo đó cho các bạn"],answer:1},{id:"th4-xem-web-an-toan-20",type:"mc",q:"Một người lạ nhắn tin cho Ngọc trên mạng, rủ gặp mặt. Ngọc nên làm gì?",explain:"Không bao giờ gặp người lạ quen trên mạng. Phải báo bố mẹ.",options:["Đi gặp một mình","Cho người đó địa chỉ nhà","Không đi, kể ngay với bố mẹ"],answer:2},{id:"th4-xem-web-an-toan-21",type:"tf",q:"Phúc thấy một trang web có nội dung không phù hợp. Phúc đóng trang và kể với cô giáo. Phúc làm đúng.",explain:"Đúng. Đóng trang và kể với người lớn là cách xử lý an toàn.",answer:!0},{id:"th4-xem-web-an-toan-22",type:"tf",q:"Vy đăng ảnh nhà mình kèm địa chỉ lên mạng để khoe với mọi người. Vy làm như vậy là an toàn.",explain:"Sai. Địa chỉ nhà là thông tin riêng, không nên đưa lên mạng.",answer:!1},{id:"th4-xem-web-an-toan-23",type:"mc",q:'Tùng đọc được tin "Ngày mai được nghỉ học" trên một trang lạ. Tùng nên làm gì?',explain:"Tin trên trang lạ có thể sai. Cần hỏi người có trách nhiệm.",options:["Báo cả lớp nghỉ học","Tin ngay và không đi học","Hỏi lại thầy cô hoặc bố mẹ"],answer:2},{id:"th4-xem-web-an-toan-24",type:"multi",q:"An muốn tìm hiểu về loài cá heo trên mạng. Những việc nào An nên làm?",emoji:"🐬",explain:"Chọn trang đáng tin, nhờ người lớn và bỏ qua cửa sổ lạ giúp An an toàn.",options:["Nhờ bố mẹ giúp chọn trang","Nháy vào mọi quảng cáo","Bỏ qua các cửa sổ lạ","Xem trang web của bảo tàng, thư viện"],answers:[0,2,3]},{id:"th4-xem-web-an-toan-25",type:"mc",q:'Bạn xin mật khẩu tài khoản học tập của Minh để "chơi giúp". Minh nên làm gì?',explain:"Mật khẩu là thông tin riêng, không đưa cho người khác.",options:["Cho ngay vì là bạn","Không cho, giữ kín mật khẩu","Viết mật khẩu lên bảng lớp"],answer:1},{id:"th4-xem-web-an-toan-26",type:"tf",q:"Khi chưa chắc một trang web có an toàn không, em nên hỏi người lớn.",explain:"Đúng. Hỏi người lớn là cách tốt nhất khi em chưa chắc.",answer:!0},{id:"th4-xem-web-an-toan-27",type:"order",q:"Sắp xếp cách xử lý khi gặp nội dung làm em sợ trên mạng.",explain:"Dừng xem, đóng trang rồi kể với người lớn.",items:["Dừng lại, không xem tiếp","Đóng trang web đó","Kể với bố mẹ hoặc thầy cô"]}]}],challenge:{questions:[{id:"th4-xem-web-an-toan-28",type:"mc",q:"Câu nào đúng về Internet?",explain:"Biết chọn lọc thì Internet rất có ích.",options:["Có nhiều điều bổ ích, cũng có điều không an toàn","Mọi thứ trên Internet đều an toàn cho em","Mọi thứ trên Internet đều có hại cho em"],answer:0},{id:"th4-xem-web-an-toan-29",type:"tf",q:"Nếu người lạ trên mạng tặng quà, em có thể cho họ biết số điện thoại nhà mình.",explain:"Sai. Không đưa thông tin riêng cho người lạ dù họ hứa tặng quà.",answer:!1},{id:"th4-xem-web-an-toan-20",type:"mc",q:"Một người lạ nhắn tin cho Ngọc trên mạng, rủ gặp mặt. Ngọc nên làm gì?",explain:"Không bao giờ gặp người lạ quen trên mạng. Phải báo bố mẹ.",options:["Đi gặp một mình","Cho người đó địa chỉ nhà","Không đi, kể ngay với bố mẹ"],answer:2},{id:"th4-xem-web-an-toan-19",type:"mc",q:"Khoa đang xem video học vẽ thì hiện lên quảng cáo nhấp nháy mời tải trò chơi. Khoa nên làm gì?",explain:"Không nháy vào quảng cáo lạ để giữ an toàn cho máy và cho mình.",options:["Nháy vào để tải trò chơi về","Bỏ qua, không nháy vào quảng cáo","Gửi quảng cáo đó cho các bạn"],answer:1},{id:"th4-xem-web-an-toan-24",type:"multi",q:"An muốn tìm hiểu về loài cá heo trên mạng. Những việc nào An nên làm?",emoji:"🐬",explain:"Chọn trang đáng tin, nhờ người lớn và bỏ qua cửa sổ lạ giúp An an toàn.",options:["Nhờ bố mẹ giúp chọn trang","Nháy vào mọi quảng cáo","Bỏ qua các cửa sổ lạ","Xem trang web của bảo tàng, thư viện"],answers:[0,2,3]},{id:"th4-xem-web-an-toan-14",type:"tf",q:"Nếu một trang web nói điều gì thì điều đó chắc chắn đúng.",explain:"Sai. Có trang đưa tin sai. Em nên hỏi người lớn hoặc xem thêm nguồn khác.",answer:!1},{id:"th4-xem-web-an-toan-27",type:"order",q:"Sắp xếp cách xử lý khi gặp nội dung làm em sợ trên mạng.",explain:"Dừng xem, đóng trang rồi kể với người lớn.",items:["Dừng lại, không xem tiếp","Đóng trang web đó","Kể với bố mẹ hoặc thầy cô"]}]},summary:["Internet có nhiều thông tin bổ ích nhưng cũng có thông tin sai, không phù hợp.","Không nháy vào quảng cáo lạ, không đưa thông tin riêng lên mạng.","Gặp điều lạ hoặc đáng sợ, đóng trang và kể với người lớn."]}]},{id:"tim-kiem-luu-tru",title:"Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin",lessons:[{id:"th4-tim-kiem-internet",title:"Bài 7: Tìm kiếm thông tin trên Internet",weeks:[10,11],learn:[{title:"Máy tìm kiếm",text:"Máy tìm kiếm là trang web giúp em tìm thông tin trên Internet. Em gõ từ khoá vào ô tìm kiếm rồi nhấn Enter.",example:"🔍 ô tìm kiếm + Enter"},{title:"Từ khoá",text:"Từ khoá là một từ hoặc cụm từ ngắn nói về điều em muốn tìm.",example:"🔍 “cá heo thức ăn”"},{title:"Kết quả tìm kiếm",text:"Máy tìm kiếm hiện ra danh sách kết quả. Mỗi kết quả thường có tiêu đề (là siêu liên kết) và một đoạn mô tả ngắn.",example:"📋 tiêu đề · đoạn mô tả"},{title:"Các bước tìm kiếm",text:"Mở trình duyệt, vào trang máy tìm kiếm, gõ từ khoá, nhấn Enter, đọc kết quả rồi nháy vào kết quả phù hợp.",example:"🌐 → 🔍 → ⌨️ → 📋 → 👆"}],practice:[{questions:[{id:"th4-tim-kiem-internet-01",type:"mc",q:"Trang web giúp em tìm thông tin trên Internet gọi là gì?",emoji:"🔍",explain:"Máy tìm kiếm giúp tìm thông tin theo từ khoá.",options:["Phần mềm vẽ","Thùng rác","Bàn phím ảo","Máy tìm kiếm"],answer:3},{id:"th4-tim-kiem-internet-02",type:"mc",q:"Từ khoá là gì?",explain:"Từ khoá là từ ngắn em gõ vào ô tìm kiếm.",options:["Chiếc chìa khoá mở cửa phòng máy","Từ hoặc cụm từ nói về điều cần tìm","Mật khẩu để mở máy tính"],answer:1},{id:"th4-tim-kiem-internet-03",type:"tf",q:"Gõ từ khoá xong, em nhấn Enter để máy tìm kiếm bắt đầu tìm.",explain:"Đúng. Nhấn Enter hoặc nút tìm kiếm để bắt đầu tìm.",answer:!0},{id:"th4-tim-kiem-internet-04",type:"tf",q:"Máy tìm kiếm chỉ cho ra đúng một kết quả.",explain:"Sai. Máy tìm kiếm thường cho ra rất nhiều kết quả.",answer:!1},{id:"th4-tim-kiem-internet-05",type:"mc",q:"Muốn tìm thông tin, em gõ từ khoá vào đâu?",explain:"Từ khoá được gõ vào ô tìm kiếm của máy tìm kiếm.",options:["Thanh cuộn","Nút đóng cửa sổ","Ô tìm kiếm"],answer:2},{id:"th4-tim-kiem-internet-06",type:"tf",q:"Tiêu đề của mỗi kết quả tìm kiếm thường là một siêu liên kết.",explain:"Đúng. Nháy vào tiêu đề sẽ mở trang web đó.",answer:!0},{id:"th4-tim-kiem-internet-07",type:"mc",q:"Mỗi kết quả tìm kiếm thường có những gì?",explain:"Tiêu đề giúp mở trang, đoạn mô tả giúp em biết trang nói gì.",options:["Tiêu đề và đoạn mô tả ngắn","Chỉ có một con số thứ tự","Chỉ có một ô màu nền trống"],answer:0},{id:"th4-tim-kiem-internet-08",type:"tf",q:"Để dùng máy tìm kiếm, em cần mở phần mềm vẽ.",explain:"Sai. Máy tìm kiếm là một trang web nên cần mở bằng trình duyệt web.",answer:!1},{id:"th4-tim-kiem-internet-09",type:"tf",q:"Từ khoá càng dài, càng nhiều chữ thừa thì tìm càng đúng.",explain:"Sai. Từ khoá nên ngắn gọn, đúng trọng tâm điều cần tìm.",answer:!1}]},{questions:[{id:"th4-tim-kiem-internet-10",type:"order",q:"Sắp xếp các bước tìm thông tin trên Internet.",explain:"Đây là các bước tìm kiếm thông tin trên Internet.",items:["Mở trình duyệt web","Vào trang máy tìm kiếm","Gõ từ khoá vào ô tìm kiếm","Nhấn Enter","Nháy vào kết quả phù hợp"]},{id:"th4-tim-kiem-internet-11",type:"mc",q:"Em muốn biết con mèo ăn gì. Từ khoá nào phù hợp nhất?",emoji:"🐱",explain:"Từ khoá cần nói đúng điều em muốn tìm: thức ăn của mèo.",options:["con vật","màu xanh","đồ chơi","thức ăn của mèo"],answer:3},{id:"th4-tim-kiem-internet-12",type:"mc",q:"Vì sao nên đọc đoạn mô tả ngắn trước khi nháy vào kết quả?",explain:"Đoạn mô tả giúp em chọn kết quả phù hợp.",options:["Để màn hình máy tính sáng hơn","Để máy tính tìm kiếm nhanh hơn nữa","Để biết trang có đúng điều cần tìm không"],answer:2},{id:"th4-tim-kiem-internet-13",type:"tf",q:"Có thể có rất nhiều trang web cùng nói về điều em tìm.",explain:"Đúng. Vì vậy máy tìm kiếm cho ra danh sách nhiều kết quả.",answer:!0},{id:"th4-tim-kiem-internet-14",type:"tf",q:"Nháy vào kết quả nào cũng sẽ có thông tin đúng và phù hợp.",explain:"Sai. Em cần chọn kết quả phù hợp và từ trang đáng tin cậy.",answer:!1},{id:"th4-tim-kiem-internet-15",type:"match",q:"Ghép phần trên màn hình với việc của nó.",explain:"Mỗi phần giúp em tìm và chọn thông tin.",pairs:[["Ô tìm kiếm","Nơi gõ từ khoá"],["Tiêu đề kết quả","Nháy vào để mở trang"],["Đoạn mô tả","Cho biết trang nói gì"]]},{id:"th4-tim-kiem-internet-16",type:"mc",q:"Kết quả tìm kiếm hiện ra theo dạng nào?",explain:"Máy tìm kiếm hiện ra danh sách nhiều kết quả.",options:["Một danh sách các kết quả","Một bản nhạc không lời","Một bức tranh vẽ bằng tay"],answer:0},{id:"th4-tim-kiem-internet-17",type:"multi",q:"Những từ nào có thể là từ khoá để tìm hiểu về vịnh Hạ Long?",explain:"Từ khoá phải nói về vịnh Hạ Long.",options:["vịnh Hạ Long","du lịch vịnh Hạ Long","bánh chưng","phần mềm vẽ"],answers:[0,1]},{id:"th4-tim-kiem-internet-18",type:"fill",q:"Điền từ còn thiếu: Từ hoặc cụm từ em gõ vào ô tìm kiếm gọi là từ … .",explain:"Đó là từ khoá.",answer:["khoá","khóa"]}]},{questions:[{id:"th4-tim-kiem-internet-19",type:"mc",q:"Lan muốn tìm cách gấp con hạc giấy. Từ khoá nào phù hợp nhất?",emoji:"🕊️",explain:'Từ khoá "cách gấp hạc giấy" nói đúng điều Lan cần.',options:["con chim","giấy trắng","bài hát hay","cách gấp hạc giấy"],answer:3},{id:"th4-tim-kiem-internet-20",type:"mc",q:'Minh tìm "voi" thì thấy cả bài hát, phim và đồ chơi. Minh muốn biết voi ăn gì. Minh nên sửa từ khoá thế nào?',emoji:"🐘",explain:'Thêm từ "thức ăn" giúp kết quả đúng điều Minh cần hơn.',options:["voi voi voi","thức ăn của voi","con vật to lớn"],answer:1},{id:"th4-tim-kiem-internet-21",type:"tf",q:"Nam đọc tiêu đề và đoạn mô tả rồi mới chọn kết quả. Nam làm đúng.",explain:"Đúng. Đọc trước giúp chọn được kết quả phù hợp.",answer:!0},{id:"th4-tim-kiem-internet-22",type:"tf",q:"Hà tìm thấy một kết quả có tiêu đề lạ, mời nhận quà. Hà nên nháy vào ngay.",explain:"Sai. Kết quả lạ, mời nhận quà có thể không an toàn. Hà nên bỏ qua.",answer:!1},{id:"th4-tim-kiem-internet-23",type:"mc",q:"Chi muốn tìm thông tin về thời tiết ngày mai ở nơi mình sống. Từ khoá nào tốt nhất?",emoji:"🌦️",explain:'Từ khoá cần có cả "thời tiết", "ngày mai" và tên nơi cần xem.',options:["trời hôm nay có đẹp hay không","thời tiết ngày mai và tên nơi Chi sống","ngày mai em đi chơi ở đâu"],answer:1},{id:"th4-tim-kiem-internet-24",type:"multi",q:"Khoa tìm thông tin cho bài về cây lúa. Khoa nên làm những việc nào?",emoji:"🌾",explain:"Gõ đúng từ khoá, đọc mô tả và chọn trang đáng tin.",options:['Gõ từ khoá "cây lúa"',"Đọc đoạn mô tả kết quả","Chọn trang đáng tin cậy","Nháy vào quảng cáo trúng thưởng"],answers:[0,1,2]},{id:"th4-tim-kiem-internet-25",type:"mc",q:"Kết quả đầu tiên không có thông tin Thảo cần. Thảo nên làm gì?",explain:"Có thể xem kết quả khác hoặc đổi từ khoá cho rõ hơn.",options:["Xem các kết quả khác hoặc đổi từ khoá","Tắt máy tính và bỏ cuộc","Gõ lại đúng từ khoá cũ thật nhiều lần"],answer:0},{id:"th4-tim-kiem-internet-26",type:"tf",q:"Khi tìm được thông tin, em nên hỏi người lớn nếu chưa chắc thông tin đó đúng.",explain:"Đúng. Không phải thông tin nào trên mạng cũng đúng.",answer:!0},{id:"th4-tim-kiem-internet-27",type:"order",q:"Sắp xếp các việc Dũng làm khi tìm hiểu về loài rùa.",emoji:"🐢",explain:"Gõ từ khoá, tìm, đọc kết quả rồi chọn trang phù hợp.",items:['Gõ từ khoá "loài rùa"',"Nhấn Enter","Đọc tiêu đề và đoạn mô tả","Nháy vào kết quả phù hợp"]}]}],challenge:{questions:[{id:"th4-tim-kiem-internet-28",type:"mc",q:"Từ khoá nào giúp tìm cách trồng cây hoa hướng dương?",emoji:"🌻",explain:"Từ khoá cụ thể cho kết quả đúng hơn.",options:["hoa","màu vàng","mặt trời","cách trồng hoa hướng dương"],answer:3},{id:"th4-tim-kiem-internet-29",type:"tf",q:"Khi tìm kiếm, thay đổi từ khoá có thể cho ra kết quả khác.",explain:"Đúng. Từ khoá khác thì danh sách kết quả cũng khác.",answer:!0},{id:"th4-tim-kiem-internet-20",type:"mc",q:'Minh tìm "voi" thì thấy cả bài hát, phim và đồ chơi. Minh muốn biết voi ăn gì. Minh nên sửa từ khoá thế nào?',emoji:"🐘",explain:'Thêm từ "thức ăn" giúp kết quả đúng điều Minh cần hơn.',options:["voi voi voi","thức ăn của voi","con vật to lớn"],answer:1},{id:"th4-tim-kiem-internet-21",type:"tf",q:"Nam đọc tiêu đề và đoạn mô tả rồi mới chọn kết quả. Nam làm đúng.",explain:"Đúng. Đọc trước giúp chọn được kết quả phù hợp.",answer:!0},{id:"th4-tim-kiem-internet-23",type:"mc",q:"Chi muốn tìm thông tin về thời tiết ngày mai ở nơi mình sống. Từ khoá nào tốt nhất?",emoji:"🌦️",explain:'Từ khoá cần có cả "thời tiết", "ngày mai" và tên nơi cần xem.',options:["trời hôm nay có đẹp hay không","thời tiết ngày mai và tên nơi Chi sống","ngày mai em đi chơi ở đâu"],answer:1},{id:"th4-tim-kiem-internet-10",type:"order",q:"Sắp xếp các bước tìm thông tin trên Internet.",explain:"Đây là các bước tìm kiếm thông tin trên Internet.",items:["Mở trình duyệt web","Vào trang máy tìm kiếm","Gõ từ khoá vào ô tìm kiếm","Nhấn Enter","Nháy vào kết quả phù hợp"]},{id:"th4-tim-kiem-internet-24",type:"multi",q:"Khoa tìm thông tin cho bài về cây lúa. Khoa nên làm những việc nào?",emoji:"🌾",explain:"Gõ đúng từ khoá, đọc mô tả và chọn trang đáng tin.",options:['Gõ từ khoá "cây lúa"',"Đọc đoạn mô tả kết quả","Chọn trang đáng tin cậy","Nháy vào quảng cáo trúng thưởng"],answers:[0,1,2]}]},summary:["Máy tìm kiếm giúp tìm thông tin trên Internet.","Từ khoá là từ hoặc cụm từ ngắn nói về điều cần tìm.","Đọc tiêu đề và đoạn mô tả để chọn kết quả phù hợp."]},{id:"th4-chon-tu-khoa",title:"Bài 8: Chọn từ khoá và chọn kết quả",weeks:[12,12],learn:[{title:"Từ khoá tốt",text:"Từ khoá tốt thì ngắn gọn, đúng trọng tâm, gõ đúng chính tả và có dấu tiếng Việt.",example:"✅ “cách trồng rau muống”"},{title:"Thu hẹp kết quả",text:"Nếu kết quả quá nhiều thứ không cần, hãy thêm từ cho rõ hơn. Ví dụ “mèo” thành “cách chăm sóc mèo con”.",example:"🔍 mèo → cách chăm sóc mèo con"},{title:"Chọn nguồn đáng tin",text:"Ưu tiên trang của trường học, thư viện, bảo tàng, cơ quan nhà nước, báo chí. Thông tin quan trọng nên xem ở nhiều nguồn và hỏi người lớn.",example:"🏫 📚 🏛️"},{title:"Ghi lại điều tìm được",text:"Đọc kĩ, ghi lại ý chính bằng lời của mình và nhớ ghi trang em đã lấy thông tin.",example:"📝 ý chính + nguồn"}],practice:[{questions:[{id:"th4-chon-tu-khoa-01",type:"tf",q:"Từ khoá gõ sai chính tả cũng luôn cho kết quả đúng như gõ đúng.",explain:"Sai. Gõ sai chính tả có thể làm kết quả không đúng.",answer:!1},{id:"th4-chon-tu-khoa-02",type:"mc",q:"Từ khoá nào được gõ đúng chính tả?",explain:'"Chuồn chuồn" viết với ch.',options:["con truồn truồn","con chuồn truồn","con chuồn chuồn"],answer:2},{id:"th4-chon-tu-khoa-03",type:"tf",q:"Từ khoá càng chung chung thì kết quả càng đúng điều em cần.",explain:"Sai. Từ khoá chung chung cho ra nhiều kết quả không cần.",answer:!1},{id:"th4-chon-tu-khoa-04",type:"mc",q:"Trang nào thường đáng tin cậy khi tìm thông tin học tập?",emoji:"📚",explain:"Thư viện là nơi có thông tin đáng tin cậy.",options:["Trang quảng cáo trúng thưởng","Trang mời tải trò chơi lạ","Trang web của thư viện"],answer:2},{id:"th4-chon-tu-khoa-05",type:"tf",q:"Khi ghi lại thông tin tìm được, em nên ghi cả nơi đã lấy thông tin.",explain:"Đúng. Ghi nguồn giúp em và người khác kiểm tra lại.",answer:!0},{id:"th4-chon-tu-khoa-06",type:"mc",q:"Từ khoá nào ngắn gọn và đúng trọng tâm?",explain:'"Cách trồng rau muống" nói rõ điều cần tìm.',options:["em ơi em muốn biết rau","cách trồng rau muống","rau rau rau rau"],answer:1},{id:"th4-chon-tu-khoa-07",type:"tf",q:"Gõ từ khoá có dấu tiếng Việt giúp kết quả đúng hơn.",explain:'Đúng. Ví dụ "bò" và "bơ" rất khác nhau nếu viết đủ dấu.',answer:!0},{id:"th4-chon-tu-khoa-08",type:"mc",q:"Muốn kết quả ít thứ thừa hơn, em nên làm gì?",explain:"Thêm từ làm từ khoá cụ thể hơn, kết quả sát hơn.",options:["Thêm từ cho từ khoá rõ hơn","Xoá hết từ khoá đi gõ lại","Tắt trình duyệt web rồi mở lại"],answer:0},{id:"th4-chon-tu-khoa-09",type:"tf",q:"Mọi trang trong danh sách kết quả đều đáng tin như nhau.",explain:"Sai. Có trang đáng tin, có trang không. Em cần chọn lọc.",answer:!1}]},{questions:[{id:"th4-chon-tu-khoa-10",type:"mc",q:'Từ khoá "bánh" cho ra rất nhiều loại bánh. Em muốn biết cách làm bánh trôi. Em sửa thành gì?',explain:'Thêm "cách làm" và "trôi" để đúng điều cần tìm.',options:["bánh ngon","bánh bánh","đồ ăn","cách làm bánh trôi"],answer:3},{id:"th4-chon-tu-khoa-11",type:"multi",q:"Những đặc điểm nào là của một từ khoá tốt?",explain:"Từ khoá tốt ngắn gọn, đúng trọng tâm, đúng chính tả.",options:["Có nhiều chữ lặp lại","Ngắn gọn","Đúng trọng tâm","Đúng chính tả"],answers:[1,2,3]},{id:"th4-chon-tu-khoa-12",type:"match",q:"Ghép điều cần tìm với từ khoá phù hợp.",explain:"Từ khoá cần chứa những từ quan trọng nhất của điều cần tìm.",pairs:[["Loài chim cánh cụt sống ở đâu","nơi sống của chim cánh cụt"],["Cách vẽ con thỏ","cách vẽ con thỏ"],["Bài hát về mùa xuân","bài hát thiếu nhi mùa xuân"]]},{id:"th4-chon-tu-khoa-13",type:"tf",q:"Thông tin quan trọng nên được xem ở nhiều nguồn để kiểm tra.",explain:"Đúng. So sánh nhiều nguồn giúp biết thông tin có đúng không.",answer:!0},{id:"th4-chon-tu-khoa-14",type:"mc",q:"Vì sao nên ghi ý chính bằng lời của mình thay vì chép nguyên văn?",explain:"Viết lại bằng lời của mình giúp em hiểu bài; chép nguyên văn cần ghi nguồn.",options:["Để hiểu bài và tôn trọng tác giả","Để bài làm dài hơn thật nhiều","Để không ai đọc được bài của mình"],answer:0},{id:"th4-chon-tu-khoa-15",type:"tf",q:'Gõ từ khoá "cá vàng" và "ca vang" sẽ luôn cho kết quả giống hệt nhau.',explain:"Sai. Gõ thiếu dấu có thể cho ra kết quả khác.",answer:!1},{id:"th4-chon-tu-khoa-16",type:"mc",q:"Trong các kết quả, kết quả nào nên chọn khi tìm hiểu về Văn Miếu – Quốc Tử Giám?",emoji:"🏛️",explain:"Trang của khu di tích có thông tin đáng tin cậy.",options:["Trang quảng cáo bán đồ chơi","Trang trò chơi đố vui không rõ nguồn","Trang giới thiệu của khu di tích"],answer:2},{id:"th4-chon-tu-khoa-17",type:"order",q:"Sắp xếp các việc khi làm bài tìm hiểu trên Internet.",explain:"Chọn từ khoá, tìm, đọc rồi ghi lại.",items:["Chọn từ khoá phù hợp","Tìm kiếm và chọn trang đáng tin","Đọc kĩ thông tin","Ghi lại ý chính và nguồn"]},{id:"th4-chon-tu-khoa-18",type:"tf",q:'Thêm từ "cách làm" vào từ khoá giúp tìm hướng dẫn làm một việc.',explain:'Đúng. Ví dụ "cách làm diều giấy" cho ra các bài hướng dẫn.',answer:!0}]},{questions:[{id:"th4-chon-tu-khoa-19",type:"mc",q:"Ngọc muốn biết vì sao lá cây có màu xanh. Từ khoá nào tốt nhất?",emoji:"🍃",explain:'Từ khoá cần có cả "lá cây" và "màu xanh".',options:["cây","màu xanh","lá rơi mùa thu","vì sao lá cây màu xanh"],answer:3},{id:"th4-chon-tu-khoa-20",type:"mc",q:'Phúc gõ "khung long an gi" và thấy kết quả lạ. Phúc nên sửa thế nào?',emoji:"🦕",explain:'Gõ đủ dấu và đúng chính tả: "khủng long ăn gì".',options:["khung long an","khủng long ăn gì","khụng lóng ăn gì"],answer:1},{id:"th4-chon-tu-khoa-21",type:"tf",q:"Vy thấy hai trang nói khác nhau về một con số. Vy nên hỏi thầy cô hoặc xem thêm trang đáng tin.",explain:"Đúng. Khi các nguồn khác nhau, cần kiểm tra thêm.",answer:!0},{id:"th4-chon-tu-khoa-22",type:"tf",q:"Tùng chép nguyên một bài trên mạng vào bài làm và nói là mình tự viết. Tùng làm như vậy là đúng.",explain:"Sai. Phải ghi nguồn và nên viết lại bằng lời của mình.",answer:!1},{id:"th4-chon-tu-khoa-23",type:"multi",q:"An tìm hiểu về loài ong. Những nguồn nào đáng tin cậy hơn?",emoji:"🐝",explain:"Bảo tàng, sách thư viện, báo chính thống đáng tin hơn bình luận của người lạ.",options:["Trang của bảo tàng thiên nhiên","Sách khoa học ở thư viện","Trang báo chí chính thống","Bình luận của người lạ trên mạng"],answers:[0,1,2]},{id:"th4-chon-tu-khoa-24",type:"mc",q:'Bình tìm "sông" và nhận được quá nhiều kết quả. Bình muốn biết sông dài nhất Việt Nam. Bình nên gõ gì?',explain:"Từ khoá cụ thể giúp thu hẹp kết quả.",options:["sông sông","nước chảy","con thuyền","sông dài nhất Việt Nam"],answer:3},{id:"th4-chon-tu-khoa-25",type:"match",q:"Ghép việc làm với lí do.",explain:"Mỗi việc làm giúp tìm và dùng thông tin tốt hơn.",pairs:[["Gõ đúng chính tả","Kết quả chính xác hơn"],["Thêm từ cho rõ","Bớt kết quả không cần"],["Ghi nguồn","Tôn trọng tác giả, dễ kiểm tra"],["Xem nhiều nguồn","Biết thông tin có đúng không"]]},{id:"th4-chon-tu-khoa-26",type:"tf",q:"Khoa chọn trang của thư viện để tìm hiểu về các nhà khoa học. Khoa chọn hợp lí.",explain:"Đúng. Thư viện là nguồn đáng tin cậy.",answer:!0},{id:"th4-chon-tu-khoa-27",type:"fill",q:"Điền từ còn thiếu: Khi lấy thông tin trên mạng, em nên ghi lại … để biết thông tin lấy từ đâu.",explain:"Ghi nguồn giúp em và người khác kiểm tra thông tin.",answer:["nguồn"]}]}],challenge:{questions:[{id:"th4-chon-tu-khoa-28",type:"mc",q:"Thảo muốn tìm bài hát thiếu nhi về chú ếch. Từ khoá nào sát nhất?",emoji:"🐸",explain:'Có cả "bài hát thiếu nhi" và "chú ếch" mới sát điều Thảo cần.',options:["con ếch xanh","bài hát hay nhất","ếch","bài hát thiếu nhi chú ếch"],answer:3},{id:"th4-chon-tu-khoa-29",type:"tf",q:"Nếu chỉ đọc tiêu đề mà không đọc nội dung, em vẫn chắc chắn hiểu đúng thông tin.",explain:"Sai. Tiêu đề chỉ cho biết ý chung, cần đọc kĩ nội dung.",answer:!1},{id:"th4-chon-tu-khoa-19",type:"mc",q:"Ngọc muốn biết vì sao lá cây có màu xanh. Từ khoá nào tốt nhất?",emoji:"🍃",explain:'Từ khoá cần có cả "lá cây" và "màu xanh".',options:["cây","màu xanh","lá rơi mùa thu","vì sao lá cây màu xanh"],answer:3},{id:"th4-chon-tu-khoa-20",type:"mc",q:'Phúc gõ "khung long an gi" và thấy kết quả lạ. Phúc nên sửa thế nào?',emoji:"🦕",explain:'Gõ đủ dấu và đúng chính tả: "khủng long ăn gì".',options:["khung long an","khủng long ăn gì","khụng lóng ăn gì"],answer:1},{id:"th4-chon-tu-khoa-23",type:"multi",q:"An tìm hiểu về loài ong. Những nguồn nào đáng tin cậy hơn?",emoji:"🐝",explain:"Bảo tàng, sách thư viện, báo chính thống đáng tin hơn bình luận của người lạ.",options:["Trang của bảo tàng thiên nhiên","Sách khoa học ở thư viện","Trang báo chí chính thống","Bình luận của người lạ trên mạng"],answers:[0,1,2]},{id:"th4-chon-tu-khoa-25",type:"match",q:"Ghép việc làm với lí do.",explain:"Mỗi việc làm giúp tìm và dùng thông tin tốt hơn.",pairs:[["Gõ đúng chính tả","Kết quả chính xác hơn"],["Thêm từ cho rõ","Bớt kết quả không cần"],["Ghi nguồn","Tôn trọng tác giả, dễ kiểm tra"],["Xem nhiều nguồn","Biết thông tin có đúng không"]]},{id:"th4-chon-tu-khoa-14",type:"mc",q:"Vì sao nên ghi ý chính bằng lời của mình thay vì chép nguyên văn?",explain:"Viết lại bằng lời của mình giúp em hiểu bài; chép nguyên văn cần ghi nguồn.",options:["Để hiểu bài và tôn trọng tác giả","Để bài làm dài hơn thật nhiều","Để không ai đọc được bài của mình"],answer:0}]},summary:["Từ khoá tốt thì ngắn gọn, đúng trọng tâm, đúng chính tả, có dấu.","Thêm từ để thu hẹp kết quả khi kết quả quá nhiều.","Chọn nguồn đáng tin, ghi ý chính bằng lời của mình và ghi nguồn."]},{id:"th4-cay-thu-muc",title:"Bài 9: Cây thư mục",weeks:[13,14],learn:[{title:"Tệp và thư mục",text:"Tệp chứa thông tin như bài văn, bức tranh, bài hát. Thư mục giống chiếc hộp để chứa tệp và các thư mục khác.",example:"📄 tệp · 📁 thư mục"},{title:"Thư mục con, thư mục mẹ",text:"Thư mục nằm bên trong một thư mục khác gọi là thư mục con. Thư mục chứa nó gọi là thư mục mẹ.",example:"📁 Học tập → 📁 Toán"},{title:"Cây thư mục",text:"Các thư mục lồng trong nhau tạo thành cây thư mục. Sắp xếp tệp theo cây thư mục giúp tìm tệp nhanh hơn.",example:`📁 Lớp 4
  ├ 📁 Toán
  └ 📁 Tin học`},{title:"Đặt tên dễ hiểu",text:"Đặt tên tệp, thư mục ngắn gọn, nói rõ nội dung bên trong để dễ tìm.",example:"📁 Tranh vẽ · 📄 Bai van mua thu"}],practice:[{questions:[{id:"th4-cay-thu-muc-01",type:"mc",q:"Thư mục dùng để làm gì?",emoji:"📁",explain:"Thư mục giống chiếc hộp chứa tệp và thư mục con.",options:["Phát ra âm thanh, bài hát","Gõ chữ và số vào máy tính","In các bức tranh ra giấy","Chứa tệp và các thư mục khác"],answer:3},{id:"th4-cay-thu-muc-02",type:"tf",q:"Một bài văn đã lưu trên máy tính là một thư mục.",emoji:"📄",explain:"Sai. Bài văn đã lưu là một tệp; thư mục dùng để chứa tệp.",answer:!1},{id:"th4-cay-thu-muc-03",type:"mc",q:"Thư mục nằm bên trong thư mục khác gọi là gì?",explain:"Thư mục nằm bên trong gọi là thư mục con.",options:["Thư mục mẹ","Thư mục con","Thư mục ông"],answer:1},{id:"th4-cay-thu-muc-04",type:"tf",q:"Thư mục chứa thư mục con gọi là thư mục mẹ.",explain:"Đúng. Thư mục mẹ chứa thư mục con.",answer:!0},{id:"th4-cay-thu-muc-05",type:"tf",q:"Thư mục chỉ chứa được tệp, không chứa được thư mục khác.",explain:"Sai. Thư mục có thể chứa cả tệp và thư mục con.",answer:!1},{id:"th4-cay-thu-muc-06",type:"mc",q:"Các thư mục lồng nhau tạo thành gì?",emoji:"🌳",explain:"Các thư mục lồng nhau giống cành cây nên gọi là cây thư mục.",options:["Bàn phím","Trang chiếu","Cây thư mục"],answer:2},{id:"th4-cay-thu-muc-07",type:"mc",q:"Tên thư mục nào dễ hiểu nhất để chứa tranh em vẽ?",emoji:"🎨",explain:'Tên "Tranh vẽ" nói rõ bên trong có gì.',options:["abc","Thư mục mới 2","xyz123","Tranh vẽ"],answer:3},{id:"th4-cay-thu-muc-08",type:"tf",q:"Sắp xếp tệp vào các thư mục giúp em tìm tệp nhanh hơn.",explain:"Đúng. Tệp được xếp gọn thì dễ tìm.",answer:!0},{id:"th4-cay-thu-muc-09",type:"tf",q:"Tệp và thư mục là hai tên gọi của cùng một thứ.",explain:"Sai. Tệp chứa thông tin, thư mục dùng để chứa tệp.",answer:!1}]},{questions:[{id:"th4-cay-thu-muc-10",type:"match",q:"Ghép mỗi thứ với loại của nó.",explain:"Tệp chứa thông tin, thư mục chứa tệp, nhiều thư mục lồng nhau tạo thành cây thư mục.",pairs:[["Bức tranh con mèo đã lưu","Tệp"],["Chiếc hộp chứa các bài văn","Thư mục"],["Các thư mục lồng nhau","Cây thư mục"]]},{id:"th4-cay-thu-muc-11",type:"mc",q:"Trong cây thư mục: Lớp 4 chứa Toán và Tin học. Thư mục mẹ của Toán là thư mục nào?",emoji:"📁",explain:"Lớp 4 chứa Toán nên Lớp 4 là thư mục mẹ.",options:["Lớp 4","Tin học","Toán"],answer:0},{id:"th4-cay-thu-muc-12",type:"mc",q:"Trong cây thư mục: Lớp 4 chứa Toán và Tin học. Thư mục nào là thư mục con của Lớp 4?",explain:"Toán và Tin học đều nằm trong Lớp 4.",options:["Chỉ có Toán","Cả Toán và Tin học","Không có thư mục nào"],answer:1},{id:"th4-cay-thu-muc-13",type:"tf",q:"Một thư mục mẹ chỉ được có đúng một thư mục con.",explain:"Sai. Thư mục mẹ có thể có nhiều thư mục con, như Lớp 4 chứa Toán, Tiếng Việt, Tin học.",answer:!1},{id:"th4-cay-thu-muc-14",type:"tf",q:'Đặt tên tất cả thư mục là "abc" giúp dễ tìm hơn.',explain:"Sai. Tên giống nhau, không rõ nghĩa sẽ rất khó tìm.",answer:!1},{id:"th4-cay-thu-muc-15",type:"multi",q:'Tệp nào nên đặt trong thư mục "Âm nhạc"?',emoji:"🎵",explain:'Thư mục "Âm nhạc" nên chứa các tệp bài hát.',options:["Bài hát Quê hương","Bài hát Em yêu trường em","Bài văn tả cây phượng","Tranh vẽ con mèo"],answers:[0,1]},{id:"th4-cay-thu-muc-16",type:"mc",q:'Vì sao gọi là "cây" thư mục?',explain:"Thư mục mẹ chia ra nhiều thư mục con như cây chia cành.",options:["Vì thư mục được làm bằng gỗ cây","Vì mọi thư mục đều có màu xanh lá","Vì các thư mục chia nhánh như cành cây"],answer:2},{id:"th4-cay-thu-muc-17",type:"order",q:"Sắp xếp từ thư mục ngoài cùng vào trong.",explain:"Học tập chứa Lớp 4, Lớp 4 chứa Tin học, Tin học chứa Bài thực hành 1.",items:["Học tập","Lớp 4","Tin học","Bài thực hành 1"]},{id:"th4-cay-thu-muc-18",type:"tf",q:"Thư mục con có thể chứa thư mục con khác bên trong.",explain:"Đúng. Thư mục có thể lồng nhiều tầng.",answer:!0}]},{questions:[{id:"th4-cay-thu-muc-19",type:"mc",q:"An có các tệp: bài văn, tranh vẽ, bài hát để lẫn lộn. An nên làm gì để dễ tìm?",explain:"Xếp tệp vào thư mục theo loại giúp tìm nhanh hơn.",options:["Tạo thư mục theo loại rồi xếp tệp vào","Để nguyên các tệp lẫn lộn như cũ",'Đổi tên tất cả các tệp thành "tệp"'],answer:0},{id:"th4-cay-thu-muc-20",type:"mc",q:"Chi muốn cất bài thực hành Tin học tuần 5. Thư mục nào hợp lí nhất?",explain:"Bài Tin học nên cất trong thư mục Tin học của Lớp 4.",options:["Lớp 4 rồi vào Tin học","Lớp 4 rồi vào Âm nhạc","Thư mục Trò chơi"],answer:0},{id:"th4-cay-thu-muc-21",type:"tf",q:"Cây thư mục: Gia đình chứa Ảnh và Video. Ảnh chứa Sinh nhật. Thư mục Sinh nhật là thư mục con của Ảnh.",explain:"Đúng. Sinh nhật nằm bên trong Ảnh.",answer:!0},{id:"th4-cay-thu-muc-22",type:"tf",q:"Cây thư mục: Gia đình chứa Ảnh và Video. Ảnh chứa Sinh nhật. Thư mục Video là thư mục mẹ của Sinh nhật.",explain:"Sai. Thư mục mẹ của Sinh nhật là Ảnh.",answer:!1},{id:"th4-cay-thu-muc-23",type:"multi",q:"Cây thư mục: Trường học chứa Lớp 4. Lớp 4 chứa Toán và Khoa học. Thư mục nào nằm trong Trường học (kể cả nằm sâu bên trong)?",explain:"Lớp 4 nằm trong Trường học, còn Toán và Khoa học nằm trong Lớp 4.",options:["Toán","Khoa học","Trường học","Lớp 4"],answers:[0,1,3]},{id:"th4-cay-thu-muc-24",type:"mc",q:'Nam đặt tên tệp là "1". Hôm sau Nam không nhớ tệp chứa gì. Nam nên đặt tên thế nào?',explain:"Tên tệp nên nói rõ nội dung bên trong.",options:["2","Bai van ta con meo","aaaa"],answer:1},{id:"th4-cay-thu-muc-25",type:"match",q:"Ghép tệp với thư mục phù hợp.",explain:"Xếp tệp theo môn học giúp dễ tìm.",pairs:[["Bài văn tả cảnh biển","Tiếng Việt"],["Bài giải phép nhân","Toán"],["Bản vẽ ngôi nhà","Mĩ thuật"],["Bài thực hành gõ phím","Tin học"]]},{id:"th4-cay-thu-muc-26",type:"tf",q:"Hà xếp tệp theo môn học trong thư mục Lớp 4. Đây là cách sắp xếp hợp lí.",explain:"Đúng. Xếp theo môn học giúp Hà tìm tệp nhanh.",answer:!0},{id:"th4-cay-thu-muc-27",type:"fill",q:"Điền từ còn thiếu: Thư mục nằm bên trong thư mục khác gọi là thư mục … .",explain:"Đó là thư mục con.",answer:["con"]}]}],challenge:{questions:[{id:"th4-cay-thu-muc-28",type:"order",q:"Cây thư mục: Máy tính, Tài liệu, Lớp 4, Toán. Sắp xếp từ ngoài vào trong.",explain:"Mỗi thư mục chứa thư mục đứng sau nó.",items:["Máy tính","Tài liệu","Lớp 4","Toán"]},{id:"th4-cay-thu-muc-29",type:"mc",q:"Thư mục Lớp 4 chứa Toán, Toán chứa Bài kiểm tra. Muốn mở Bài kiểm tra, em mở lần lượt thế nào?",explain:"Đi từ thư mục ngoài vào thư mục trong.",options:["Toán, rồi Lớp 4, rồi Bài kiểm tra","Bài kiểm tra, rồi Toán","Lớp 4, rồi Toán, rồi Bài kiểm tra"],answer:2},{id:"th4-cay-thu-muc-21",type:"tf",q:"Cây thư mục: Gia đình chứa Ảnh và Video. Ảnh chứa Sinh nhật. Thư mục Sinh nhật là thư mục con của Ảnh.",explain:"Đúng. Sinh nhật nằm bên trong Ảnh.",answer:!0},{id:"th4-cay-thu-muc-22",type:"tf",q:"Cây thư mục: Gia đình chứa Ảnh và Video. Ảnh chứa Sinh nhật. Thư mục Video là thư mục mẹ của Sinh nhật.",explain:"Sai. Thư mục mẹ của Sinh nhật là Ảnh.",answer:!1},{id:"th4-cay-thu-muc-23",type:"multi",q:"Cây thư mục: Trường học chứa Lớp 4. Lớp 4 chứa Toán và Khoa học. Thư mục nào nằm trong Trường học (kể cả nằm sâu bên trong)?",explain:"Lớp 4 nằm trong Trường học, còn Toán và Khoa học nằm trong Lớp 4.",options:["Toán","Khoa học","Trường học","Lớp 4"],answers:[0,1,3]},{id:"th4-cay-thu-muc-25",type:"match",q:"Ghép tệp với thư mục phù hợp.",explain:"Xếp tệp theo môn học giúp dễ tìm.",pairs:[["Bài văn tả cảnh biển","Tiếng Việt"],["Bài giải phép nhân","Toán"],["Bản vẽ ngôi nhà","Mĩ thuật"],["Bài thực hành gõ phím","Tin học"]]},{id:"th4-cay-thu-muc-14",type:"tf",q:'Đặt tên tất cả thư mục là "abc" giúp dễ tìm hơn.',explain:"Sai. Tên giống nhau, không rõ nghĩa sẽ rất khó tìm.",answer:!1}]},summary:["Tệp chứa thông tin, thư mục dùng để chứa tệp và thư mục khác.","Thư mục bên trong là thư mục con, thư mục chứa nó là thư mục mẹ.","Các thư mục lồng nhau tạo thành cây thư mục, giúp tìm tệp nhanh."]},{id:"th4-thao-tac-tep",title:"Bài 10: Tạo, đổi tên, xoá tệp và thư mục",weeks:[15,16],learn:[{title:"Tạo thư mục mới",text:"Mở nơi muốn tạo, nháy nút phải chuột vào chỗ trống, chọn lệnh tạo thư mục mới, gõ tên rồi nhấn Enter.",example:"🖱️ nút phải → Mới → Thư mục"},{title:"Đổi tên",text:"Nháy nút phải chuột vào tệp hoặc thư mục, chọn lệnh đổi tên, gõ tên mới rồi nhấn Enter.",example:"🖱️ nút phải → Đổi tên"},{title:"Xoá",text:"Chọn tệp hoặc thư mục rồi nhấn phím Delete. Tệp bị xoá thường được đưa vào Thùng rác và còn lấy lại được.",example:"🗑️ Thùng rác"},{title:"Cẩn thận",text:"Xoá một thư mục là xoá cả mọi thứ bên trong. Chỉ xoá, đổi tên tệp của mình; không động vào tệp của người khác.",example:"⚠️ 📁 = 📁 + 📄📄📄"}],practice:[{questions:[{id:"th4-thao-tac-tep-01",type:"mc",q:"Để xoá một tệp đã chọn, em có thể nhấn phím nào?",explain:"Phím Delete dùng để xoá tệp hoặc thư mục đã chọn.",options:["Enter","Phím cách","Phím F","Delete"],answer:3},{id:"th4-thao-tac-tep-02",type:"tf",q:"Tệp bị xoá thường được đưa vào Thùng rác.",emoji:"🗑️",explain:"Đúng. Từ Thùng rác vẫn có thể lấy lại tệp.",answer:!0},{id:"th4-thao-tac-tep-03",type:"tf",q:"Xoá một thư mục thì các tệp bên trong vẫn còn nguyên ở chỗ cũ.",explain:"Sai. Xoá thư mục là xoá cả mọi thứ bên trong nó.",answer:!1},{id:"th4-thao-tac-tep-04",type:"mc",q:"Để đổi tên thư mục, em nháy nút phải chuột vào thư mục rồi chọn lệnh gì?",explain:"Lệnh đổi tên giúp đặt lại tên cho tệp, thư mục.",options:["Xoá","In","Đổi tên"],answer:2},{id:"th4-thao-tac-tep-05",type:"mc",q:"Gõ xong tên thư mục mới, em nhấn phím nào để hoàn tất?",explain:"Nhấn Enter để xác nhận tên.",options:["Enter","Delete","Phím Q"],answer:0},{id:"th4-thao-tac-tep-06",type:"tf",q:"Em không thể tự tạo thư mục mới trên máy tính.",explain:"Sai. Em có thể tạo thư mục mới để cất bài cho gọn gàng.",answer:!1},{id:"th4-thao-tac-tep-07",type:"mc",q:"Khi xoá nhầm một tệp, em có thể tìm lại ở đâu?",explain:"Tệp xoá thường nằm trong Thùng rác, có thể khôi phục.",options:["Ô tìm kiếm của trang web","Thùng rác","Phần mềm vẽ"],answer:1},{id:"th4-thao-tac-tep-08",type:"tf",q:"Em được tự ý xoá tệp của bạn khác trên máy tính của lớp.",explain:"Sai. Không xoá, không đổi tên tệp của người khác.",answer:!1},{id:"th4-thao-tac-tep-09",type:"tf",q:"Muốn tạo thư mục mới, em có thể nháy nút phải chuột vào chỗ trống trong cửa sổ thư mục.",explain:"Đúng. Bảng chọn hiện ra có lệnh tạo mới thư mục.",answer:!0}]},{questions:[{id:"th4-thao-tac-tep-10",type:"order",q:"Sắp xếp các bước tạo một thư mục mới.",explain:"Đây là các bước tạo thư mục mới.",items:["Mở nơi muốn tạo thư mục","Nháy nút phải chuột vào chỗ trống","Chọn lệnh tạo thư mục mới","Gõ tên thư mục","Nhấn Enter"]},{id:"th4-thao-tac-tep-11",type:"order",q:"Sắp xếp các bước đổi tên một tệp.",explain:"Đây là các bước đổi tên tệp.",items:["Nháy nút phải chuột vào tệp","Chọn lệnh đổi tên","Gõ tên mới","Nhấn Enter"]},{id:"th4-thao-tac-tep-12",type:"match",q:"Ghép việc cần làm với cách làm.",explain:"Mỗi việc có một cách làm riêng.",pairs:[["Xoá tệp","Chọn tệp, nhấn Delete"],["Đổi tên tệp","Nháy nút phải, chọn Đổi tên"],["Lấy lại tệp đã xoá","Mở Thùng rác, khôi phục"]]},{id:"th4-thao-tac-tep-13",type:"mc",q:"Vì sao cần cẩn thận khi xoá thư mục?",explain:"Thư mục bị xoá sẽ mang theo mọi thứ bên trong.",options:["Vì máy tính sẽ tắt ngay lập tức","Vì bàn phím sẽ bị khoá không gõ được","Vì mọi tệp bên trong cũng bị xoá"],answer:2},{id:"th4-thao-tac-tep-14",type:"tf",q:"Đổi tên tệp sẽ xoá hết nội dung bên trong tệp.",explain:"Sai. Đổi tên chỉ thay tên gọi, nội dung vẫn giữ nguyên.",answer:!1},{id:"th4-thao-tac-tep-15",type:"tf",q:"Khi đã dọn sạch Thùng rác, tệp vẫn luôn lấy lại được dễ dàng.",explain:"Sai. Dọn sạch Thùng rác thì thường không lấy lại được tệp nữa.",answer:!1},{id:"th4-thao-tac-tep-16",type:"mc",q:"Trong cùng một thư mục, có thể có hai tệp trùng tên hoàn toàn không?",explain:"Trong một thư mục, mỗi tệp cần một tên khác nhau.",options:["Không, máy sẽ báo trùng tên","Có, bao nhiêu tệp trùng tên cũng được","Chỉ được khi tắt máy"],answer:0},{id:"th4-thao-tac-tep-17",type:"multi",q:"Những việc nào cần cẩn thận, nên hỏi người lớn nếu chưa chắc?",explain:"Những việc này có thể làm mất hoặc nhầm tệp. Mở thư mục của mình thì an toàn.",options:["Đổi tên tệp của người khác","Mở thư mục của mình","Xoá thư mục có nhiều tệp","Dọn sạch Thùng rác"],answers:[0,2,3]},{id:"th4-thao-tac-tep-18",type:"mc",q:"Muốn xoá nhiều tệp, trước hết em cần làm gì?",explain:"Phải chọn đúng các tệp rồi mới xoá.",options:["Tắt máy tính","Chọn các tệp cần xoá","Mở trình duyệt web"],answer:1}]},{questions:[{id:"th4-thao-tac-tep-19",type:"mc",q:'Lan đặt tên thư mục là "Thu muc moi" nhưng muốn đổi thành "Tranh ve". Lan làm thế nào?',explain:"Dùng lệnh đổi tên là cách nhanh và không mất tệp.",options:["Xoá thư mục rồi tạo lại thư mục khác","Tắt máy tính rồi bật lại là tự đổi","Nháy nút phải, chọn Đổi tên, gõ tên mới"],answer:2},{id:"th4-thao-tac-tep-20",type:"mc",q:"Minh lỡ tay xoá bài văn của mình. Minh nên làm gì?",explain:"Tệp vừa xoá thường còn trong Thùng rác.",options:["Mở Thùng rác để khôi phục tệp","Dọn sạch Thùng rác cho gọn","Viết lại bài văn từ đầu ngay"],answer:0},{id:"th4-thao-tac-tep-21",type:"tf",q:'Bình muốn xoá thư mục "Trò chơi cũ" nhưng bên trong có bài Toán. Bình nên chuyển bài Toán ra trước khi xoá.',explain:"Đúng. Nếu không, bài Toán sẽ bị xoá theo thư mục.",answer:!0},{id:"th4-thao-tac-tep-22",type:"tf",q:"Dũng thấy thư mục của bạn Nam trên máy lớp nên đổi tên nó cho vui. Dũng làm như vậy là đúng.",explain:"Sai. Không được tự ý đổi tên, xoá tệp của người khác.",answer:!1},{id:"th4-thao-tac-tep-23",type:"mc",q:"Vy tạo thư mục mới nhưng máy báo tên đã có. Vy nên làm gì?",explain:"Trong cùng một nơi, mỗi thư mục cần một tên riêng.",options:["Xoá thư mục cũ dù không biết bên trong có gì","Đặt một tên khác","Tắt máy tính"],answer:1},{id:"th4-thao-tac-tep-24",type:"multi",q:"Hà muốn sắp xếp bài làm. Những việc nào hợp lí?",explain:"Xoá cả thư mục Lớp 4 sẽ mất hết bài.",options:["Xoá các tệp không còn cần","Xoá cả thư mục Lớp 4","Tạo thư mục theo từng môn","Đổi tên tệp cho rõ nghĩa"],answers:[0,2,3]},{id:"th4-thao-tac-tep-25",type:"order",q:'Khoa muốn cất tranh vào thư mục mới tên "Tranh". Sắp xếp các việc.',explain:"Tạo, đặt tên, đưa tệp vào rồi kiểm tra lại.",items:["Tạo thư mục mới",'Đặt tên thư mục là "Tranh"',"Đưa các tệp tranh vào thư mục","Mở thư mục để kiểm tra"]},{id:"th4-thao-tac-tep-26",type:"tf",q:'Ngọc muốn sửa tên tệp "bai1" thành "Bai van ta me". Nội dung bài văn vẫn còn sau khi đổi tên.',explain:"Đúng. Đổi tên không làm mất nội dung tệp.",answer:!0},{id:"th4-thao-tac-tep-27",type:"fill",q:"Điền từ còn thiếu: Tệp bị xoá thường nằm trong Thùng … .",explain:"Thùng rác giữ các tệp vừa bị xoá.",answer:["rác"]}]}],challenge:{questions:[{id:"th4-thao-tac-tep-28",type:"mc",q:'Phúc xoá thư mục "Lớp 4" chứa thư mục "Toán". Điều gì xảy ra với thư mục "Toán"?',explain:"Xoá thư mục mẹ thì thư mục con bên trong cũng bị xoá.",options:["Vẫn còn nguyên ở chỗ cũ",'Tự đổi tên thành "Lớp 5"',"Cũng bị xoá theo"],answer:2},{id:"th4-thao-tac-tep-29",type:"tf",q:"Trước khi xoá một thư mục, em nên mở ra xem bên trong có gì.",explain:"Đúng. Kiểm tra trước giúp không xoá nhầm tệp quan trọng.",answer:!0},{id:"th4-thao-tac-tep-10",type:"order",q:"Sắp xếp các bước tạo một thư mục mới.",explain:"Đây là các bước tạo thư mục mới.",items:["Mở nơi muốn tạo thư mục","Nháy nút phải chuột vào chỗ trống","Chọn lệnh tạo thư mục mới","Gõ tên thư mục","Nhấn Enter"]},{id:"th4-thao-tac-tep-19",type:"mc",q:'Lan đặt tên thư mục là "Thu muc moi" nhưng muốn đổi thành "Tranh ve". Lan làm thế nào?',explain:"Dùng lệnh đổi tên là cách nhanh và không mất tệp.",options:["Xoá thư mục rồi tạo lại thư mục khác","Tắt máy tính rồi bật lại là tự đổi","Nháy nút phải, chọn Đổi tên, gõ tên mới"],answer:2},{id:"th4-thao-tac-tep-21",type:"tf",q:'Bình muốn xoá thư mục "Trò chơi cũ" nhưng bên trong có bài Toán. Bình nên chuyển bài Toán ra trước khi xoá.',explain:"Đúng. Nếu không, bài Toán sẽ bị xoá theo thư mục.",answer:!0},{id:"th4-thao-tac-tep-22",type:"tf",q:"Dũng thấy thư mục của bạn Nam trên máy lớp nên đổi tên nó cho vui. Dũng làm như vậy là đúng.",explain:"Sai. Không được tự ý đổi tên, xoá tệp của người khác.",answer:!1},{id:"th4-thao-tac-tep-24",type:"multi",q:"Hà muốn sắp xếp bài làm. Những việc nào hợp lí?",explain:"Xoá cả thư mục Lớp 4 sẽ mất hết bài.",options:["Xoá các tệp không còn cần","Xoá cả thư mục Lớp 4","Tạo thư mục theo từng môn","Đổi tên tệp cho rõ nghĩa"],answers:[0,2,3]}]},summary:["Tạo thư mục, đổi tên bằng cách nháy nút phải chuột và chọn lệnh.","Nhấn Delete để xoá; tệp xoá thường còn trong Thùng rác.","Xoá thư mục là xoá cả bên trong; không động vào tệp của người khác."]}]},{id:"dao-duc-phap-luat-moi-truong-so",title:"Đạo đức, pháp luật và văn hoá trong môi trường số",lessons:[{id:"th4-ban-quyen",title:"Bài 11: Bản quyền phần mềm và nội dung số",weeks:[17,19],learn:[{title:"Bản quyền là gì",text:"Phần mềm, bài hát, bức ảnh, video, truyện trên mạng đều do người khác làm ra. Tác giả có quyền với sản phẩm của mình, gọi là bản quyền.",example:"🎵 📷 🎬 📖 ©"},{title:"Phần mềm có bản quyền và miễn phí",text:"Có phần mềm phải mua mới được dùng. Có phần mềm miễn phí, được dùng không mất tiền. Chỉ dùng phần mềm khi được phép.",example:"💳 phải mua · 🆓 miễn phí"},{title:"Không sao chép trái phép",text:"Không sao chép, cài đặt phần mềm khi không được phép. Không dùng cách bẻ khoá phần mềm. Làm vậy là vi phạm bản quyền.",example:"🚫 sao chép trái phép"},{title:"Dùng nội dung của người khác",text:"Khi dùng ảnh, bài viết của người khác cho bài học, em cần xin phép khi cần và ghi rõ tác giả hoặc nguồn.",example:"📝 Nguồn: …"}],practice:[{questions:[{id:"th4-ban-quyen-01",type:"tf",q:"Bài hát, bức ảnh, phần mềm do người khác làm ra đều có tác giả.",explain:"Đúng. Mỗi sản phẩm đều có người làm ra, đó là tác giả.",answer:!0},{id:"th4-ban-quyen-02",type:"mc",q:"Quyền của tác giả đối với sản phẩm mình làm ra gọi là gì?",emoji:"©️",explain:"Đó là bản quyền.",options:["Mật khẩu","Từ khoá","Thư mục","Bản quyền"],answer:3},{id:"th4-ban-quyen-03",type:"tf",q:"Mọi phần mềm trên mạng đều được tự do sao chép và cài đặt.",explain:"Sai. Nhiều phần mềm cần mua hoặc phải được phép mới dùng.",answer:!1},{id:"th4-ban-quyen-04",type:"mc",q:"Phần mềm miễn phí là phần mềm như thế nào?",emoji:"🆓",explain:"Phần mềm miễn phí được dùng mà không mất tiền.",options:["Được dùng mà không phải trả tiền","Phải trả tiền mỗi lần bật máy","Chỉ dùng được khi không có điện"],answer:0},{id:"th4-ban-quyen-05",type:"tf",q:"Dùng cách bẻ khoá để dùng phần mềm phải mua là vi phạm bản quyền.",explain:"Đúng. Bẻ khoá là dùng phần mềm khi không được phép.",answer:!0},{id:"th4-ban-quyen-06",type:"mc",q:"Khi dùng ảnh của người khác trong bài trình chiếu, em nên làm gì?",emoji:"🖼️",explain:"Ghi nguồn là tôn trọng tác giả.",options:["Nói đó là ảnh mình chụp","Ghi rõ tác giả hoặc nguồn","Xoá tên tác giả trên ảnh"],answer:1},{id:"th4-ban-quyen-07",type:"tf",q:"Chép bài viết của người khác rồi nói là của mình là việc đúng.",explain:"Sai. Đó là không trung thực và không tôn trọng tác giả.",answer:!1},{id:"th4-ban-quyen-08",type:"mc",q:"Ai được quyết định cho người khác dùng sản phẩm của mình?",explain:"Tác giả có bản quyền với sản phẩm của mình.",options:["Bất kì ai thấy sản phẩm","Tác giả của sản phẩm đó","Người tải sản phẩm về"],answer:1},{id:"th4-ban-quyen-09",type:"tf",q:"Em nên hỏi người lớn trước khi cài một phần mềm mới.",explain:"Đúng. Người lớn giúp em biết phần mềm có được phép dùng và có an toàn không.",answer:!0}]},{questions:[{id:"th4-ban-quyen-10",type:"match",q:"Ghép việc làm với nhận xét.",explain:"Dùng phần mềm khi được phép và ghi nguồn là việc làm đúng.",pairs:[["Dùng phần mềm miễn phí","Được phép"],["Bẻ khoá phần mềm phải mua","Vi phạm bản quyền"],["Ghi nguồn khi dùng ảnh","Tôn trọng tác giả"]]},{id:"th4-ban-quyen-11",type:"multi",q:"Những việc nào tôn trọng bản quyền?",explain:"Sao chép phần mềm phải mua cho người khác là vi phạm bản quyền.",options:["Ghi nguồn khi dùng ảnh của người khác","Xin phép trước khi dùng tác phẩm của bạn","Sao chép phần mềm phải mua cho cả lớp","Dùng phần mềm miễn phí hoặc đã mua"],answers:[0,1,3]},{id:"th4-ban-quyen-12",type:"mc",q:"Vì sao cần tôn trọng bản quyền?",explain:"Tôn trọng bản quyền là tôn trọng công sức của tác giả.",options:["Vì phần mềm sẽ đẹp và chạy nhanh hơn","Vì máy tính sẽ không bao giờ bị hỏng","Vì tác giả đã bỏ công sức làm ra sản phẩm"],answer:2},{id:"th4-ban-quyen-13",type:"tf",q:"Phần mềm bị bẻ khoá luôn an toàn tuyệt đối cho máy tính.",explain:"Sai. Phần mềm bẻ khoá có thể chứa thứ gây hại cho máy.",answer:!1},{id:"th4-ban-quyen-14",type:"tf",q:"Nếu tải được trên mạng thì mọi bài hát đều được dùng tự do cho mọi việc.",explain:"Sai. Bài hát có tác giả, có bản quyền. Cần xem điều kiện sử dụng.",answer:!1},{id:"th4-ban-quyen-15",type:"mc",q:"Bạn tặng em đĩa phần mềm sao chép trái phép. Em nên làm gì?",explain:"Không dùng phần mềm sao chép trái phép.",options:["Không dùng và nói với người lớn","Cài ngay vào máy của lớp","Sao chép thêm tặng bạn khác"],answer:0},{id:"th4-ban-quyen-16",type:"order",q:"Sắp xếp các việc khi muốn dùng một bức ảnh trên mạng cho bài thuyết trình.",explain:"Xem được phép rồi mới dùng, và luôn ghi nguồn.",items:["Tìm ảnh phù hợp","Xem ảnh có được phép dùng không","Chèn ảnh vào bài","Ghi nguồn của ảnh"]},{id:"th4-ban-quyen-17",type:"mc",q:"Dòng nào là cách ghi nguồn cho bức ảnh lấy từ mạng?",explain:"Ghi nơi lấy ảnh giúp người xem biết nguồn.",options:["Ảnh do chính em tự chụp ở vườn","Ảnh: trang web Thư viện thiên nhiên","Ảnh đẹp, không cần ghi tên ai cả"],answer:1},{id:"th4-ban-quyen-18",type:"tf",q:"Tác phẩm của bạn cùng lớp cũng có bản quyền, em cần xin phép nếu muốn dùng.",explain:"Đúng. Bạn là tác giả của tác phẩm mình làm ra.",answer:!0}]},{questions:[{id:"th4-ban-quyen-19",type:"mc",q:"An thích một trò chơi phải mua. Bạn rủ An cài bản bẻ khoá. An nên làm gì?",emoji:"🎮",explain:"Bản bẻ khoá vi phạm bản quyền và có thể gây hại cho máy.",options:["Từ chối, nhờ bố mẹ chọn bản được phép","Cài bản bẻ khoá cho đỡ tốn tiền","Cài rồi chia cho cả lớp cùng chơi"],answer:0},{id:"th4-ban-quyen-20",type:"mc",q:"Bình dùng bài thơ trên mạng cho bài trình chiếu. Bình nên làm gì?",explain:"Ghi tên tác giả là tôn trọng bản quyền.",options:["Ghi tên mình là tác giả","Sửa vài chữ rồi nói là của mình","Ghi tên tác giả bài thơ"],answer:2},{id:"th4-ban-quyen-21",type:"tf",q:"Chi vẽ một bức tranh trên máy tính. Chi là tác giả của bức tranh đó.",emoji:"🎨",explain:"Đúng. Ai làm ra sản phẩm thì là tác giả của sản phẩm đó.",answer:!0},{id:"th4-ban-quyen-22",type:"tf",q:"Dũng mượn bài trình chiếu của Nam, đổi tên tác giả thành Dũng rồi nộp. Dũng làm vậy là đúng.",explain:"Sai. Đó là lấy công sức của bạn, không trung thực.",answer:!1},{id:"th4-ban-quyen-23",type:"multi",q:"Phòng máy của trường cần phần mềm vẽ. Những cách nào đúng?",explain:"Dùng phần mềm miễn phí hoặc mua là được phép. Bản bẻ khoá thì không.",options:["Nhà trường mua phần mềm","Tải bản bẻ khoá trên mạng","Dùng phần mềm vẽ miễn phí"],answers:[0,2]},{id:"th4-ban-quyen-24",type:"mc",q:"Hà muốn dùng ảnh do bạn Lan chụp cho bài làm. Hà nên làm gì?",emoji:"📷",explain:"Xin phép và ghi tên người chụp là tôn trọng tác giả.",options:["Lấy dùng mà không hỏi ai","Nói với cô giáo là mình tự chụp","Hỏi Lan và ghi tên Lan là người chụp"],answer:2},{id:"th4-ban-quyen-25",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi tình huống đều cần tôn trọng bản quyền.",pairs:[["Muốn cài phần mềm mới","Hỏi người lớn trước"],["Dùng ảnh trên mạng","Ghi nguồn"],["Được rủ dùng phần mềm bẻ khoá","Từ chối"],["Muốn dùng tranh của bạn","Xin phép bạn"]]},{id:"th4-ban-quyen-26",type:"tf",q:"Khoa dùng phần mềm luyện gõ miễn phí mà thầy giáo giới thiệu. Khoa dùng phần mềm đúng cách.",explain:"Đúng. Phần mềm miễn phí, được thầy giới thiệu là được phép dùng.",answer:!0},{id:"th4-ban-quyen-27",type:"fill",q:"Điền từ còn thiếu: Quyền của tác giả đối với sản phẩm mình làm ra gọi là bản … .",explain:"Đó là bản quyền.",answer:["quyền"]}]}],challenge:{questions:[{id:"th4-ban-quyen-28",type:"mc",q:"Câu nào đúng nhất về bản quyền?",explain:"Phần mềm, ảnh, nhạc, video đều có bản quyền.",options:["Chỉ dùng phần mềm, nội dung số khi được phép","Cái gì có trên mạng cũng được dùng tự do","Chỉ phần mềm mới có bản quyền, ảnh thì không"],answer:0},{id:"th4-ban-quyen-29",type:"tf",q:"Ghi nguồn khi dùng thông tin là cách giúp người đọc kiểm tra lại thông tin.",explain:"Đúng. Ghi nguồn vừa tôn trọng tác giả vừa giúp người đọc kiểm tra.",answer:!0},{id:"th4-ban-quyen-19",type:"mc",q:"An thích một trò chơi phải mua. Bạn rủ An cài bản bẻ khoá. An nên làm gì?",emoji:"🎮",explain:"Bản bẻ khoá vi phạm bản quyền và có thể gây hại cho máy.",options:["Từ chối, nhờ bố mẹ chọn bản được phép","Cài bản bẻ khoá cho đỡ tốn tiền","Cài rồi chia cho cả lớp cùng chơi"],answer:0},{id:"th4-ban-quyen-22",type:"tf",q:"Dũng mượn bài trình chiếu của Nam, đổi tên tác giả thành Dũng rồi nộp. Dũng làm vậy là đúng.",explain:"Sai. Đó là lấy công sức của bạn, không trung thực.",answer:!1},{id:"th4-ban-quyen-23",type:"multi",q:"Phòng máy của trường cần phần mềm vẽ. Những cách nào đúng?",explain:"Dùng phần mềm miễn phí hoặc mua là được phép. Bản bẻ khoá thì không.",options:["Nhà trường mua phần mềm","Tải bản bẻ khoá trên mạng","Dùng phần mềm vẽ miễn phí"],answers:[0,2]},{id:"th4-ban-quyen-24",type:"mc",q:"Hà muốn dùng ảnh do bạn Lan chụp cho bài làm. Hà nên làm gì?",emoji:"📷",explain:"Xin phép và ghi tên người chụp là tôn trọng tác giả.",options:["Lấy dùng mà không hỏi ai","Nói với cô giáo là mình tự chụp","Hỏi Lan và ghi tên Lan là người chụp"],answer:2},{id:"th4-ban-quyen-14",type:"tf",q:"Nếu tải được trên mạng thì mọi bài hát đều được dùng tự do cho mọi việc.",explain:"Sai. Bài hát có tác giả, có bản quyền. Cần xem điều kiện sử dụng.",answer:!1}]},summary:["Phần mềm và nội dung số đều có tác giả và bản quyền.","Chỉ dùng phần mềm khi được phép; không sao chép, bẻ khoá trái phép.","Khi dùng ảnh, bài viết của người khác, cần xin phép khi cần và ghi nguồn."]}]},{id:"ung-dung-tin-hoc",title:"Ứng dụng tin học",lessons:[{id:"th4-tao-bai-trinh-chieu",title:"Bài 12: Tạo bài trình chiếu",weeks:[20,21],learn:[{title:"Phần mềm trình chiếu",text:"Phần mềm trình chiếu giúp em tạo bài trình chiếu để giới thiệu, thuyết trình trước lớp.",example:"📊 bài trình chiếu"},{title:"Trang chiếu",text:"Bài trình chiếu gồm nhiều trang chiếu. Trang đầu thường là trang tiêu đề, ghi tên bài và tên người trình bày.",example:"🗂️ trang 1: tiêu đề · trang 2, 3…: nội dung"},{title:"Thêm nội dung",text:"Em gõ chữ vào khung có sẵn, thêm trang chiếu mới, chèn hình ảnh cho bài thêm sinh động.",example:"➕ trang mới · 🖼️ chèn ảnh"},{title:"Trình chiếu và lưu bài",text:"Chọn chế độ trình chiếu để chiếu toàn màn hình. Nhấn phím Esc để thoát. Nhớ lưu bài thành tệp.",example:"▶️ trình chiếu · Esc thoát · 💾 lưu"}],practice:[{questions:[{id:"th4-tao-bai-trinh-chieu-01",type:"mc",q:"Phần mềm nào giúp em tạo bài để thuyết trình trước lớp?",emoji:"📊",explain:"Phần mềm trình chiếu dùng để tạo bài trình chiếu.",options:["Phần mềm luyện gõ","Trình duyệt web","Phần mềm nghe nhạc","Phần mềm trình chiếu"],answer:3},{id:"th4-tao-bai-trinh-chieu-02",type:"tf",q:"Một bài trình chiếu có thể gồm nhiều trang chiếu.",explain:"Đúng. Bài trình chiếu thường có nhiều trang chiếu nối tiếp nhau.",answer:!0},{id:"th4-tao-bai-trinh-chieu-03",type:"mc",q:"Trang đầu tiên của bài trình chiếu thường là trang gì?",explain:"Trang tiêu đề ghi tên bài và tên người trình bày.",options:["Trang cuối cùng","Trang tiêu đề","Trang trắng không có chữ"],answer:1},{id:"th4-tao-bai-trinh-chieu-04",type:"tf",q:"Trên trang chiếu chỉ được có chữ, không được chèn hình ảnh.",explain:"Sai. Em có thể chèn hình ảnh vào trang chiếu.",answer:!1},{id:"th4-tao-bai-trinh-chieu-05",type:"mc",q:"Khi đang trình chiếu, nhấn phím nào để thoát ra?",explain:"Phím Esc dùng để thoát chế độ trình chiếu.",options:["Phím A","Phím cách","Esc"],answer:2},{id:"th4-tao-bai-trinh-chieu-06",type:"tf",q:"Trang tiêu đề thường là trang cuối cùng của bài trình chiếu.",explain:"Sai. Trang tiêu đề thường là trang đầu tiên, ghi tên bài và tên người trình bày.",answer:!1},{id:"th4-tao-bai-trinh-chieu-07",type:"mc",q:"Muốn có thêm trang để viết tiếp nội dung, em làm gì?",explain:"Lệnh thêm trang chiếu mới tạo thêm trang.",options:["Tắt phần mềm trình chiếu","Thêm trang chiếu mới","Xoá trang tiêu đề"],answer:1},{id:"th4-tao-bai-trinh-chieu-08",type:"tf",q:"Làm xong bài trình chiếu không cần lưu, tắt máy bài vẫn còn.",explain:"Sai. Cần lưu bài thành tệp, nếu không sẽ mất bài.",answer:!1},{id:"th4-tao-bai-trinh-chieu-09",type:"tf",q:"Chế độ trình chiếu cho các trang hiện toàn màn hình.",explain:"Đúng. Trình chiếu toàn màn hình giúp cả lớp dễ xem.",answer:!0}]},{questions:[{id:"th4-tao-bai-trinh-chieu-10",type:"order",q:"Sắp xếp các bước tạo bài trình chiếu đơn giản.",explain:"Đây là các bước tạo một bài trình chiếu đơn giản.",items:["Mở phần mềm trình chiếu","Gõ tên bài ở trang tiêu đề","Thêm trang chiếu mới và gõ nội dung","Lưu bài trình chiếu"]},{id:"th4-tao-bai-trinh-chieu-11",type:"match",q:"Ghép việc cần làm với cách làm.",explain:"Mỗi việc có một cách làm trong phần mềm trình chiếu.",pairs:[["Chiếu toàn màn hình","Chọn chế độ trình chiếu"],["Thoát trình chiếu","Nhấn phím Esc"],["Thêm hình minh hoạ","Chèn hình ảnh"],["Giữ lại bài đã làm","Lưu bài thành tệp"]]},{id:"th4-tao-bai-trinh-chieu-12",type:"mc",q:"Vì sao nên chèn hình ảnh vào trang chiếu?",explain:"Hình ảnh giúp người xem dễ hiểu và thích thú hơn.",options:["Để bài sinh động, dễ hiểu hơn","Để bài có thật nhiều chữ hơn","Để máy tính tự lưu bài"],answer:0},{id:"th4-tao-bai-trinh-chieu-13",type:"multi",q:"Trang chiếu có thể chứa những gì?",explain:"Trang chiếu chứa chữ, tiêu đề, hình ảnh; không chứa đồ vật thật.",options:["Hình ảnh","Tiêu đề","Chiếc bút chì thật","Chữ"],answers:[0,1,3]},{id:"th4-tao-bai-trinh-chieu-14",type:"tf",q:"Mỗi trang chiếu nên viết ít chữ, chỉ ghi ý chính.",explain:"Đúng. Ít chữ, ý chính rõ ràng thì người xem dễ theo dõi.",answer:!0},{id:"th4-tao-bai-trinh-chieu-15",type:"tf",q:"Nên viết cả một bài văn dài vào một trang chiếu.",explain:"Sai. Chữ quá nhiều sẽ nhỏ và khó đọc. Nên chia ra nhiều trang.",answer:!1},{id:"th4-tao-bai-trinh-chieu-16",type:"mc",q:"Bài trình chiếu đã lưu được cất ở đâu?",explain:"Bài trình chiếu được lưu thành tệp trong thư mục.",options:["Trong chiếc loa của máy","Thành một tệp trong thư mục","Trên trang web của máy tìm kiếm"],answer:1},{id:"th4-tao-bai-trinh-chieu-17",type:"mc",q:"Khi trình chiếu, cách nào để chuyển sang trang tiếp theo?",explain:"Nháy chuột hoặc nhấn phím mũi tên để sang trang tiếp.",options:["Nhấn phím Esc ở góc bàn phím","Tắt màn hình rồi bật lại","Nháy chuột hoặc nhấn phím mũi tên phải"],answer:2},{id:"th4-tao-bai-trinh-chieu-18",type:"fill",q:"Điền từ còn thiếu: Bài trình chiếu gồm nhiều trang … .",explain:"Mỗi trang trong bài trình chiếu gọi là trang chiếu.",answer:["chiếu"]}]},{questions:[{id:"th4-tao-bai-trinh-chieu-19",type:"mc",q:"Lan làm bài giới thiệu về gia đình. Trang tiêu đề nên ghi gì?",emoji:"👨‍👩‍👧",explain:"Trang tiêu đề ghi tên bài và tên người trình bày.",options:["Gia đình em, kèm tên người trình bày","Toàn bộ bài văn tả mẹ thật dài","Một danh sách các món ăn em thích"],answer:0},{id:"th4-tao-bai-trinh-chieu-20",type:"mc",q:"Minh có 4 ý muốn giới thiệu về con mèo. Minh nên làm thế nào?",emoji:"🐱",explain:"Chia mỗi ý một trang giúp bài rõ ràng, dễ theo dõi.",options:["Viết cả 4 ý thật dài vào trang tiêu đề","Chỉ chèn ảnh, không ghi ý nào","Mỗi ý một trang chiếu, có hình minh hoạ"],answer:2},{id:"th4-tao-bai-trinh-chieu-21",type:"tf",q:"Nam làm xong bài trình chiếu, lưu bài vào thư mục Tin học. Nam làm đúng.",explain:"Đúng. Lưu vào thư mục phù hợp giúp dễ tìm lại.",answer:!0},{id:"th4-tao-bai-trinh-chieu-22",type:"tf",q:"Hà đang trình chiếu thì muốn quay về sửa bài. Hà nhấn phím Enter để thoát.",explain:"Sai. Muốn thoát chế độ trình chiếu, Hà nhấn phím Esc.",answer:!1},{id:"th4-tao-bai-trinh-chieu-23",type:"multi",q:"Chi muốn bài trình chiếu về mùa xuân thật hay. Chi nên làm những gì?",emoji:"🌸",explain:"Chữ quá nhỏ thì người xem không đọc được.",options:["Có trang tiêu đề rõ ràng","Chèn ảnh hoa mai, hoa đào","Mỗi trang ghi ý chính ngắn gọn","Viết chữ thật nhỏ cho vừa nhiều"],answers:[0,1,2]},{id:"th4-tao-bai-trinh-chieu-24",type:"order",q:"Dũng thuyết trình trước lớp. Sắp xếp các việc.",explain:"Mở bài, trình chiếu, chuyển trang rồi kết thúc.",items:["Mở tệp bài trình chiếu","Chọn chế độ trình chiếu","Chuyển trang và nói từng ý","Nhấn Esc để kết thúc"]},{id:"th4-tao-bai-trinh-chieu-25",type:"mc",q:"Thảo muốn thêm ảnh chú chó vào trang chiếu. Thảo dùng lệnh nào?",emoji:"🐶",explain:"Lệnh chèn hình ảnh giúp đưa ảnh vào trang chiếu.",options:["Xoá trang chiếu","Chèn hình ảnh","Thêm trang tiêu đề"],answer:1},{id:"th4-tao-bai-trinh-chieu-26",type:"tf",q:"Tùng lấy ảnh trên mạng cho bài trình chiếu và ghi nguồn ở cuối trang. Tùng làm đúng.",explain:"Đúng. Ghi nguồn là tôn trọng bản quyền.",answer:!0},{id:"th4-tao-bai-trinh-chieu-27",type:"match",q:"Ghép phần của bài trình chiếu với nội dung phù hợp.",explain:"Bài trình chiếu có phần mở đầu, nội dung và kết thúc.",pairs:[["Trang tiêu đề","Tên bài và người trình bày"],["Trang nội dung","Các ý chính kèm hình"],["Trang cuối","Lời cảm ơn người nghe"]]}]}],challenge:{questions:[{id:"th4-tao-bai-trinh-chieu-28",type:"mc",q:"Ngọc mở bài trình chiếu hôm qua nhưng không thấy. Có thể Ngọc đã quên làm gì?",explain:"Không lưu bài thì tắt phần mềm bài sẽ mất.",options:["Lưu bài trình chiếu","Chèn thêm hình ảnh","Thêm trang tiêu đề"],answer:0},{id:"th4-tao-bai-trinh-chieu-29",type:"tf",q:"Có thể sắp xếp lại thứ tự các trang chiếu trong bài.",explain:"Đúng. Em có thể kéo thả để đổi thứ tự trang chiếu.",answer:!0},{id:"th4-tao-bai-trinh-chieu-19",type:"mc",q:"Lan làm bài giới thiệu về gia đình. Trang tiêu đề nên ghi gì?",emoji:"👨‍👩‍👧",explain:"Trang tiêu đề ghi tên bài và tên người trình bày.",options:["Gia đình em, kèm tên người trình bày","Toàn bộ bài văn tả mẹ thật dài","Một danh sách các món ăn em thích"],answer:0},{id:"th4-tao-bai-trinh-chieu-20",type:"mc",q:"Minh có 4 ý muốn giới thiệu về con mèo. Minh nên làm thế nào?",emoji:"🐱",explain:"Chia mỗi ý một trang giúp bài rõ ràng, dễ theo dõi.",options:["Viết cả 4 ý thật dài vào trang tiêu đề","Chỉ chèn ảnh, không ghi ý nào","Mỗi ý một trang chiếu, có hình minh hoạ"],answer:2},{id:"th4-tao-bai-trinh-chieu-23",type:"multi",q:"Chi muốn bài trình chiếu về mùa xuân thật hay. Chi nên làm những gì?",emoji:"🌸",explain:"Chữ quá nhỏ thì người xem không đọc được.",options:["Có trang tiêu đề rõ ràng","Chèn ảnh hoa mai, hoa đào","Mỗi trang ghi ý chính ngắn gọn","Viết chữ thật nhỏ cho vừa nhiều"],answers:[0,1,2]},{id:"th4-tao-bai-trinh-chieu-24",type:"order",q:"Dũng thuyết trình trước lớp. Sắp xếp các việc.",explain:"Mở bài, trình chiếu, chuyển trang rồi kết thúc.",items:["Mở tệp bài trình chiếu","Chọn chế độ trình chiếu","Chuyển trang và nói từng ý","Nhấn Esc để kết thúc"]},{id:"th4-tao-bai-trinh-chieu-10",type:"order",q:"Sắp xếp các bước tạo bài trình chiếu đơn giản.",explain:"Đây là các bước tạo một bài trình chiếu đơn giản.",items:["Mở phần mềm trình chiếu","Gõ tên bài ở trang tiêu đề","Thêm trang chiếu mới và gõ nội dung","Lưu bài trình chiếu"]}]},summary:["Bài trình chiếu gồm nhiều trang chiếu, trang đầu là trang tiêu đề.","Có thể thêm trang chiếu, gõ chữ, chèn hình ảnh.","Chọn trình chiếu để chiếu toàn màn hình, nhấn Esc để thoát; nhớ lưu bài."]},{id:"th4-hieu-ung-trang-chieu",title:"Bài 13: Định dạng và hiệu ứng trang chiếu",weeks:[22,23],learn:[{title:"Định dạng chữ",text:"Em có thể đổi phông chữ, cỡ chữ, màu chữ để trang chiếu rõ ràng, đẹp mắt.",example:"🔠 phông · 🔢 cỡ · 🎨 màu"},{title:"Chữ dễ đọc",text:"Chữ cần đủ to, màu chữ khác hẳn màu nền. Ví dụ chữ đen trên nền trắng, chữ trắng trên nền xanh đậm.",example:"⬛ trên ⬜ ✅ · 🟨 trên ⬜ ❌"},{title:"Hiệu ứng chuyển trang",text:"Hiệu ứng chuyển trang là cách trang chiếu xuất hiện khi chuyển từ trang này sang trang khác, như hiện dần, trượt vào.",example:"🗂️ ➡️ 🗂️ ✨"},{title:"Dùng vừa phải",text:"Chỉ nên dùng ít hiệu ứng, nhẹ nhàng. Quá nhiều hiệu ứng làm người xem rối mắt.",example:"✨ vừa đủ"}],practice:[{questions:[{id:"th4-hieu-ung-trang-chieu-01",type:"mc",q:"Hiệu ứng chuyển trang là gì?",emoji:"✨",explain:"Hiệu ứng chuyển trang làm việc chuyển trang thêm sinh động.",options:["Cách trang chiếu hiện ra khi chuyển trang","Cách gõ chữ có dấu tiếng Việt","Cách lưu bài vào một thư mục"],answer:0},{id:"th4-hieu-ung-trang-chieu-02",type:"tf",q:"Chữ trên trang chiếu chỉ có một màu đen, không đổi được.",emoji:"🎨",explain:"Sai. Em có thể đổi màu chữ trên trang chiếu.",answer:!1},{id:"th4-hieu-ung-trang-chieu-03",type:"mc",q:"Chữ trên trang chiếu nên như thế nào?",explain:"Chữ to, rõ giúp cả lớp đọc được.",options:["Thật nhỏ để ghi được nhiều","Cùng màu với màu nền","Đủ to, dễ đọc"],answer:2},{id:"th4-hieu-ung-trang-chieu-04",type:"tf",q:"Chữ vàng nhạt trên nền trắng rất dễ đọc.",explain:"Sai. Vàng nhạt trên nền trắng rất khó đọc vì hai màu gần giống nhau.",answer:!1},{id:"th4-hieu-ung-trang-chieu-05",type:"mc",q:"Muốn chữ to hơn, em thay đổi gì?",explain:"Tăng cỡ chữ để chữ to hơn.",options:["Màu nền","Cỡ chữ","Tên tệp"],answer:1},{id:"th4-hieu-ung-trang-chieu-06",type:"tf",q:"Nên dùng thật nhiều hiệu ứng trên mỗi trang để bài thật vui.",explain:"Sai. Quá nhiều hiệu ứng làm người xem rối mắt.",answer:!1},{id:"th4-hieu-ung-trang-chieu-07",type:"mc",q:"Chữ đen trên nền nào dễ đọc nhất?",explain:"Màu chữ khác hẳn màu nền thì dễ đọc.",options:["Nền trắng","Nền đen","Nền xanh đậm"],answer:0},{id:"th4-hieu-ung-trang-chieu-08",type:"tf",q:"Phông chữ, cỡ chữ, màu chữ đều là định dạng chữ.",explain:"Đúng. Đó là ba cách định dạng chữ thường dùng.",answer:!0},{id:"th4-hieu-ung-trang-chieu-09",type:"tf",q:"Hiệu ứng chuyển trang chỉ có tác dụng khi chuyển từ trang này sang trang khác.",explain:"Đúng. Hiệu ứng chuyển trang xuất hiện lúc đổi trang.",answer:!0}]},{questions:[{id:"th4-hieu-ung-trang-chieu-10",type:"match",q:"Ghép điều muốn làm với việc cần thay đổi.",explain:"Mỗi điều muốn làm cần thay đổi đúng một thuộc tính.",pairs:[["Chữ to hơn","Cỡ chữ"],["Chữ màu đỏ","Màu chữ"],["Kiểu chữ khác","Phông chữ"],["Trang hiện ra từ từ","Hiệu ứng chuyển trang"]]},{id:"th4-hieu-ung-trang-chieu-11",type:"multi",q:"Cặp màu chữ và màu nền nào dễ đọc?",explain:"Chữ và nền khác hẳn màu nhau thì dễ đọc.",options:["Chữ trắng, nền xanh đậm","Chữ vàng nhạt, nền trắng","Chữ xám nhạt, nền xám","Chữ đen, nền trắng"],answers:[0,3]},{id:"th4-hieu-ung-trang-chieu-12",type:"mc",q:"Vì sao chỉ nên dùng ít hiệu ứng?",explain:"Hiệu ứng vừa phải giúp người xem chú ý vào nội dung.",options:["Để máy in in bài được nhanh hơn","Để tệp không bao giờ bị xoá mất","Để người xem tập trung vào nội dung"],answer:2},{id:"th4-hieu-ung-trang-chieu-13",type:"tf",q:"Định dạng chữ giúp tiêu đề nổi bật hơn nội dung.",explain:"Đúng. Tiêu đề có thể to hơn, đậm hơn hoặc màu khác.",answer:!0},{id:"th4-hieu-ung-trang-chieu-14",type:"tf",q:"Đổi màu chữ sẽ làm mất nội dung của trang chiếu.",explain:"Sai. Đổi màu chỉ thay cách chữ hiện ra, nội dung vẫn giữ nguyên.",answer:!1},{id:"th4-hieu-ung-trang-chieu-15",type:"order",q:"Sắp xếp các bước đổi màu chữ tiêu đề.",explain:"Phải chọn chữ trước rồi mới đổi màu.",items:["Chọn phần chữ tiêu đề","Mở lệnh màu chữ","Chọn màu mong muốn"]},{id:"th4-hieu-ung-trang-chieu-16",type:"mc",q:"Muốn đổi định dạng một dòng chữ, trước tiên em phải làm gì?",explain:"Chọn chữ trước thì lệnh định dạng mới áp dụng đúng chỗ.",options:["Lưu bài lại","Chọn dòng chữ đó","Thêm một trang chiếu"],answer:1},{id:"th4-hieu-ung-trang-chieu-17",type:"mc",q:"Tiêu đề nên có cỡ chữ thế nào so với nội dung?",explain:"Tiêu đề to hơn giúp người xem nhận ra ngay.",options:["Nhỏ hơn nội dung","To hơn nội dung","Không cần có chữ"],answer:1},{id:"th4-hieu-ung-trang-chieu-18",type:"fill",q:"Điền từ còn thiếu: Để chữ to hơn, em tăng … chữ.",explain:"Tăng cỡ chữ để chữ to hơn.",answer:["cỡ"]}]},{questions:[{id:"th4-hieu-ung-trang-chieu-19",type:"mc",q:"Phúc làm chữ xanh lá trên nền xanh lá. Cả lớp không đọc được. Phúc nên sửa thế nào?",explain:"Chữ và nền phải khác màu rõ ràng thì mới đọc được.",options:["Đổi chữ sang màu trắng cho khác nền","Thêm thật nhiều hiệu ứng nữa","Làm chữ nhỏ hơn nữa cho gọn"],answer:0},{id:"th4-hieu-ung-trang-chieu-20",type:"mc",q:"Vy dùng 5 hiệu ứng khác nhau trên một trang. Bạn bè thấy rối mắt. Vy nên làm gì?",explain:"Hiệu ứng vừa phải giúp bài dễ xem hơn.",options:["Thêm một hiệu ứng thứ sáu nữa","Xoá hết chữ, chỉ để lại hiệu ứng","Bớt đi, chọn một hiệu ứng nhẹ nhàng"],answer:2},{id:"th4-hieu-ung-trang-chieu-21",type:"tf",q:"An đặt tiêu đề to và đậm hơn phần nội dung. An làm đúng.",explain:"Đúng. Tiêu đề nổi bật giúp người xem dễ theo dõi.",answer:!0},{id:"th4-hieu-ung-trang-chieu-22",type:"tf",q:"Bình để cỡ chữ rất nhỏ cho mỗi trang ghi được nhiều chữ. Bạn ngồi cuối lớp vẫn đọc dễ dàng.",explain:"Sai. Chữ quá nhỏ thì bạn ngồi xa không đọc được.",answer:!1},{id:"th4-hieu-ung-trang-chieu-23",type:"multi",q:"Khoa muốn trang chiếu dễ đọc. Khoa nên làm những việc nào?",explain:"Dùng quá nhiều hiệu ứng làm người xem rối mắt.",options:["Chỉ ghi ý chính","Dùng thật nhiều hiệu ứng","Chọn cỡ chữ đủ to","Chọn màu chữ khác hẳn màu nền"],answers:[0,2,3]},{id:"th4-hieu-ung-trang-chieu-24",type:"mc",q:"Minh chọn hiệu ứng chuyển trang cho trang 2. Hiệu ứng xuất hiện khi nào?",explain:"Hiệu ứng chuyển trang xuất hiện lúc trang chiếu hiện ra.",options:["Khi bấm lưu bài trình chiếu","Khi tắt phần mềm trình chiếu","Khi chuyển sang trang 2"],answer:2},{id:"th4-hieu-ung-trang-chieu-25",type:"match",q:"Ghép vấn đề với cách sửa.",explain:"Mỗi vấn đề có một cách sửa phù hợp.",pairs:[["Chữ khó đọc vì quá nhỏ","Tăng cỡ chữ"],["Chữ trùng màu nền","Đổi màu chữ"],["Quá nhiều hiệu ứng","Bớt hiệu ứng"]]},{id:"th4-hieu-ung-trang-chieu-26",type:"tf",q:"Lan chọn cùng một kiểu hiệu ứng nhẹ nhàng cho tất cả các trang. Bài của Lan trông gọn gàng.",explain:"Đúng. Dùng hiệu ứng thống nhất giúp bài gọn gàng.",answer:!0},{id:"th4-hieu-ung-trang-chieu-27",type:"order",q:"Sắp xếp các bước thêm hiệu ứng chuyển trang.",explain:"Chọn trang, chọn hiệu ứng rồi trình chiếu để xem thử.",items:["Chọn trang chiếu cần thêm hiệu ứng","Mở phần hiệu ứng chuyển trang","Chọn một hiệu ứng","Trình chiếu để xem thử"]}]}],challenge:{questions:[{id:"th4-hieu-ung-trang-chieu-28",type:"mc",q:'Thảo muốn tiêu đề "Mùa hè của em" nổi bật. Cách nào hợp lí nhất?',emoji:"☀️",explain:"Chữ to, đậm, màu tương phản làm tiêu đề nổi bật.",options:["Chữ to, đậm, màu khác hẳn màu nền","Chữ nhỏ, màu giống màu nền","Chữ thật nhỏ đặt ở góc trang"],answer:0},{id:"th4-hieu-ung-trang-chieu-29",type:"tf",q:"Định dạng chữ và hiệu ứng nên giúp người xem hiểu bài, không làm họ rối mắt.",explain:"Đúng. Định dạng và hiệu ứng để phục vụ nội dung.",answer:!0},{id:"th4-hieu-ung-trang-chieu-19",type:"mc",q:"Phúc làm chữ xanh lá trên nền xanh lá. Cả lớp không đọc được. Phúc nên sửa thế nào?",explain:"Chữ và nền phải khác màu rõ ràng thì mới đọc được.",options:["Đổi chữ sang màu trắng cho khác nền","Thêm thật nhiều hiệu ứng nữa","Làm chữ nhỏ hơn nữa cho gọn"],answer:0},{id:"th4-hieu-ung-trang-chieu-20",type:"mc",q:"Vy dùng 5 hiệu ứng khác nhau trên một trang. Bạn bè thấy rối mắt. Vy nên làm gì?",explain:"Hiệu ứng vừa phải giúp bài dễ xem hơn.",options:["Thêm một hiệu ứng thứ sáu nữa","Xoá hết chữ, chỉ để lại hiệu ứng","Bớt đi, chọn một hiệu ứng nhẹ nhàng"],answer:2},{id:"th4-hieu-ung-trang-chieu-23",type:"multi",q:"Khoa muốn trang chiếu dễ đọc. Khoa nên làm những việc nào?",explain:"Dùng quá nhiều hiệu ứng làm người xem rối mắt.",options:["Chỉ ghi ý chính","Dùng thật nhiều hiệu ứng","Chọn cỡ chữ đủ to","Chọn màu chữ khác hẳn màu nền"],answers:[0,2,3]},{id:"th4-hieu-ung-trang-chieu-24",type:"mc",q:"Minh chọn hiệu ứng chuyển trang cho trang 2. Hiệu ứng xuất hiện khi nào?",explain:"Hiệu ứng chuyển trang xuất hiện lúc trang chiếu hiện ra.",options:["Khi bấm lưu bài trình chiếu","Khi tắt phần mềm trình chiếu","Khi chuyển sang trang 2"],answer:2},{id:"th4-hieu-ung-trang-chieu-14",type:"tf",q:"Đổi màu chữ sẽ làm mất nội dung của trang chiếu.",explain:"Sai. Đổi màu chỉ thay cách chữ hiện ra, nội dung vẫn giữ nguyên.",answer:!1}]},summary:["Định dạng chữ gồm phông chữ, cỡ chữ, màu chữ.","Chữ cần đủ to, màu chữ khác hẳn màu nền.","Hiệu ứng chuyển trang làm bài sinh động; chỉ dùng vừa phải."]},{id:"th4-soan-thao-van-ban",title:"Bài 14: Soạn thảo văn bản",weeks:[24,26],learn:[{title:"Phần mềm soạn thảo",text:"Phần mềm soạn thảo văn bản giúp em gõ, sửa, trình bày bài văn, thiệp mời, thời khoá biểu. Vạch nhấp nháy là con trỏ soạn thảo, chữ gõ vào sẽ hiện ở đó.",example:"📝 | con trỏ soạn thảo"},{title:"Gõ tiếng Việt kiểu Telex",text:"aa → â, aw → ă, ee → ê, oo → ô, ow → ơ, uw → ư, dd → đ. Dấu: s sắc, f huyền, r hỏi, x ngã, j nặng.",example:"Vieetj → Việt · hocj → học"},{title:"Sửa chữ",text:"Phím Backspace xoá chữ bên trái con trỏ. Phím Delete xoá chữ bên phải con trỏ. Phím Enter để xuống dòng, bắt đầu đoạn mới.",example:"⌫ trái · Delete phải · ↵ đoạn mới"},{title:"Định dạng và căn lề",text:"Chữ có thể in đậm, in nghiêng, gạch chân. Đoạn văn có thể căn trái, căn giữa, căn phải hoặc căn đều hai bên. Tiêu đề thường căn giữa.",example:"B: đậm · I: nghiêng · U: gạch chân · ≡ căn lề"}],practice:[{questions:[{id:"th4-soan-thao-van-ban-01",type:"mc",q:"Phím nào xoá chữ ở bên trái con trỏ soạn thảo?",explain:"Backspace xoá chữ bên trái con trỏ; Delete xoá chữ bên phải.",options:["Delete","Enter","Esc","Backspace"],answer:3},{id:"th4-soan-thao-van-ban-02",type:"mc",q:"Muốn xuống dòng để bắt đầu đoạn văn mới, em nhấn phím nào?",explain:"Nhấn Enter để bắt đầu đoạn mới.",options:["Backspace","Enter","Esc"],answer:1},{id:"th4-soan-thao-van-ban-03",type:"tf",q:'Theo kiểu gõ Telex, gõ "dd" sẽ được chữ "đ".',explain:"Đúng. Trong kiểu Telex, dd cho chữ đ.",answer:!0},{id:"th4-soan-thao-van-ban-04",type:"tf",q:'Theo kiểu gõ Telex, gõ chữ "f" ở cuối tiếng sẽ được dấu sắc.',explain:"Sai. Chữ f cho dấu huyền; chữ s mới cho dấu sắc.",answer:!1},{id:"th4-soan-thao-van-ban-05",type:"mc",q:"Tiêu đề bài văn thường được căn lề như thế nào?",explain:"Tiêu đề thường căn giữa cho cân đối.",options:["Căn giữa","Căn phải","Không căn lề"],answer:0},{id:"th4-soan-thao-van-ban-06",type:"tf",q:"Phím Delete xoá chữ ở bên phải con trỏ soạn thảo.",explain:"Đúng. Delete xoá chữ bên phải, Backspace xoá chữ bên trái.",answer:!0},{id:"th4-soan-thao-van-ban-07",type:"mc",q:"Vạch nhấp nháy trong phần mềm soạn thảo gọi là gì?",explain:"Con trỏ soạn thảo cho biết chữ gõ vào sẽ hiện ở đâu.",options:["Thanh cuộn","Siêu liên kết","Con trỏ soạn thảo"],answer:2},{id:"th4-soan-thao-van-ban-08",type:"tf",q:"Căn giữa là một cách định dạng chữ giống như in đậm.",explain:"Sai. Căn giữa là căn lề cho đoạn văn; in đậm mới là định dạng chữ.",answer:!1},{id:"th4-soan-thao-van-ban-09",type:"tf",q:"Phần mềm soạn thảo văn bản dùng để nghe nhạc.",explain:"Sai. Phần mềm soạn thảo dùng để gõ và trình bày văn bản.",answer:!1}]},{questions:[{id:"th4-soan-thao-van-ban-10",type:"match",q:"Ghép cách gõ Telex với chữ được tạo ra.",explain:"Đây là quy tắc gõ chữ có dấu mũ, dấu móc theo kiểu Telex.",pairs:[["aa","â"],["ow","ơ"],["uw","ư"],["ee","ê"]]},{id:"th4-soan-thao-van-ban-11",type:"match",q:"Ghép chữ gõ thêm với dấu thanh theo kiểu Telex.",explain:"Kiểu Telex: s sắc, f huyền, r hỏi, x ngã, j nặng.",pairs:[["s","Dấu sắc"],["f","Dấu huyền"],["r","Dấu hỏi"],["j","Dấu nặng"]]},{id:"th4-soan-thao-van-ban-12",type:"mc",q:'Theo kiểu Telex, gõ "hocj" sẽ được chữ gì?',explain:'Chữ j cho dấu nặng nên "hocj" thành "học".',options:["hóc","hộc","hòc","học"],answer:3},{id:"th4-soan-thao-van-ban-13",type:"mc",q:'Theo kiểu Telex, muốn gõ chữ "mẹ", em gõ thế nào?',explain:"Chữ j cho dấu nặng: mej thành mẹ.",options:["mes","mef","mer","mej"],answer:3},{id:"th4-soan-thao-van-ban-14",type:"tf",q:'Theo kiểu Telex, gõ "nhaf" sẽ được chữ "nhà".',explain:"Đúng. Chữ f cho dấu huyền.",answer:!0},{id:"th4-soan-thao-van-ban-15",type:"multi",q:"Những cách nào là định dạng chữ?",explain:"Căn giữa là căn lề cho đoạn văn, không phải định dạng chữ.",options:["Căn giữa","In đậm","In nghiêng","Gạch chân"],answers:[1,2,3]},{id:"th4-soan-thao-van-ban-16",type:"mc",q:"Muốn in đậm một từ đã gõ, trước tiên em phải làm gì?",explain:"Phải chọn từ trước rồi mới chọn lệnh in đậm.",options:["Xoá từ đó","Chọn từ đó","Nhấn phím Enter"],answer:1},{id:"th4-soan-thao-van-ban-17",type:"tf",q:"Căn đều hai bên làm cho hai mép đoạn văn đều thẳng hàng.",explain:"Đúng. Căn đều hai bên làm mép trái và mép phải đều thẳng.",answer:!0},{id:"th4-soan-thao-van-ban-18",type:"order",q:"Sắp xếp các bước làm tiêu đề in đậm và căn giữa.",explain:"Gõ chữ, chọn chữ rồi mới định dạng và căn lề.",items:["Gõ tiêu đề","Chọn dòng tiêu đề","Chọn lệnh in đậm","Chọn lệnh căn giữa"]}]},{questions:[{id:"th4-soan-thao-van-ban-19",type:"mc",q:'Theo kiểu Telex, muốn gõ chữ "Việt", em gõ thế nào?',explain:"ee cho ê, j cho dấu nặng: Vieetj thành Việt.",options:["Vietj","Vieets","Viet","Vieetj"],answer:3},{id:"th4-soan-thao-van-ban-20",type:"mc",q:'Theo kiểu Telex, muốn gõ chữ "đường", em gõ thế nào?',explain:"dd cho đ, uw và ow cho ư và ơ, f cho dấu huyền.",options:["duongf","dduongs","dduowng","dduwowngf"],answer:3},{id:"th4-soan-thao-van-ban-21",type:"tf",q:'Nam gõ "bàn" nhưng con trỏ ở ngay sau chữ "n". Nhấn Backspace một lần sẽ xoá chữ "n".',explain:"Đúng. Backspace xoá chữ ngay bên trái con trỏ.",answer:!0},{id:"th4-soan-thao-van-ban-22",type:"tf",q:"Hà muốn tên bài văn nằm giữa dòng. Hà chọn căn phải.",explain:"Sai. Muốn nằm giữa dòng thì chọn căn giữa.",answer:!1},{id:"th4-soan-thao-van-ban-23",type:"multi",q:"Chi làm thiệp mời sinh nhật. Những việc nào giúp thiệp đẹp, rõ ràng?",emoji:"🎂",explain:"Gạch chân mọi chữ làm thiệp rối, không nổi bật chỗ cần chú ý.",options:["Căn giữa dòng tiêu đề","In đậm tên người được mời","Gõ đúng dấu tiếng Việt","Gạch chân tất cả mọi chữ"],answers:[0,1,2]},{id:"th4-soan-thao-van-ban-24",type:"mc",q:'Minh gõ "sach" nhưng muốn được chữ "sách". Minh cần gõ thêm chữ nào ở cuối?',emoji:"📘",explain:"Chữ s cho dấu sắc: sachs thành sách.",options:["f","x","j","s"],answer:3},{id:"th4-soan-thao-van-ban-25",type:"mc",q:"Tùng gõ sai chữ ở giữa câu. Cách sửa hợp lí là gì?",explain:"Đưa con trỏ tới đúng chỗ để sửa, không cần gõ lại cả bài.",options:["Xoá cả bài rồi gõ lại từ đầu","Để nguyên như vậy, không cần sửa","Đưa con trỏ tới chỗ sai, xoá và gõ lại"],answer:2},{id:"th4-soan-thao-van-ban-26",type:"match",q:"Ghép điều muốn làm với lệnh phù hợp.",explain:"Mỗi việc dùng đúng một lệnh hoặc một phím.",pairs:[["Nhấn mạnh một từ","In đậm"],["Tên bài nằm giữa dòng","Căn giữa"],["Bắt đầu đoạn mới","Nhấn Enter"],["Xoá chữ bên phải con trỏ","Nhấn Delete"]]},{id:"th4-soan-thao-van-ban-27",type:"fill",q:'Điền chữ còn thiếu: Theo kiểu Telex, gõ "oo" sẽ được chữ … .',explain:"oo cho chữ ô.",answer:["ô","Ô"]}]}],challenge:{questions:[{id:"th4-soan-thao-van-ban-28",type:"mc",q:'Theo kiểu Telex, gõ "truwowngf" sẽ được chữ gì?',emoji:"🏫",explain:"uw thành ư, ow thành ơ, f thêm dấu huyền: trường.",options:["trương","trưởng","trướng","trường"],answer:3},{id:"th4-soan-thao-van-ban-29",type:"tf",q:'Theo kiểu Telex, chữ "x" gõ ở cuối tiếng cho dấu hỏi.',explain:"Sai. Chữ x cho dấu ngã; chữ r mới cho dấu hỏi.",answer:!1},{id:"th4-soan-thao-van-ban-19",type:"mc",q:'Theo kiểu Telex, muốn gõ chữ "Việt", em gõ thế nào?',explain:"ee cho ê, j cho dấu nặng: Vieetj thành Việt.",options:["Vietj","Vieets","Viet","Vieetj"],answer:3},{id:"th4-soan-thao-van-ban-20",type:"mc",q:'Theo kiểu Telex, muốn gõ chữ "đường", em gõ thế nào?',explain:"dd cho đ, uw và ow cho ư và ơ, f cho dấu huyền.",options:["duongf","dduongs","dduowng","dduwowngf"],answer:3},{id:"th4-soan-thao-van-ban-23",type:"multi",q:"Chi làm thiệp mời sinh nhật. Những việc nào giúp thiệp đẹp, rõ ràng?",emoji:"🎂",explain:"Gạch chân mọi chữ làm thiệp rối, không nổi bật chỗ cần chú ý.",options:["Căn giữa dòng tiêu đề","In đậm tên người được mời","Gõ đúng dấu tiếng Việt","Gạch chân tất cả mọi chữ"],answers:[0,1,2]},{id:"th4-soan-thao-van-ban-24",type:"mc",q:'Minh gõ "sach" nhưng muốn được chữ "sách". Minh cần gõ thêm chữ nào ở cuối?',emoji:"📘",explain:"Chữ s cho dấu sắc: sachs thành sách.",options:["f","x","j","s"],answer:3},{id:"th4-soan-thao-van-ban-14",type:"tf",q:'Theo kiểu Telex, gõ "nhaf" sẽ được chữ "nhà".',explain:"Đúng. Chữ f cho dấu huyền.",answer:!0}]},summary:["Phần mềm soạn thảo giúp gõ, sửa và trình bày văn bản.","Gõ tiếng Việt kiểu Telex: s sắc, f huyền, r hỏi, x ngã, j nặng.","Định dạng chữ: in đậm, in nghiêng, gạch chân; căn lề: trái, giữa, phải, đều hai bên."]}]},{id:"lap-trinh-truc-quan",title:"Giải quyết vấn đề với sự trợ giúp của máy tính",lessons:[{id:"th4-lam-quen-khoi-lenh",title:"Bài 15: Làm quen với lập trình khối lệnh",weeks:[27,30],learn:[{title:"Lập trình kéo thả",text:"Có phần mềm lập trình kéo thả khối lệnh như Scratch. Em kéo các khối lệnh và ghép chúng lại để tạo chương trình, không cần gõ lệnh.",example:"🧩 kéo · thả · ghép"},{title:"Nhân vật và sân khấu",text:"Nhân vật là hình chú mèo, con cá… thực hiện các lệnh. Sân khấu là nơi nhân vật xuất hiện và hoạt động, có phông nền phía sau.",example:"🐱 nhân vật · 🎭 sân khấu · 🏞️ phông nền"},{title:"Khu vực trên màn hình",text:"Khu vực khối lệnh chứa các khối lệnh xếp theo nhóm màu. Khu vực lập trình là nơi em kéo thả và ghép các khối lệnh.",example:"🧱 khối lệnh → 📋 khu vực lập trình"},{title:"Bắt đầu và dừng",text:"Khối lệnh sự kiện “khi bấm vào lá cờ xanh” đặt trên cùng. Bấm lá cờ xanh để chạy chương trình, bấm nút đỏ để dừng. Các lệnh chạy lần lượt từ trên xuống dưới.",example:"🟢🚩 chạy · 🔴 dừng"}],practice:[{questions:[{id:"th4-lam-quen-khoi-lenh-01",type:"mc",q:"Trong lập trình kéo thả, em tạo chương trình bằng cách nào?",emoji:"🧩",explain:"Phần mềm lập trình kéo thả cho em ghép các khối lệnh lại với nhau.",options:["Kéo thả và ghép các khối lệnh","Vẽ tranh bằng bút chì lên giấy","Gõ thật nhanh trên bàn phím"],answer:0},{id:"th4-lam-quen-khoi-lenh-02",type:"mc",q:"Nơi nhân vật xuất hiện và hoạt động gọi là gì?",emoji:"🎭",explain:"Sân khấu là nơi nhân vật hoạt động.",options:["Thùng rác","Ô tìm kiếm","Thanh cuộn","Sân khấu"],answer:3},{id:"th4-lam-quen-khoi-lenh-03",type:"tf",q:"Nhân vật là đối tượng thực hiện các lệnh trong chương trình.",emoji:"🐱",explain:"Đúng. Ví dụ chú mèo di chuyển, nói theo lệnh em ghép.",answer:!0},{id:"th4-lam-quen-khoi-lenh-04",type:"mc",q:"Muốn chạy chương trình, em bấm vào đâu?",emoji:"🚩",explain:"Bấm lá cờ xanh để chương trình bắt đầu chạy.",options:["Nút màu đỏ","Lá cờ xanh","Phím Delete"],answer:1},{id:"th4-lam-quen-khoi-lenh-05",type:"tf",q:"Bấm nút màu đỏ để chạy chương trình.",explain:"Sai. Nút màu đỏ dùng để dừng chương trình; lá cờ xanh để chạy.",answer:!1},{id:"th4-lam-quen-khoi-lenh-06",type:"tf",q:"Các khối lệnh ghép với nhau chạy lần lượt từ trên xuống dưới.",explain:"Đúng. Máy tính làm theo thứ tự các khối lệnh từ trên xuống.",answer:!0},{id:"th4-lam-quen-khoi-lenh-07",type:"mc",q:"Hình ảnh phía sau sân khấu gọi là gì?",emoji:"🏞️",explain:"Phông nền là hình nền của sân khấu, như bãi biển, khu vườn.",options:["Nhân vật","Khối lệnh","Phông nền"],answer:2},{id:"th4-lam-quen-khoi-lenh-08",type:"tf",q:"Khi lập trình kéo thả, em phải gõ từng chữ của câu lệnh.",explain:"Sai. Em chỉ cần kéo thả các khối lệnh có sẵn.",answer:!1},{id:"th4-lam-quen-khoi-lenh-09",type:"mc",q:"Nơi em kéo thả và ghép các khối lệnh gọi là gì?",explain:"Khu vực lập trình là nơi ghép các khối lệnh thành chương trình.",options:["Sân khấu","Khu vực lập trình","Phông nền"],answer:1}]},{questions:[{id:"th4-lam-quen-khoi-lenh-10",type:"match",q:"Ghép mỗi phần với việc của nó.",explain:"Mỗi phần trên màn hình có một việc riêng.",pairs:[["Lá cờ xanh","Bắt đầu chạy chương trình"],["Nút màu đỏ","Dừng chương trình"],["Sân khấu","Nơi nhân vật hoạt động"],["Khu vực khối lệnh","Nơi chứa các khối lệnh"]]},{id:"th4-lam-quen-khoi-lenh-11",type:"mc",q:'Khối lệnh "khi bấm vào lá cờ xanh" thường đặt ở đâu trong chương trình?',explain:"Khối sự kiện này đặt trên cùng để bắt đầu chương trình.",options:["Trên cùng","Dưới cùng","Ở giữa các lệnh khác"],answer:0},{id:"th4-lam-quen-khoi-lenh-12",type:"order",q:'Sắp xếp các bước tạo chương trình cho nhân vật nói "Xin chào".',explain:"Ghép khối sự kiện trước, rồi khối lệnh, rồi chạy chương trình.",items:['Kéo khối "khi bấm vào lá cờ xanh" vào khu vực lập trình','Kéo khối "nói Xin chào" ghép bên dưới',"Bấm lá cờ xanh","Xem nhân vật nói trên sân khấu"]},{id:"th4-lam-quen-khoi-lenh-13",type:"tf",q:"Mỗi chương trình chỉ được có đúng một khối lệnh.",explain:"Sai. Một chương trình có thể có nhiều khối lệnh ghép nối với nhau.",answer:!1},{id:"th4-lam-quen-khoi-lenh-14",type:"tf",q:'Nếu chưa ghép khối "khi bấm vào lá cờ xanh" ở trên cùng, bấm lá cờ xanh vẫn chắc chắn chạy các lệnh đó.',explain:"Sai. Cần khối sự kiện này ở trên cùng thì bấm lá cờ xanh mới chạy các lệnh bên dưới.",answer:!1},{id:"th4-lam-quen-khoi-lenh-15",type:"mc",q:'Chương trình: khi bấm lá cờ xanh, nói "Chào bạn" trong 2 giây, rồi nói "Tạm biệt" trong 2 giây. Nhân vật nói câu nào trước?',explain:'Lệnh chạy từ trên xuống nên "Chào bạn" được nói trước.',options:["Tạm biệt","Chào bạn","Nói cả hai cùng lúc"],answer:1},{id:"th4-lam-quen-khoi-lenh-16",type:"multi",q:"Những gì có thể thấy trên sân khấu?",explain:"Sân khấu có nhân vật, phông nền và lời nhân vật nói.",options:["Nhân vật","Phông nền","Lời nói của nhân vật","Bàn phím thật"],answers:[0,1,2]},{id:"th4-lam-quen-khoi-lenh-17",type:"mc",q:"Các khối lệnh trong khu vực khối lệnh được xếp như thế nào?",explain:"Các khối lệnh được chia nhóm theo màu để dễ tìm.",options:["Theo nhóm, mỗi nhóm một màu","Lộn xộn, không có thứ tự","Theo tên người dùng máy"],answer:0},{id:"th4-lam-quen-khoi-lenh-18",type:"tf",q:"Có thể đổi phông nền cho sân khấu, ví dụ chọn phông nền bãi biển.",emoji:"🏖️",explain:"Đúng. Em có thể chọn phông nền phù hợp với câu chuyện.",answer:!0}]},{questions:[{id:"th4-lam-quen-khoi-lenh-19",type:"mc",q:'An ghép khối "nói Xin chào" nhưng bấm lá cờ xanh không thấy gì. An có thể đã quên điều gì?',explain:"Cần khối sự kiện bấm lá cờ xanh ở trên cùng để chạy.",options:["Bật loa của máy tính thật to lên","Đổi tên tệp chương trình cho ngắn hơn",'Ghép khối "khi bấm vào lá cờ xanh" ở trên'],answer:2},{id:"th4-lam-quen-khoi-lenh-20",type:"mc",q:"Bình muốn kể chuyện chú cá dưới biển. Bình nên chọn gì?",emoji:"🐠",explain:"Nhân vật và phông nền nên hợp với câu chuyện.",options:["Nhân vật con cá và phông nền dưới biển","Nhân vật con cá và phông nền sa mạc","Nhân vật con mèo và phông nền vũ trụ"],answer:0},{id:"th4-lam-quen-khoi-lenh-21",type:"tf",q:"Chương trình đang chạy mà Chi muốn dừng lại. Chi bấm nút màu đỏ.",explain:"Đúng. Nút màu đỏ dùng để dừng chương trình.",answer:!0},{id:"th4-lam-quen-khoi-lenh-22",type:"tf",q:'Dũng đặt khối "nói Tạm biệt" lên trên khối "nói Xin chào". Nhân vật sẽ nói "Xin chào" trước.',explain:'Sai. Lệnh chạy từ trên xuống nên nhân vật nói "Tạm biệt" trước.',answer:!1},{id:"th4-lam-quen-khoi-lenh-23",type:"order",q:"Hà muốn nhân vật chào rồi giới thiệu tên. Sắp xếp các khối lệnh.",explain:"Khối sự kiện ở trên cùng, sau đó các lệnh theo thứ tự muốn nói.",items:["khi bấm vào lá cờ xanh",'nói "Xin chào" trong 2 giây','nói "Mình là Mèo Mướp" trong 2 giây']},{id:"th4-lam-quen-khoi-lenh-24",type:"mc",q:'Ngọc muốn nhân vật nói "Chúc mừng sinh nhật". Ngọc tìm khối lệnh "nói" ở đâu?',emoji:"🎉",explain:"Mọi khối lệnh nằm trong khu vực khối lệnh.",options:["Phông nền","Khu vực khối lệnh","Thùng rác"],answer:1},{id:"th4-lam-quen-khoi-lenh-25",type:"multi",q:"Thảo làm chương trình chú mèo chào bạn. Những việc nào cần làm?",emoji:"🐱",explain:"Không thể xoá sân khấu; nhân vật cần sân khấu để hoạt động.",options:['Ghép khối "nói Xin chào" bên dưới',"Xoá sân khấu đi","Chọn nhân vật chú mèo",'Ghép khối "khi bấm vào lá cờ xanh"'],answers:[0,2,3]},{id:"th4-lam-quen-khoi-lenh-26",type:"tf",q:"Lập trình giúp em ra lệnh cho máy tính làm việc theo ý mình.",explain:"Đúng. Chương trình là dãy lệnh máy tính làm theo.",answer:!0},{id:"th4-lam-quen-khoi-lenh-27",type:"fill",q:"Điền từ còn thiếu: Bấm lá cờ … để chương trình bắt đầu chạy.",explain:"Lá cờ xanh dùng để bắt đầu chạy chương trình.",answer:["xanh"]}]}],challenge:{questions:[{id:"th4-lam-quen-khoi-lenh-28",type:"mc",q:'Chương trình: khi bấm lá cờ xanh, nói "Một" trong 1 giây, nói "Hai" trong 1 giây, nói "Ba" trong 1 giây. Nhân vật nói câu cuối cùng là gì?',explain:'Lệnh chạy từ trên xuống, lệnh cuối là nói "Ba".',options:["Một","Hai","Ba"],answer:2},{id:"th4-lam-quen-khoi-lenh-29",type:"tf",q:"Thay đổi thứ tự các khối lệnh có thể làm chương trình chạy khác đi.",explain:"Đúng. Máy tính làm theo đúng thứ tự các khối lệnh.",answer:!0},{id:"th4-lam-quen-khoi-lenh-19",type:"mc",q:'An ghép khối "nói Xin chào" nhưng bấm lá cờ xanh không thấy gì. An có thể đã quên điều gì?',explain:"Cần khối sự kiện bấm lá cờ xanh ở trên cùng để chạy.",options:["Bật loa của máy tính thật to lên","Đổi tên tệp chương trình cho ngắn hơn",'Ghép khối "khi bấm vào lá cờ xanh" ở trên'],answer:2},{id:"th4-lam-quen-khoi-lenh-22",type:"tf",q:'Dũng đặt khối "nói Tạm biệt" lên trên khối "nói Xin chào". Nhân vật sẽ nói "Xin chào" trước.',explain:'Sai. Lệnh chạy từ trên xuống nên nhân vật nói "Tạm biệt" trước.',answer:!1},{id:"th4-lam-quen-khoi-lenh-23",type:"order",q:"Hà muốn nhân vật chào rồi giới thiệu tên. Sắp xếp các khối lệnh.",explain:"Khối sự kiện ở trên cùng, sau đó các lệnh theo thứ tự muốn nói.",items:["khi bấm vào lá cờ xanh",'nói "Xin chào" trong 2 giây','nói "Mình là Mèo Mướp" trong 2 giây']},{id:"th4-lam-quen-khoi-lenh-24",type:"mc",q:'Ngọc muốn nhân vật nói "Chúc mừng sinh nhật". Ngọc tìm khối lệnh "nói" ở đâu?',emoji:"🎉",explain:"Mọi khối lệnh nằm trong khu vực khối lệnh.",options:["Phông nền","Khu vực khối lệnh","Thùng rác"],answer:1},{id:"th4-lam-quen-khoi-lenh-14",type:"tf",q:'Nếu chưa ghép khối "khi bấm vào lá cờ xanh" ở trên cùng, bấm lá cờ xanh vẫn chắc chắn chạy các lệnh đó.',explain:"Sai. Cần khối sự kiện này ở trên cùng thì bấm lá cờ xanh mới chạy các lệnh bên dưới.",answer:!1}]},summary:["Lập trình kéo thả là ghép các khối lệnh để tạo chương trình.","Nhân vật hoạt động trên sân khấu, phía sau là phông nền.","Bấm lá cờ xanh để chạy, nút đỏ để dừng; lệnh chạy từ trên xuống."]},{id:"th4-di-chuyen-va-lap",title:"Bài 16: Lệnh di chuyển và lệnh lặp",weeks:[31,35],learn:[{title:"Lệnh di chuyển",text:"Khối “di chuyển 10 bước” làm nhân vật đi về phía trước 10 bước. Muốn đi xa hơn, em thay số bước lớn hơn.",example:"🐱 ➡️ ➡️"},{title:"Lệnh xoay",text:"Khối “xoay 90 độ” làm nhân vật quay một góc vuông. Quay đủ bốn lần 90 độ thì nhân vật quay về hướng cũ.",example:"↻ 90°"},{title:"Lệnh lặp",text:"Khối “lặp lại 4 lần” làm các lệnh bên trong nó chạy 4 lần. Dùng lệnh lặp giúp chương trình ngắn gọn hơn.",example:"🔁 lặp lại 4 lần"},{title:"Ví dụ vẽ hình vuông",text:"Lặp lại 4 lần: di chuyển 100 bước, xoay 90 độ. Nhân vật đi đúng bốn cạnh của một hình vuông.",example:"🔁 ×4: ➡️ 100 · ↻ 90°  =  ⬜"}],practice:[{questions:[{id:"th4-di-chuyen-va-lap-01",type:"mc",q:'Khối "di chuyển 10 bước" làm nhân vật làm gì?',emoji:"➡️",explain:"Lệnh di chuyển làm nhân vật đi về phía trước.",options:["Đi về phía trước 10 bước",'Nói "10" trong 2 giây',"Đổi sang phông nền thứ 10"],answer:0},{id:"th4-di-chuyen-va-lap-02",type:"mc",q:"Khối lệnh nào làm các lệnh bên trong chạy nhiều lần?",emoji:"🔁",explain:"Lệnh lặp lại làm các lệnh bên trong chạy nhiều lần.",options:["Di chuyển","Nói","Đổi phông nền","Lặp lại"],answer:3},{id:"th4-di-chuyen-va-lap-03",type:"tf",q:'Khối "lặp lại 3 lần" làm các lệnh bên trong chạy 3 lần.',explain:"Đúng. Số trong khối lặp cho biết chạy bao nhiêu lần.",answer:!0},{id:"th4-di-chuyen-va-lap-04",type:"tf",q:'Khối "xoay 90 độ" làm nhân vật đi về phía trước 90 bước.',explain:"Sai. Khối xoay làm nhân vật quay, không làm nhân vật đi.",answer:!1},{id:"th4-di-chuyen-va-lap-05",type:"mc",q:'Muốn nhân vật đi xa hơn, em sửa khối "di chuyển 10 bước" thế nào?',explain:"Số bước lớn hơn thì nhân vật đi xa hơn.",options:["Thay 10 bằng số nhỏ hơn","Thay 10 bằng số lớn hơn","Xoá khối di chuyển đi"],answer:1},{id:"th4-di-chuyen-va-lap-06",type:"tf",q:"Dùng lệnh lặp làm chương trình dài hơn và khó sửa hơn.",explain:"Sai. Lệnh lặp giúp chương trình ngắn gọn, dễ sửa hơn.",answer:!1},{id:"th4-di-chuyen-va-lap-07",type:"number",q:'Nhân vật chạy khối "di chuyển 10 bước" hai lần liên tiếp. Nhân vật đi được tất cả bao nhiêu bước?',explain:"Mỗi lần 10 bước, hai lần là 10 + 10 = 20 bước.",answer:20,unit:"bước"},{id:"th4-di-chuyen-va-lap-08",type:"tf",q:'Khối "xoay 90 độ" làm nhân vật quay một góc vuông.',emoji:"↻",explain:"Đúng. 90 độ là một góc vuông.",answer:!0},{id:"th4-di-chuyen-va-lap-09",type:"tf",q:"Các lệnh nằm bên trong khối lặp chỉ chạy đúng một lần.",explain:"Sai. Các lệnh bên trong khối lặp chạy nhiều lần, đúng bằng số lần ghi trong khối.",answer:!1}]},{questions:[{id:"th4-di-chuyen-va-lap-10",type:"number",q:"Chương trình: lặp lại 4 lần: di chuyển 10 bước. Nhân vật đi tất cả bao nhiêu bước?",explain:"Lặp 4 lần, mỗi lần 10 bước: 4 × 10 = 40 bước.",answer:40,unit:"bước"},{id:"th4-di-chuyen-va-lap-11",type:"number",q:"Chương trình: lặp lại 3 lần: di chuyển 20 bước. Nhân vật đi tất cả bao nhiêu bước?",explain:"Lặp 3 lần, mỗi lần 20 bước: 3 × 20 = 60 bước.",answer:60,unit:"bước"},{id:"th4-di-chuyen-va-lap-12",type:"mc",q:'Chương trình nào giống "lặp lại 3 lần: di chuyển 10 bước"?',explain:"Lặp 3 lần một lệnh giống ghép lệnh đó 3 lần liền nhau.",options:['Một khối "di chuyển 3 bước" đứng riêng','Một khối "xoay 30 độ" đứng riêng','Ba khối "di chuyển 10 bước" ghép liền nhau'],answer:2},{id:"th4-di-chuyen-va-lap-13",type:"number",q:"Nhân vật xoay 90 độ bao nhiêu lần thì quay về hướng ban đầu?",explain:"Bốn lần 90 độ là 360 độ, đủ một vòng.",answer:4,unit:"lần"},{id:"th4-di-chuyen-va-lap-14",type:"tf",q:'Chương trình "lặp lại 2 lần: di chuyển 50 bước" làm nhân vật đi 100 bước.',explain:"Đúng. 2 × 50 = 100 bước.",answer:!0},{id:"th4-di-chuyen-va-lap-15",type:"tf",q:'Chương trình "lặp lại 5 lần: di chuyển 10 bước" làm nhân vật đi 15 bước.',explain:"Sai. 5 × 10 = 50 bước.",answer:!1},{id:"th4-di-chuyen-va-lap-16",type:"match",q:"Ghép khối lệnh với việc nó làm.",explain:"Mỗi khối lệnh có một tác dụng riêng.",pairs:[["di chuyển 10 bước","Nhân vật đi về phía trước"],["xoay 90 độ","Nhân vật quay một góc vuông"],["lặp lại 4 lần","Chạy các lệnh bên trong 4 lần"],["khi bấm vào lá cờ xanh","Bắt đầu chương trình"]]},{id:"th4-di-chuyen-va-lap-17",type:"order",q:"Sắp xếp chương trình cho nhân vật đi 30 bước bằng lệnh lặp.",explain:"Khối sự kiện trên cùng, rồi khối lặp, lệnh di chuyển nằm bên trong.",items:["khi bấm vào lá cờ xanh","lặp lại 3 lần","di chuyển 10 bước (nằm trong khối lặp)"]},{id:"th4-di-chuyen-va-lap-18",type:"mc",q:"Vì sao nên dùng lệnh lặp thay vì ghép 10 khối giống nhau?",explain:"Lệnh lặp giúp chương trình ngắn gọn và dễ sửa.",options:["Nhân vật trên sân khấu sẽ to hơn","Phông nền sân khấu sẽ đẹp hơn","Chương trình ngắn gọn, dễ sửa hơn"],answer:2}]},{questions:[{id:"th4-di-chuyen-va-lap-19",type:"mc",q:"Chương trình: lặp lại 4 lần: di chuyển 100 bước, xoay 90 độ. Nhân vật đi theo hình gì?",emoji:"⬜",explain:"Bốn cạnh bằng nhau, bốn góc vuông là hình vuông.",options:["Hình tròn","Đường thẳng","Hình tam giác","Hình vuông"],answer:3},{id:"th4-di-chuyen-va-lap-20",type:"number",q:"Chương trình: lặp lại 4 lần: di chuyển 100 bước, xoay 90 độ. Nhân vật đi tất cả bao nhiêu bước?",explain:"Bốn cạnh, mỗi cạnh 100 bước: 4 × 100 = 400 bước.",answer:400,unit:"bước"},{id:"th4-di-chuyen-va-lap-21",type:"mc",q:"Lan muốn chú mèo đi 50 bước bằng lệnh lặp, mỗi lần 10 bước. Lan cần lặp bao nhiêu lần?",emoji:"🐱",explain:"5 × 10 = 50 bước.",options:["10 lần","50 lần","4 lần","5 lần"],answer:3},{id:"th4-di-chuyen-va-lap-22",type:"tf",q:"Minh viết: lặp lại 2 lần: di chuyển 10 bước, xoay 90 độ. Sau đó nhân vật quay về đúng hướng ban đầu.",explain:"Sai. Xoay 2 lần 90 độ mới được nửa vòng, nhân vật quay ngược hướng ban đầu.",answer:!1},{id:"th4-di-chuyen-va-lap-23",type:"tf",q:'Nam muốn nhân vật nhảy 3 lần. Nam đặt các lệnh nhảy bên trong khối "lặp lại 3 lần".',explain:"Đúng. Các lệnh bên trong khối lặp sẽ chạy 3 lần.",answer:!0},{id:"th4-di-chuyen-va-lap-24",type:"mc",q:"Chương trình của Vy: lặp lại 4 lần: di chuyển 50 bước, xoay 90 độ. Vy muốn hình vuông to hơn. Vy sửa thế nào?",explain:"Số bước di chuyển là độ dài cạnh, tăng số bước thì hình to hơn.",options:["Tăng số bước di chuyển","Tăng số lần lặp lên 8","Xoá lệnh xoay"],answer:0},{id:"th4-di-chuyen-va-lap-25",type:"number",q:'Phúc muốn nhân vật đi 80 bước. Phúc dùng "lặp lại 4 lần: di chuyển … bước". Mỗi lần nhân vật cần đi bao nhiêu bước?',explain:"80 : 4 = 20 bước mỗi lần.",answer:20,unit:"bước"},{id:"th4-di-chuyen-va-lap-26",type:"multi",q:"Khoa muốn nhân vật đi đúng 40 bước. Những chương trình nào đúng?",explain:"Ba cách đầu đều ra 40 bước; cách cuối là 160 bước.",options:["lặp lại 2 lần: di chuyển 20 bước","di chuyển 40 bước","lặp lại 4 lần: di chuyển 40 bước","lặp lại 4 lần: di chuyển 10 bước"],answers:[0,1,3]},{id:"th4-di-chuyen-va-lap-27",type:"order",q:"Thảo muốn nhân vật đi một vòng hình vuông. Sắp xếp các khối lệnh.",explain:"Trong khối lặp: đi một cạnh rồi xoay góc vuông.",items:["khi bấm vào lá cờ xanh","lặp lại 4 lần","di chuyển 100 bước (trong khối lặp)","xoay 90 độ (trong khối lặp)"]}]}],challenge:{questions:[{id:"th4-di-chuyen-va-lap-28",type:"number",q:"Chương trình: lặp lại 3 lần: di chuyển 10 bước. Sau đó thêm khối di chuyển 5 bước. Nhân vật đi tất cả bao nhiêu bước?",explain:"3 × 10 = 30 bước, thêm 5 bước là 35 bước.",answer:35,unit:"bước"},{id:"th4-di-chuyen-va-lap-29",type:"tf",q:"Lệnh lặp và lệnh di chuyển có thể dùng cùng nhau để vẽ hình.",explain:"Đúng. Ví dụ lặp 4 lần đi và xoay 90 độ vẽ được hình vuông.",answer:!0},{id:"th4-di-chuyen-va-lap-19",type:"mc",q:"Chương trình: lặp lại 4 lần: di chuyển 100 bước, xoay 90 độ. Nhân vật đi theo hình gì?",emoji:"⬜",explain:"Bốn cạnh bằng nhau, bốn góc vuông là hình vuông.",options:["Hình tròn","Đường thẳng","Hình tam giác","Hình vuông"],answer:3},{id:"th4-di-chuyen-va-lap-20",type:"number",q:"Chương trình: lặp lại 4 lần: di chuyển 100 bước, xoay 90 độ. Nhân vật đi tất cả bao nhiêu bước?",explain:"Bốn cạnh, mỗi cạnh 100 bước: 4 × 100 = 400 bước.",answer:400,unit:"bước"},{id:"th4-di-chuyen-va-lap-22",type:"tf",q:"Minh viết: lặp lại 2 lần: di chuyển 10 bước, xoay 90 độ. Sau đó nhân vật quay về đúng hướng ban đầu.",explain:"Sai. Xoay 2 lần 90 độ mới được nửa vòng, nhân vật quay ngược hướng ban đầu.",answer:!1},{id:"th4-di-chuyen-va-lap-25",type:"number",q:'Phúc muốn nhân vật đi 80 bước. Phúc dùng "lặp lại 4 lần: di chuyển … bước". Mỗi lần nhân vật cần đi bao nhiêu bước?',explain:"80 : 4 = 20 bước mỗi lần.",answer:20,unit:"bước"},{id:"th4-di-chuyen-va-lap-26",type:"multi",q:"Khoa muốn nhân vật đi đúng 40 bước. Những chương trình nào đúng?",explain:"Ba cách đầu đều ra 40 bước; cách cuối là 160 bước.",options:["lặp lại 2 lần: di chuyển 20 bước","di chuyển 40 bước","lặp lại 4 lần: di chuyển 40 bước","lặp lại 4 lần: di chuyển 10 bước"],answers:[0,1,3]}]},summary:["Lệnh di chuyển làm nhân vật đi; lệnh xoay làm nhân vật quay.","Lệnh lặp làm các lệnh bên trong chạy nhiều lần, chương trình ngắn gọn hơn.","Lặp 4 lần đi một cạnh rồi xoay 90 độ sẽ đi được hình vuông."]}]}],g={grade:4,subject:n,title:h,review:t,topics:i};export{g as default,c as grade,t as review,n as subject,h as title,i as topics};
